window.__APOENA_V4_PARTES=window.__APOENA_V4_PARTES||[];window.__APOENA_V4_PARTES[22]="\"},{\"id\":\"destino\",\"numero\":52,\"nome\":\"Poção do Destino\",\"categoria\":\"ESPECIAL\",\"descricao\":\"Efeito raro de evento, ainda não definido (conceito).\",\"arquivo\":\"52_destino.png\",\"estado\":\"conceito\",\"observacao\":\"Somente referência visual: sem venda ou efeito ativado\",\"base64\":\"\"}];\nconst GODOT_CREATOR_EXECUTOR=\"extends RefCounted\\n## APOENA GAME CREATOR v2: interpretador seguro de fluxos configurados.\\n## Opera sobre uma copia de estado (Dictionary). Nao altera automaticamente o jogo real.\\n## Integre explicitamente a camada de combate/inventario antes de usar em producao.\\n\\nstatic func carregar_fluxos(caminho: String = \\\"res://dados/apoena_fluxos.json\\\") -> Dictionary:\\n    if not caminho.begins_with(\\\"res://dados/\\\") or not FileAccess.file_exists(caminho):\\n        return {}\\n    var parser := JSON.new()\\n    if parser.parse(FileAccess.get_file_as_string(caminho)) != OK:\\n        return {}\\n    if typeof(parser.data) != TYPE_DICTIONARY:\\n        return {}\\n    var pacote: Dictionary = parser.data\\n    if str(pacote.get(\\\"schema\\\", \\\"\\\")) != \\\"apoena.flows.v1\\\":\\n        return {}\\n    var saida: Dictionary = {}\\n    for valor in pacote.get(\\\"flows\\\", []):\\n        if typeof(valor) == TYPE_DICTIONARY and valor.has(\\\"id\\\"):\\n            saida[str(valor[\\\"id\\\"])] = valor\\n    return saida\\n\\nstatic func simular(ficha: Dictionary, estado: Dictionary) -> Dictionary:\\n    # Impede que JSON execute codigos dinamicos: os tipos suportados sao fixos.\\n    var novo: Dictionary = estado.duplicate(true)\\n    var mensagens: Array[String] = []\\n    var bag: Dictionary = novo.get(\\\"bag\\\", {})\\n    var blocos: Array = ficha.get(\\\"blocks\\\", [])\\n    if blocos.size() > 60:\\n        return {\\\"ok\\\": false, \\\"erro\\\": \\\"Fluxo com mais de 60 blocos\\\"}\\n    for bloco in blocos:\\n        if typeof(bloco) != TYPE_DICTIONARY:\\n            return {\\\"ok\\\": false, \\\"erro\\\": \\\"Bloco invalido\\\"}\\n        var tipo := str(bloco.get(\\\"type\\\", \\\"\\\"))\\n        var valor: float = maxf(0.0, float(bloco.get(\\\"valor\\\", 0.0)))\\n        match tipo:\\n            \\\"mensagem\\\":\\n                mensagens.append(str(bloco.get(\\\"texto\\\", \\\"\\\")))\\n            \\\"curar_hp\\\":\\n                var limite_hp: float = float(novo.get(\\\"maxhp\\\", 0.0))\\n                novo[\\\"hp\\\"] = minf(limite_hp, float(novo.get(\\\"hp\\\", 0.0)) + limite_hp * valor / 100.0)\\n            \\\"curar_aurium\\\":\\n                var limite_aurium: float = float(novo.get(\\\"maxaurium\\\", 0.0))\\n                novo[\\\"aurium\\\"] = minf(limite_aurium, float(novo.get(\\\"aurium\\\", 0.0)) + limite_aurium * valor / 100.0)\\n            \\\"dar_ouro\\\":\\n                novo[\\\"gold\\\"] = float(novo.get(\\\"gold\\\", 0)) + valor\\n            \\\"gastar_ouro\\\":\\n                if float(novo.get(\\\"gold\\\", 0)) < valor:\\n                    return {\\\"ok\\\": false, \\\"erro\\\": \\\"Ouro insuficiente\\\"}\\n                novo[\\\"gold\\\"] = float(novo.get(\\\"gold\\\", 0)) - valor\\n            \\\"requer_nivel\\\":\\n                if float(novo.get(\\\"level\\\", 0)) < valor:\\n                    return {\\\"ok\\\": false, \\\"erro\\\": \\\"Nivel insuficiente\\\"}\\n            \\\"requer_item\\\", \\\"retirar_item\\\":\\n                var id: String = str(bloco.get(\\\"itemId\\\", \\\"\\\"))\\n                if int(bag.get(id, 0)) < 1:\\n                    return {\\\"ok\\\": false, \\\"erro\\\": \\\"Item ausente: \\\" + id}\\n                if tipo == \\\"retirar_item\\\":\\n                    bag[id] = int(bag[id]) - 1\\n            \\\"dar_item\\\":\\n                var id: String = str(bloco.get(\\\"itemId\\\", \\\"\\\"))\\n                if id.is_empty():\\n                    return {\\\"ok\\\": false, \\\"erro\\\": \\\"ID de item ausente\\\"}\\n                bag[id] = int(bag.get(id, 0)) + 1\\n            \\\"ir_tela\\\":\\n                novo[\\\"tela_solicitada\\\"] = str(bloco.get(\\\"destino\\\", \\\"\\\"))\\n            \\\"bonus_temporario\\\":\\n                mensagens.append(\\\"Bonus temporario pendente de integrar com atributos reais\\\")\\n            \\\"efeito_visual\\\":\\n                mensagens.append(\\\"Efeito visual pendente de vincular ao motor\\\")\\n            _:\\n                return {\\\"ok\\\": false, \\\"erro\\\": \\\"Bloco desconhecido: \\\" + tipo}\\n    novo[\\\"bag\\\"] = bag\\n    return {\\\"ok\\\": true, \\\"estado\\\": novo, \\\"mensagens\\\": mensagens}\\n\";\nconst GODOT_CREATOR_CONNECTOR=\"extends Node\\n## Conector de sinais do layout exportado. Acoes reais devem ser mapeadas\\n## explicitamente em cada cena. Nunca executa codigo arbitrario do JSON.\\nsignal aviso(mensagem: String)\\nsignal abrir_inventario_solicitado()\\nsignal acao_jogo_solicitada(identificador: String)\\n\\n@export var destinos_cenas: Dictionary = {\\n    \\\"iniciar_jogo\\\": \\\"\\\",\\n    \\\"selecionar_heroi\\\": \\\"\\\",\\n    \\\"abrir_configuracoes\\\": \\\"\\\",\\n    \\\"abrir_inventario\\\": \\\"\\\",\\n    \\\"abrir_laboratorio\\\": \\\"\\\",\\n    \\\"abrir_forja\\\": \\\"\\\",\\n    \\\"abrir_cristais\\\": \\\"\\\",\\n    \\\"abrir_loja\\\": \\\"\\\",\\n    \\\"abrir_receitas\\\": \\\"\\\",\\n    \\\"voltar\\\": \\\"\\\",\\n    \\\"fechar_inventario\\\": \\\"\\\"\\n}\\nconst ACOES_DADOS: Array[String] = [\\n    \\\"comprar_item\\\", \\\"vender_item\\\", \\\"usar_item\\\", \\\"equipar_item\\\",\\n    \\\"preparar_pocao\\\", \\\"forjar_item\\\", \\\"exibir_mensagem\\\"\\n]\\n\\nfunc processar_acao(identificador: String) -> void:\\n    if destinos_cenas.has(identificador):\\n        var caminho: String = str(destinos_cenas.get(identificador, \\\"\\\"))\\n        if not caminho.begins_with(\\\"res://cenas/\\\") or not caminho.ends_with(\\\".tscn\\\"):\\n            aviso.emit(\\\"Configure no Inspector a cena do botao: \\\" + identificador)\\n            return\\n        if not ResourceLoader.exists(caminho):\\n            aviso.emit(\\\"Cena ainda nao existe: \\\" + caminho)\\n            return\\n        get_tree().change_scene_to_file(caminho)\\n        return\\n    if identificador in ACOES_DADOS:\\n        # O jogo deve lidar com as regras existentes de economia, inventario e combate.\\n        acao_jogo_solicitada.emit(identificador)\\n        return\\n    aviso.emit(\\\"Acao nao configurada no motor: \\\" + identificador)\\n\";\nconst GODOT_CREATOR_PREVIA=\"extends Control\\n## Cena de teste: carrega menus exportados, aceita cliques e testa fluxos.\\n## NAO altera vida, inventario ou progressao do jogo real.\\nconst LEITOR_LAYOUT = preload(\\\"res://scripts/ui/layout_json_agar.gd\\\")\\nconst EXECUTOR = preload(\\\"res://scripts/sistemas/apoena_game_creator_executor.gd\\\")\\nconst TELA_POR_ACAO = {\\n    \\\"abrir_inventario\\\": \\\"inventario\\\",\\n    \\\"fechar_inventario\\\": \\\"menu_principal\\\",\\n    \\\"abrir_laboratorio\\\": \\\"laboratorio\\\",\\n    \\\"abrir_forja\\\": \\\"forja\\\",\\n    \\\"abrir_cristais\\\": \\\"cristais\\\",\\n    \\\"abrir_loja\\\": \\\"loja\\\",\\n    \\\"abrir_receitas\\\": \\\"receitas\\\",\\n    \\\"voltar\\\": \\\"menu_principal\\\"\\n}\\nvar _quadro: Control\\nvar _status: Label\\nvar _estado: Dictionary = {\\n    \\\"hp\\\": 500.0, \\\"maxhp\\\": 1000.0,\\n    \\\"aurium\\\": 50.0, \\\"maxaurium\\\": 100.0,\\n    \\\"gold\\\": 250.0, \\\"level\\\": 1, \\\"bag\\\": {}\\n}\\n\\nfunc _ready() -> void:\\n    set_anchors_and_offsets_preset(Control.PRESET_FULL_RECT)\\n    _quadro = LEITOR_LAYOUT.new()\\n    _quadro.arquivo_layout = \\\"res://layouts/menu_principal.json\\\"\\n    add_child(_quadro)\\n    _quadro.set_anchors_and_offsets_preset(Control.PRESET_FULL_RECT)\\n    _quadro.acao_solicitada.connect(_acao_do_layout)\\n    var barra := PanelContainer.new()\\n    barra.set_anchors_and_offsets_preset(Control.PRESET_TOP_WIDE)\\n    barra.custom_minimum_size.y = 44.0\\n    add_child(barra)\\n    _status = Label.new()\\n    _status.text = \\\"PREVIA: menus funcionam nesta cena. Sistemas reais precisam de integracao.\\\"\\n    _status.autowrap_mode = TextServer.AUTOWRAP_WORD_SMART\\n    barra.add_child(_status)\\n\\nfunc _acao_do_layout(id: String) -> void:\\n    if TELA_POR_ACAO.has(id):\\n        var nome: String = str(TELA_POR_ACAO[id])\\n        var arquivo := \\\"res://layouts/\\\" + nome + \\\".json\\\"\\n        if FileAccess.file_exists(arquivo):\\n            _quadro.carregar_layout(arquivo)\\n            _status.text = \\\"Tela aberta: \\\" + nome\\n        else:\\n            _status.text = \\\"Layout nao exportado: \\\" + arquivo\\n        return\\n    var fluxos: Dictionary = EXECUTOR.carregar_fluxos()\\n    if fluxos.has(id):\\n        var resultado: Dictionary = EXECUTOR.simular(fluxos[id], _estado)\\n        if bool(resultado.get(\\\"ok\\\", false)):\\n            _estado = resultado.get(\\\"estado\\\", _estado)\\n            var mensagens: Array = resultado.get(\\\"mensagens\\\", [])\\n            var textos := PackedStringArray()\\n            for mensagem in mensagens:\\n                textos.append(str(mensagem))\\n            _status.text = \\\"Fluxo \\\" + id + \\\" simulado. \\\" + \\\" | \\\".join(textos)\\n        else:\\n            _status.text = \\\"Fluxo nao executado: \\\" + str(resultado.get(\\\"erro\\\", \\\"\\\"))\\n        return\\n    # Nunca marcar uma acao de gameplay como concluida so porque o botao foi clicado.\\n    _status.text = \\\"Botao '\\\" + id + \\\"' detectado; vincule a acao ao sistema REAL do jogo.\\\"\\n\";\nconst GODOT_CREATOR_SCENE=\"[gd_scene load_steps=2 format=3]\\n\\n[ext_resource type=\\\"Script\\\" path=\\\"res://scripts/ui/apoena_game_creator_previa.gd\\\" id=\\\"1\\\"]\\n\\n[node name=\\\"PreviaGameCreator\\\" type=\\\"Control\\\"]\\nlayout_mode = 3\\nanchors_preset = 15\\nanchor_right = 1.0\\nanchor_bottom = 1.0\\nscript = ExtResource(\\\"1\\\")\\n\";\n</script>\n<script>'use strict';\n/* Game Creator v2: banco central, personagens, regras, simulador, cortador e exportador.\n   O arquivo offline usa as mesmas estruturas de dados da Central 1.2.\n   Execucao de regras limitada a uma lista segura e explicita de tipos conhecidos. */\nconst CREATOR_ACTIONS = [\n {id:'iniciar_jogo',label:'Jogar / Iniciar partida',mode:'cena',desc:'Destino de partida selecionável no Godot; exige ligação à cena real.'},\n {id:'selecionar_heroi',label:'Selecionar herói',mode:'editor',desc:'Abre ficha de personagens na simulação; no Godot será ligado à cena de seleção.'},\n {id:'abrir_inventario',label:'Abrir inventário',mode:'tela',target:'inventario'},\n {id:'fechar_inventario',label:'Fechar inventário',mode:'tela',target:'menu_principal'},\n {id:'abrir_laboratorio',label:'Abrir laboratório',mode:'tela',target:'laboratorio'},\n {id:'abrir_forja',label:'Abrir forja',mode:'tela',target:'forja'},\n {id:'abrir_cristais',label:'Abrir cristais',mode:'tela',target:'cristais'},\n {id:'abrir_loja',label:'Abrir loja',mode:'tela',target:'loja'},\n {id:'abrir_receitas',label:'Abrir receitas',mode:'tela',target:'receitas'},\n {id:'abrir_configuracoes',label:'Abrir configurações',mode:'cena',desc:'Aguardando ligação à cena oficial de configurações.'},\n {id:'voltar',label:'Voltar',mode:'tela',target:'menu_principal'},\n {id:'comprar_item',label:'Comprar item selecionado',mode:'regra'},\n {id:'vender_item',label:'Vender item selecionado',mode:'regra'},\n {id:'usar_item',label:'Consumir item selecionado',mode:'regra'},\n {id:'equipar_item',label:'Equipar item selecionado',mode:'regra'},\n {id:'preparar_pocao',label:'Preparar poção/receita',mode:'regra'},\n {id:'forjar_item',label:'Forjar equipamento/receita',mode:'regra'},\n {id:'exibir_mensagem',label:'Exibir mensagem',mode:'regra'},\n];\nconst CREATOR_BLOCKS = [\n {id:'mensagem',name:'Mostrar mensagem',field:'texto',hint:'Mensagem apresentada ao jogador'},\n {id:'curar_hp',name:'Recuperar vida (HP)',field:'valor',hint:'Porcentagem do HP máximo. 25 = 25%'},\n {id:'curar_aurium',name:'Recuperar Aurium',field:'valor',hint:'Porcentagem do Aurium máximo. 100 = 100%'},\n {id:'gastar_ouro',name:'Descontar moedas',field:'valor',hint:'Falha se o personagem não tiver ouro'},\n {id:'dar_ouro',name:'Adicionar moedas',field:'valor',hint:'Quantidade de ouro'},\n {id:'dar_item',name:'Adicionar item',field:'itemId',hint:'ID do item cadastrado'},\n {id:'retirar_item',name:'Remover item',field:'itemId',hint:'ID de item; quantidade 1'},\n {id:'ir_tela',name:'Abrir tela',field:'destino',hint:'Tela existente nos layouts'},\n {id:'requer_item',name:'Verificar item no inventário',field:'itemId',hint:'Se faltar, interrompe a sequência'},\n {id:'requer_nivel',name:'Verificar nível mínimo',field:'valor',hint:'Se o nível for menor, interrompe'},\n {id:'bonus_temporario',name:'Bônus temporário (dados)',field:'atributo',hint:'Registra bônus no simulador. Motor Godot exige integração.'},\n {id:'efeito_visual',name:'Reproduzir efeito visual',field:'recurso',hint:'Referência de efeito para integrar no Godot'},\n];\nconst CHAR_DEFAULT=[\n {id:'apoena',name:'Apoena Rocha Rios',classe:'Aprendiz de aventureiro',nivel:1,hp:0,aurium:0,ataque:0,defesa:0,retratoId:'',modelo3d:'',habilidades:[],equipamento:{arma:'',escudo:'',armadura:'',cristal:''},notes:'Atributos ainda precisam ser conferidos com a ficha oficial do jogo.'},\n {id:'oriom',name:'Orion / Oriom',classe:'',nivel:1,hp:0,aurium:0,ataque:0,defesa:0,retratoId:'',modelo3d:'',habilidades:[],equipamento:{arma:'',escudo:'',armadura:'',cristal:''},notes:'Confirmar grafia e valores do cadastro oficial.'},\n {id:'ubirara',name:'Ubirará',classe:'',nivel:1,hp:0,aurium:0,ataque:0,defesa:0,retratoId:'',modelo3d:'',habilidades:[],equipamento:{arma:'',escudo:'',armadura:'',cristal:''},notes:''},\n {id:'aqua',name:'Aqua',classe:'',nivel:1,hp:0,aurium:0,ataque:0,defesa:0,retratoId:'',modelo3d:'',habilidades:[],equipamento:{arma:'',escudo:'',armadura:'',cristal:''},notes:''},\n];\nlet creatorCurrentChar='apoena',creatorCurrentFlow='curar_hp_demo',creatorSim={hp:500,maxhp:1000,aurium:50,maxaurium:100,gold:250,level:1,bag:{},screen:'menu_principal',effects:[]},slicerImg=null;\nconst creatorEsc=esc;\nfunction ensureCreatorState(){\n if(!Array.isArray(state.characters))state.characters=deep(CHAR_DEFAULT);\n if(!Array.isArray(state.flows))state.flows=[\n  {id:'curar_hp_demo',name:'Demonstração: recuperar vida',trigger:'ao_usar_item',blocks:[{type:'curar_hp',valor:25},{type:'mensagem',texto:'Vida recuperada.'}],status:'exemplo'},\n ];\n if(!state.integration||typeof state.integration!=='object')state.integration={sceneTargets:{},bridgeVersion:1};\n if(!state.creatorSettings)state.creatorSettings={schema:'apoena.gamecreator.v2'};\n}\nfunction seedOfficialPotions(){\n ensureCreatorState();if(state.creatorSettings.officialPackEnabled===false)return {created:0,linked:0,total:state.items.filter(x=>x.category==='pocao').length};let created=0,linked=0;\n for(const obj of OFFICIAL_52_POTIONS){\n   let it=state.items.find(x=>x.id===obj.id);\n   let a=it?.iconId?asset(it.iconId):null;\n   if(!a){const desired='oficial_52_'+obj.id;\n     a=state.assets.find(x=>x.id===desired);\n     if(!a){a={id:desired,name:obj.nome,file:obj.arquivo,source:'PACK_OFICIAL_52',category:'pocao',data:'data:image/png;base64,'+obj.base64};state.assets.push(a)}\n     if(it){it.iconId=a.id;linked++}\n   }\n   if(!it){\n    it={id:obj.id,name:obj.nome,category:'pocao',group:obj.categoria,officialNumber:obj.numero,\n      rarity:'comum',iconId:a.id,description:obj.descricao,sourceState:obj.estado,sourceNote:obj.observacao,\n      price:0,craftCost:0,equippable:false,consumable:true,maxStack:99,\n      effect:{type:'nenhum',value:0,duration:0},visibility:{inventory:true,laboratorio:true,loja:false,forja:false,cristais:false,disponivel:true},\n      gameplayEnabled:false,status:'referencia_oficial_pendente',source:'pack_52',\n      // Os 3 itens 'implementado' no ZIP nao devem ter efeito sobrescrito por um gerador externo.\n      // Preservar suas descricoes; habilitacao no motor requer conferência.\n      };state.items.push(it);created++}\n   else {it.group??=obj.categoria;it.sourceState??=obj.estado;it.sourceNote??=obj.observacao;it.officialNumber??=obj.numero;}\n }\n return{created,linked,total:state.items.filter(x=>x.category==='pocao').length};\n}\nfunction creatorRenderHome(){ensureCreatorState();const all=state.items,official=all.filter(x=>x.source==='pack_52');\n $('#creatorStats').innerHTML=[['Poções oficiais',official.length+'/52'],['Itens',all.length],['Receitas',state.recipes.length],['Personagens',state.characters.length],['Telas',Object.keys(state.screens).length],['Fluxos',state.flows.length]].map(x=>`<div class=\"stat\"><strong>${x[1]}</strong>${x[0]}</div>`).join('');\n $('#creatorOfficialList').innerHTML=official.map(i=>{const a=asset(i.iconId);return `<button class=\"creator-potion\" data-id=\"${creatorEsc(i.id)}\" title=\"${creatorEsc(i.description)}\">${a?`<img loading=\"lazy\" src=\"${a.data}\">`:''}<span><strong>${creatorEsc(i.name)}</strong><small>${creatorEsc(i.group||'')} · ${creatorEsc(i.sourceState||'conceito')}</small></span></button>`}).join('');\n $$('#creatorOfficialList [data-id]').forEach(b=>b.onclick=()=>{const i=state.items.find(x=>x.id===b.dataset.id);if(i)fillItem(i)});\n $('#creatorHomeWarnings').textContent='O pack inclui descrições de referência. Apenas três poções constam como “implementado” no material original. Nenhum efeito é ativado automaticamente na Central nem no Godot.';\n}\nfunction creatorRenderCharacters(){ensureCreatorState();$('#creatorCharList').innerHTML=state.characters.map(c=>{const a=asset(c.retratoId);return `<button class=\"character-chip ${c.id===creatorCurrentChar?'selected':''}\" data-id=\"${creatorEsc(c.id)}\">${a?`<img src=\"${a.data}\" alt=\"\">`:'<span>◉</span>'}<span>${creatorEsc(c.name)}</span></button>`}).join('');\n $$('#creatorCharList [data-id]').forEach(b=>b.onclick=()=>{creatorCurrentChar=b.dataset.id;creatorRenderCharacters()});\n const c=state.characters.find(x=>x.id===creatorCurrentChar)||state.characters[0];if(!c)return;\n const pic=asset(c.retratoId);$('#creatorCharPortrait').innerHTML=pic?`<img src=\"${pic.data}\" alt=\"Retrato de ${creatorEsc(c.name)}\">`:'<span>Carregar retrato</span>';\n for(const [field,prop] of [['charName','name'],['charId','id'],['charClass','classe'],['charLevel','nivel'],['charHP','hp'],['charAurium','aurium'],['charAttack','ataque'],['charDefense','defesa'],['charModel','modelo3d'],['charNotes','notes']])$('#'+field).value=c[prop]??'';\n $('#charPortraitSelect').innerHTML=assetOptions(c.retratoId);$('#charPortraitSelect').value=c.retratoId||'';\n for(const key of ['arma','escudo','armadura','cristal']){\n   $('#charEquip'+key).innerHTML='<option value=\"\">— Nenhum —</option>'+state.items.filter(i=>i.category===key).map(i=>`<option value=\"${creatorEsc(i.id)}\">${creatorEsc(i.name)}</option>`).join('');\n   $('#charEquip'+key).value=c.equipamento?.[key]||'';\n }\n}\nfunction creatorSaveCharacter(){ensureCreatorState();const c=state.characters.find(x=>x.id===creatorCurrentChar);if(!c)return;const oldId=c.id,newId=slug($('#charId').value||$('#charName').value);if(newId!==oldId&&state.characters.some(x=>x.id===newId))return alert('Outro personagem já usa esse ID.');\n c.id=newId;creatorCurrentChar=newId;c.name=$('#charName').value.trim()||newId;c.classe=$('#charClass').value;\n for(const [field,prop] of [['charLevel','nivel'],['charHP','hp'],['charAurium','aurium'],['charAttack','ataque'],['charDefense','defesa']])c[prop]=Math.max(0,Number($('#'+field).value)||0);\n c.retratoId=$('#charPortraitSelect').value;c.modelo3d=$('#charModel').value;c.notes=$('#charNotes').value;\n c.equipamento=Object.fromEntries(['arma','escudo','armadura','cristal'].map(k=>[k,$('#charEquip'+k).value]));\n creatorRenderCharacters();status('Ficha de '+c.name+' salva no banco do projeto.');\n}\nconst creatorBlockOption=(value='mensagem')=>CREATOR_BLOCKS.map(x=>`<option value=\"${x.id}\" ${value===x.id?'selected':''}>${x.name}</option>`).join('');\nfunction creatorRenderFlows(){ensureCreatorState();$('#creatorFlowSelect').innerHTML=state.flows.map(x=>`<option value=\"${creatorEsc(x.id)}\">${creatorEsc(x.name)}</option>`).join('');\n if(!state.flows.some(x=>x.id===creatorCurrentFlow))creatorCurrentFlow=state.flows[0]?.id||'';\n $('#creatorFlowSelect').value=creatorCurrentFlow;const f=state.flows.find(x=>x.id===creatorCurrentFlow);if(!f)return;\n $('#flowName').value=f.name;$('#flowId').value=f.id;$('#flowTrigger').value=f.trigger||'ao_clicar';\n $('#flowBlocks').innerHTML=f.blocks.map((b,index)=>`<div class=\"flow-block\"><div class=\"row\"><strong>Bloco ${index+1}</strong><select data-btype=\"${index}\">${creatorBlockOption(b.type)}</select><button data-up=\"${index}\" title=\"Mover para cima\">↑</button><button data-down=\"${index}\" title=\"Mover para baixo\">↓</button><button data-del=\"${index}\" class=\"danger\">×</button></div><label>Valor, ID ou parâmetro</label><input data-bvalue=\"${index}\" value=\"${creatorEsc(b.texto??b.valor??b.itemId??b.destino??b.atributo??b.recurso??'')}\" placeholder=\"Valor do bloco\"><p class=\"hint\">${creatorEsc(CREATOR_BLOCKS.find(x=>x.id===b.type)?.hint||'')}</p></div>`).join('');\n $$('[data-btype]').forEach(x=>x.onchange=()=>{const b=f.blocks[+x.dataset.btype];const val=b.texto??b.valor??b.itemId??b.destino??b.atributo??b.recurso??'';b.type=x.value;for(const p of ['texto','valor','itemId','destino','atributo','recurso'])delete b[p];b[CREATOR_BLOCKS.find(y=>y.id===b.type).field]=val;creatorRenderFlows()});\n $$('[data-bvalue]').forEach(x=>x.oninput=()=>{const b=f.blocks[+x.dataset.bvalue];const field=CREATOR_BLOCKS.find(y=>y.id===b.type).field;b[field]=field==='valor'?Number(x.value)||0:x.value});\n $$('[data-del]').forEach(x=>x.onclick=()=>{f.blocks.splice(+x.dataset.del,1);creatorRenderFlows()});\n $$('[data-up]').forEach(x=>x.onclick=()=>{const i=+x.dataset.up;if(i>0){[f.blocks[i-1],f.blocks[i]]=[f.blocks[i],f.blocks[i-1]];creatorRenderFlows()}});\n $$('[data-down]').forEach(x=>x.onclick=()=>{const i=+x.dataset.down;if(i<f.blocks.length-1){[f.blocks[i+1],f.blocks[i]]=[f.blocks[i],f.blocks[i+1]];creatorRenderFlows()}});\n}\nfunction creatorSaveFlow(){const f=state.flows.find(x=>x.id===creatorCurrentFlow);if(!f)return;const id=slug($('#flowId').value||$('#flowName').value);if(id!==f.id&&state.flows.some(x=>x.id===id))return alert('Já existe fluxo com esse ID');f.id=id;f.name=$('#flowName').value||id;f.trigger=$('#flowTrigger').value;creatorCurrentFlow=id;creatorRenderFlows();status('Fluxo '+id+' salvo.');}\nfunction creatorDefaultSim(){creatorSim={hp:500,maxhp:1000,aurium:50,maxaurium:100,gold:250,level:1,bag:{},screen:'menu_principal',effects:[]};creatorRenderSimulator('Simulação reiniciada com valores de teste, sem afetar o jogo.')}\nfunction creatorRenderSimulator(message='Escolha uma ação e clique em Testar.'){\n $('#simStats').innerHTML=[['HP',creatorSim.hp+'/'+creatorSim.maxhp],['Aurium',creatorSim.aurium+'/'+creatorSim.maxaurium],['Ouro',creatorSim.gold],['Nível',creatorSim.level],['Tela',creatorSim.screen]].map(x=>`<div class=\"stat\"><strong>${creatorEsc(x[1])}</strong>${x[0]}</div>`).join('');\n $('#simBag').innerHTML=Object.keys(creatorSim.bag).filter(id=>creatorSim.bag[id]>0).map(id=>{const i=state.items.find(x=>x.id===id),a=asset(i?.iconId);return `<span class=\"sim-bag-entry\">${a?`<img src=\"${a.data}\" alt=\"\">`:''}${creatorEsc(i?.name||id)} × ${creatorSim.bag[id]}</span>`}).join('')||'<span class=\"hint\">Mochila vazia (simulação)</span>';\n $('#simLog').textContent=message;$('#simAction').innerHTML=CREATOR_ACTIONS.map(x=>`<option value=\"${x.id}\">${creatorEsc(x.label)}</option>`).join('');\n $('#simItem').innerHTML=state.items.map(x=>`<option value=\"${creatorEsc(x.id)}\">${creatorEsc(x.name)}</option>`).join('');\n $('#simRecipe').innerHTML='<option value=\"\">— Selecione receita —</option>'+state.recipes.map(r=>`<option value=\"${creatorEsc(r.id)}\">${creatorEsc(r.name)}</option>`).join('');\n $('#simFlow').innerHTML=state.flows.map(f=>`<option value=\"${creatorEsc(f.id)}\">${creatorEsc(f.name)}</option>`).join('');\n}\nfunction creatorSimAction(id,itemId,recipeId){\n const it=state.items.find(x=>x.id===itemId),v=(it?.visibility||{});let msg='';\n const go=t=>{if(state.screens[t]){creatorSim.screen=t;return'Abriu tela '+t}return 'Tela '+t+' não foi cadastrada; falta integração.'};\n if(['abrir_inventario','fechar_inventario','abrir_laboratorio','abrir_forja','abrir_cristais','abrir_loja','abrir_receitas','voltar'].includes(id)){msg=go(CREATOR_ACTIONS.find(x=>x.id===id).target)}\n else if(id==='selecionar_heroi'){switchPage('characters');creatorRenderCharacters();msg='Abriu o editor de personagens (modo de simulação)'}\n else if(id==='iniciar_jogo'||id==='abrir_configuracoes'){msg='AÇÃO PENDENTE NO GODOT: configure a cena real para '+id+'. Nenhuma partida foi iniciada.'}\n else if(id==='comprar_item'){if(!it)msg='Selecione um item';else if(v.loja===false)msg='Item bloqueado para venda';else if(creatorSim.gold<(Number(it.price)||0))msg='Ouro insuficiente';else{creatorSim.gold-=Number(it.price)||0;creatorSim.bag[it.id]=(creatorSim.bag[it.id]||0)+1;msg='Comprou '+it.name}}\n else if(id==='vender_item'){if(!it||!(creatorSim.bag[it.id]>0))msg='Item não está na mochila';else{creatorSim.bag[it.id]--;creatorSim.gold+=Math.max(0,Math.floor(Number(it.price||0)*.5));msg='Vendeu '+it.name+' por 50% do preço (regra ilustrativa)'}}\n else if(id==='usar_item'){if(!it||!(creatorSim.bag[it.id]>0))msg='Você não possui esse item';else if(!it.gameplayEnabled){msg='Item em cadastro: efeito ainda não aprovado/ativo.'}else if(['recuperar_hp','restaurar_hp_percentual','restaurar_hp_fixo'].includes(it.effect?.type)){creatorSim.hp=Math.min(creatorSim.maxhp,creatorSim.hp+((it.effect?.type==='restaurar_hp_fixo')?Number(it.effect?.value||0):creatorSim.maxhp*(Number(it.effect?.value)||0)/100));creatorSim.bag[it.id]--;msg='Poção usada: HP recuperado'}else if(['recuperar_aurium','restaurar_aurium_percentual'].includes(it.effect?.type)){creatorSim.aurium=Math.min(creatorSim.maxaurium,creatorSim.aurium+creatorSim.maxaurium*(Number(it.effect?.value)||0)/100);creatorSim.bag[it.id]--;msg='Poção usada: Aurium recuperado'}else msg='Efeito ainda não implementado no simulador: '+(it.effect?.type||'nenhum')}\n else if(id==='equipar_item'){if(!it||!(creatorSim.bag[it.id]>0)||!['arma','escudo','armadura','cristal','acessorio'].includes(it.category))msg='Equipe um item compatível da mochila';else msg='Equipamento registrado na simulação: '+it.name+' (bônus no Godot pendentes)'}\n else if(['preparar_pocao','forjar_item'].includes(id)){const recipe=state.recipes.find(x=>x.id===recipeId);if(!recipe)msg='Selecione uma receita cadastrada';else if((id==='forjar_item'?recipe.station!=='forja':recipe.station!=='laboratorio'))msg='Receita não é dessa estação';else if(creatorSim.gold<(recipe.gold||0))msg='Ouro insuficiente';else if((recipe.ingredients||[]).some(x=>(creatorSim.bag[x.id]||0)<x.qty))msg='Ingredientes insuficientes';else{creatorSim.gold-=recipe.gold||0;for(const i of recipe.ingredients||[])creatorSim.bag[i.id]-=i.qty;creatorSim.bag[recipe.resultId]=(creatorSim.bag[recipe.resultId]||0)+(recipe.quantity||1);msg='Produziu '+(state.items.find(x=>x.id===recipe.resultId)?.name||recipe.resultId)}}\n else msg='Ação não simulada.';\n creatorRenderSimulator(msg);$('#simAction').value=id;$('#simItem').value=itemId;$('#simRecipe').value=recipeId;\n}\nfunction creatorRunFlow(f){if(!f)return;const bag=deep(creatorSim.bag);let msg=[];\n for(const b of f.blocks){const val=Number(b.valor)||0;switch(b.type){\n case 'mensagem':msg.push(String(b.texto||''));break;\n case 'curar_hp':creatorSim.hp=Math.min(creatorSim.maxhp,creatorSim.hp+creatorSim.maxhp*Math.max(0,val)/100);msg.push('Curou '+val+'% de HP');break;\n case 'curar_aurium':creatorSim.aurium=Math.min(creatorSim.maxaurium,creatorSim.aurium+creatorSim.maxaurium*Math.max(0,val)/100);msg.push('Recuperou '+val+'% de Aurium');break;\n case 'gastar_ouro':if(creatorSim.gold<val){creatorSim.bag=bag;return creatorRenderSimulator('Fluxo interrompido: moedas insuficientes')}creatorSim.gold-=Math.max(0,val);break;\n case 'dar_ouro':creatorSim.gold+=Math.max(0,val);break;\n case 'requer_item':if(!(creatorSim.bag[b.itemId]>0))return creatorRenderSimulator('Fluxo interrompido: falta '+b.itemId);break;\n case 'retirar_item':if(!(creatorSim.bag[b.itemId]>0))return creatorRenderSimulator('Fluxo interrompido: item '+b.itemId+' não encontrado');creatorSim.bag[b.itemId]--;break;\n case 'dar_item':if(state.items.some(x=>x.id===b.itemId))creatorSim.bag[b.itemId]=(creatorSim.bag[b.itemId]||0)+1;else msg.push('Item não cadastrado: '+b.itemId);break;\n case 'ir_tela':if(state.screens[b.destino])creatorSim.screen=b.destino;else msg.push('Tela inexistente: '+b.destino);break;\n case 'requer_nivel':if(creatorSim.level<val)return creatorRenderSimulator('Nível insuficiente');break;\n case 'bonus_temporario':creatorSim.effects.push({tipo:b.atributo||'atributo',valor:val});msg.push('Bônus registrado; aplicação real depende do Godot');break;\n case 'efeito_visual':msg.push('Efeito visual a ligar no Godot: '+(b.recurso||''));break;\n default:msg.push('Bloco desconhecido: '+b.type);break;\n }}creatorRenderSimulator(msg.join(' · ')||'Fluxo executado no simulador');\n}\nfunction creatorValidate(){ensureCreatorState();const warnings=[];const ids=new Set(state.items.map(i=>i.id));const layouts=new Set(Object.keys(state.screens));const assetIds=new Set(state.assets.map(a=>a.id));const valid=new Set(CREATOR_ACTIONS.map(a=>a.id));\n for(const l of Object.values(state.screens))for(const e of l.elements||[])if(e.type==='button'&&e.action&&!valid.has(e.action)&&!state.flows.some(f=>f.id===e.action))warnings.push('Botão '+e.name+': ação não registrada ('+e.action+')');\n for(const i of state.items){if(i.iconId&&!assetIds.has(i.iconId))warnings.push('Ícone ausente em '+i.name);if(i.gameplayEnabled&&(!i.effect||i.effect.type==='nenhum'))warnings.push('Item ativo sem efeito: '+i.name);if(i.category==='pocao'&&i.sourceState==='conceito'&&i.gameplayEnabled)warnings.push('Conceito ativado sem validação oficial: '+i.name)}\n for(const c of state.characters){if(!c.name)warnings.push('Personagem sem nome: '+c.id);if(c.retratoId&&!assetIds.has(c.retratoId))warnings.push('Retrato inexistente: '+c.name);for(const [slot,id] of Object.entries(c.equipamento||{})){if(id&&!ids.has(id))warnings.push('Equipamento '+id+' inexistente em '+c.name)}}\n for(const f of state.flows)for(const b of f.blocks){if(!CREATOR_BLOCKS.some(t=>t.id===b.type))warnings.push('Fluxo '+f.id+': bloco inválido '+b.type);if(b.type==='ir_tela'&&!layouts.has(b.destino))warnings.push('Fluxo '+f.id+': tela inexistente '+b.destino);if(['requer_item','retirar_item','dar_item'].includes(b.type)&&!ids.has(b.itemId))warnings.push('Fluxo '+f.id+': item inexistente '+b.itemId)}\n const data=dbReportData();const officialConcept=state.items.filter(i=>i.source==='pack_52'&&i.sourceState==='conceito').length;\n $('#creatorValidator').innerHTML=`<div class=\"database-stat\"><div class=\"stat\"><strong>${state.items.length}</strong>Itens</div><div class=\"stat\"><strong>${officialConcept}</strong>Poções conceito</div><div class=\"stat\"><strong>${warnings.length}</strong>Pendências estruturais</div><div class=\"stat\"><strong>${data.avisos.length}</strong>Avisos de cadastro</div></div>`+(warnings.length?warnings.slice(0,35).map(x=>`<div class=\"db-warn\">${creatorEsc(x)}</div>`).join(''):'<div class=\"db-ok\">Não foram encontradas falhas de referência entre layouts, itens, personagens e fluxos.</div>')+`<p class=\"hint\">${data.avisos.length} avisos adicionais de catálogo. Não é teste de execução no Godot.</p>`;\n return {warnings,db:data};\n}\n/* Biblioteca de ações para botões no Inspector da Central. */\nconst renderInspectorV12=renderInspector;\nrenderInspector=function(){renderInspectorV12();const e=element();if(!e||e.type!=='button')return;const box=$('#inspector');const field=$('#inspector [data-field=\"action\"]');if(field){field.readOnly=true;field.title='Escolha uma ação na lista de comportamentos';}\n const section=document.createElement('div');section.innerHTML=`<label>Função pronta do botão</label><select id=\"creatorButtonAction\"><option value=\"\">— Sem ação —</option>${CREATOR_ACTIONS.map(x=>`<option value=\"${x.id}\" ${e.action===x.id?'selected':''}>${creatorEsc(x.label)}</option>`).join('')}${state.flows.map(x=>`<option value=\"${x.id}\" ${e.action===x.id?'selected':''}>FLUXO: ${creatorEsc(x.name)}</option>`).join('')}</select><p class=\"hint\" id=\"creatorButtonHint\">Selecione uma função para saber o que o botão faz. No Godot, as ações dependem do executor integrado.</p>`;\n if(field)field.insertAdjacentElement('beforebegin',section);else box.prepend(section);\n $('#creatorButtonAction').onchange=()=>{e.action=$('#creatorButtonAction').value;if(field)field.value=e.action;$('#creatorButtonHint').textContent=CREATOR_ACTIONS.find(x=>x.id===e.action)?.desc||'Fluxo configurável no editor de ações.';};\n};\nconst CREATOR_MAX_RECORTES=3000;\nfunction creatorCutterDraw(){const c=$('#creatorCutCanvas'),ctx=c.getContext('2d'),col=Math.min(CREATOR_MAX_RECORTES,Math.max(1,parseInt($('#cutCols').value)||1)),rows=Math.min(CREATOR_MAX_RECORTES,Math.max(1,parseInt($('#cutRows').value)||1));if(!slicerImg){c.width=500;c.height=300;ctx.fillStyle='#172a38';ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle='#b4cbd1';ctx.fillText('Envie uma imagem com os ícones para visualizar os cortes',14,34);return}\n c.width=slicerImg.naturalWidth;c.height=slicerImg.naturalHeight;ctx.clearRect(0,0,c.width,c.height);ctx.drawImage(slicerImg,0,0);const margin=Math.max(0,Number($('#cutMargin').value)||0),gap=Math.max(0,Number($('#cutGap').value)||0);const cellW=(c.width-2*margin-(col-1)*gap)/col,cellH=(c.height-2*margin-(rows-1)*gap)/rows;\n if(col*rows>CREATOR_MAX_RECORTES){$('#creatorCutInfo').textContent=`${col} × ${rows} = ${col*rows} recortes. O máximo é ${CREATOR_MAX_RECORTES}. Reduza linhas ou colunas.`;return;}\n ctx.save();ctx.strokeStyle='#31e6ff';ctx.lineWidth=Math.max(1,Math.min(c.width,c.height)/800);ctx.font=`${Math.max(12,Math.round(c.width/60))}px system-ui`;ctx.fillStyle='#ffffff';\n for(let j=0;j<rows;j++)for(let i=0;i<col;i++){const x=margin+i*(cellW+gap),y=margin+j*(cellH+gap);if(cellW<1||cellH<1)continue;ctx.strokeRect(x,y,cellW,cellH);ctx.fillText(String(j*col+i+1),x+4,y+Math.max(14,Math.round(c.width/60)))}ctx.restore();\n $('#creatorCutInfo').textContent=`${c.width} × ${c.height}px • ${col} colunas × ${rows} linhas = ${col*rows} recortes • ${Math.floor(cellW)} × ${Math.floor(cellH)}px por célula antes do recorte quadrado.`;\n}\nfunction creatorGridPreset(n){if(n===42){$('#cutCols').value=7;$('#cutRows').value=6}else{const columns=n===10?5:n===20?5:n===30?6:n===40?8:10;$('#cutCols').value=columns;$('#cutRows').value=n/columns;}creatorCutterDraw()}\nasync function creatorSlice(toLibrary){if(!slicerImg)return alert('Envie uma imagem para recortar.');const col=Math.max(1,parseInt($('#cutCols').value)||1),rows=Math.max(1,parseInt($('#cutRows').value)||1);if(col*rows>CREATOR_MAX_RECORTES)return alert('Limite: 3.000 ícones por pack. Reduza linhas ou colunas.');const margin=Math.max(0,Number($('#cutMargin').value)||0),gap=Math.max(0,Number($('#cutGap').value)||0),w=slicerImg.naturalWidth,h=slicerImg.naturalHeight,cellW=(w-margin*2-(col-1)*gap)/col,cellH=(h-margin*2-(rows-1)*gap)/rows; if(cellW<8||cellH<8)return alert('Grade inválida: diminua margens e espaçamento.');\n const zipFiles=[],cat=$('#cutCategory').value,output=Math.max(32,Math.min(1024,parseInt($('#cutOutputSize').value)||256)),square=$('#cutSquare').checked;\n for(let r=0;r<rows;r++)for(let c=0;c<col;c++){\n  const x=margin+c*(cellW+gap),y=margin+r*(cellH+gap),filename=`icone_${String(r*col+c+1).padStart(3,'0')}.png`,canvas=document.createElement('canvas');canvas.width=canvas.height=output;const ctx=canvas.getContext('2d');let sx=x,sy=y,sw=cellW,sh=cellH;\n  if(square){const side=Math.min(cellW,cellH);sx+=(cellW-side)/2;sy+=(cellH-side)/2;sw=sh=side;}\n  ctx.drawImage(slicerImg,sx,sy,sw,sh,0,0,output,output);const data=canvas.toDataURL('image/png');if(toLibrary)makeAsset(filename,data,'cortador',cat);\n  const bin=atob(data.split(',')[1]);const bytes=new Uint8Array(bin.length);for(let n=0;n<bin.length;n++)bytes[n]=bin.charCodeAt(n);zipFiles.push(['icones/'+filename,bytes]);\n  const concluidos=r*col+c+1;if(concluidos%100===0){status('Recortando '+concluidos+' / '+(col*rows)+' ícones...');await new Promise(resolve=>setTimeout(resolve,0));}\n }\n if(toLibrary){refreshAssetLists();creatorRenderHome();status(zipFiles.length+' PNGs enviados para a biblioteca compartilhada.');}\n else {zipFiles.push(['LEIA-ME.txt','Ícones gerados na Central Apoena Game Creator.\\nArquivos PNG numerados. Revise cada recorte antes de usar no jogo.\\n']);download(zipPack(zipFiles),'APOENA_ICONES_RECORTADOS.zip');status('Pack com '+zipFiles.length+' arquivos gerado.');}\n}\nfunction creatorSetupEvents(){\n $$('.tab').forEach(b=>b.onclick=()=>{switchPage(b.dataset.page);location.hash=b.dataset.page;if(b.dataset.page==='creator')creatorRenderHome();if(b.dataset.page==='characters')creatorRenderCharacters();if(b.dataset.page==='flows')creatorRenderFlows();if(b.dataset.page==='simulator')creatorRenderSimulator();if(b.dataset.page==='validation')creatorValidate();if(b.dataset.page==='slicer')creatorCutterDraw()});\n $('#creatorNewChar').onclick=()=>{const name=prompt('Nome do novo personagem:');if(!name)return;const id=slug(name);if(state.characters.some(x=>x.id===id))return alert('Personagem já cadastrado');state.characters.push({...deep(CHAR_DEFAULT[0]),id,name,retratoId:'',classe:'',modelo3d:'',notes:'',hp:0,aurium:0,ataque:0,defesa:0});creatorCurrentChar=id;creatorRenderCharacters()};\n $('#creatorCharSave').onclick=creatorSaveCharacter;\n $('#creatorCharDelete').onclick=()=>{if(!confirm('Excluir ficha deste personagem do projeto?'))return;state.characters=state.characters.filter(x=>x.id!==creatorCurrentChar);creatorCurrentChar=state.characters[0]?.id;creatorRenderCharacters()};\n $('#charPortraitFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const d=await fileToPNG(f),a=makeAsset(f.name,d,'personagem','nao_classificado');const c=state.characters.find(x=>x.id===creatorCurrentChar);c.retratoId=a.id;refreshAssetLists();creatorRenderCharacters()}catch(err){alert(err.message)}e.target.value=''};\n $('#creatorFlowSelect').onchange=e=>{creatorCurrentFlow=e.target.value;creatorRenderFlows()};\n $('#creatorFlowNew').onclick=()=>{const name=prompt('Nome da ação/fluxo:');if(!name)return;const id=slug(name);if(state.flows.some(x=>x.id===id))return alert('Esse fluxo já existe');state.flows.push({id,name,trigger:'ao_clicar',blocks:[],status:'rascunho'});creatorCurrentFlow=id;creatorRenderFlows()};\n $('#creatorFlowSave').onclick=creatorSaveFlow;$('#creatorFlowAdd').onclick=()=>{const f=state.flows.find(x=>x.id===creatorCurrentFlow);if(!f)return;f.blocks.push({type:'mensagem',texto:'Nova ação'});creatorRenderFlows()};\n $('#creatorFlowDelete').onclick=()=>{if(!confirm('Excluir fluxo?'))return;state.flows=state.flows.filter(x=>x.id!==creatorCurrentFlow);creatorCurrentFlow=state.flows[0]?.id||'';creatorRenderFlows()};\n $('#simReset').onclick=creatorDefaultSim;\n $('#simTest').onclick=()=>{const id=$('#simAction').value,i=$('#simItem').value,r=$('#simRecipe').value;creatorSimAction(id,i,r)};\n $('#simAddItem').onclick=()=>{const id=$('#simItem').value;if(!id)return;creatorSim.bag[id]=(creatorSim.bag[id]||0)+1;creatorRenderSimulator('Item de teste adicionado à mochila: '+id);$('#simItem').value=id};\n $('#simFlowTest').onclick=()=>creatorRunFlow(state.flows.find(x=>x.id===$('#simFlow').value));\n $('#simGold').onchange=()=>{creatorSim.gold=Math.max(0,Number($('#simGold').value)||0);creatorRenderSimulator('Ouro ajustado para teste.');};\n $('#creatorValidateBtn').onclick=creatorValidate;\n $('#creatorGoItems').onclick=()=>switchPage('inventory');$('#creatorGoLayouts').onclick=()=>switchPage('layouts');\n $('#cutFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>25_000_000)return alert('Imagem muito grande (limite 25MB)');const url=URL.createObjectURL(f);try{slicerImg=await imageFromData(url);$('#cutFileLabel').textContent=f.name;creatorCutterDraw()}catch(err){alert(err.message)}finally{URL.revokeObjectURL(url)}};\n ['cutCols','cutRows','cutMargin','cutGap','cutSquare','cutOutputSize'].forEach(id=>$('#'+id).addEventListener('input',creatorCutterDraw));\n $$('[data-cut-preset]').forEach(b=>b.onclick=()=>creatorGridPreset(+b.dataset.cutPreset));\n $('#cutExport').onclick=()=>creatorSlice(false);$('#cutImport').onclick=()=>creatorSlice(true);\n $('#creatorResetOfficial').onclick=()=>{const ans=confirm('Repor somente fichas oficiais que estiverem faltando? Suas alterações existentes serão preservadas.');if(!ans)return;state.creatorSettings.officialPackEnabled=true;const result=seedOfficialPotions();refreshAssetLists();creatorRenderHome();status('Catálogo oficial conferido: '+result.created+' novas fichas, '+result.linked+' imagens vinculadas.')};\n}\n/* Extensao da exportacao v1.2: anexar os dados aos arquivos já existentes.\n   O leitor Godot continua sendo um componente separado, nunca executamos scripts de terceiros. */\nconst creatorZipPackBase=zipPack;\nzipPack=function(files){\n if(files.some(x=>x[0]==='dados/apoena_catalogo_itens.json')){\n  files.push(['dados/apoena_personagens.json',JSON.stringify({schema:'apoena.characters.v1',characters:state.characters},null,2)]);\n  files.push(['dados/apoena_fluxos.json',JSON.stringify({schema:'apoena.flows.v1',flows:state.flows},null,2)]);\n  files.push(['dados/apoena_acoes_preprogramadas.json',JSON.stringify({schema:'apoena.actions.v1',actions:CREATOR_ACTIONS},null,2)]);\n  files.push(['dados/apoena_relatorio_integracao.json',JSON.stringify({schema:'apoena.validation.v1',warnings:creatorValidate().warnings},null,2)]);\n  files.push(['scripts/sistemas/apoena_game_creator_executor.gd',GODOT_CREATOR_EXECUTOR]);\n  files.push(['scripts/ui/apoena_game_creator_conector.gd',GODOT_CREATOR_CONNECTOR]);\n  files.push(['scripts/ui/apoena_game_creator_previa.gd',GODOT_CREATOR_PREVIA]);\n  files.push(['cenas/game_creator_previa.tscn',GODOT_CREATOR_SCENE]);\n  files.push(['GAME_CREATOR-LEIA-ME.txt',`APOENA GAME CREATOR — PACOTE DE DADOS (VERSAO DE TESTES)\\n\\nIMPORTANTE: abra COPIA do Godot 4, nao sobrescreva seu projeto principal.\\nImagens: arte/apoena_geradores/\\nDados: dados/apoena_catalogo_itens.json, receitas, personagens, fluxos.\\n\\nPara testar a navegacao no Godot abra cenas/game_creator_previa.tscn (F6).\n\nPara vincular os botoes, instancie a cena de layout e conecte o sinal acao_solicitada do script ui/layout_json_agar.gd ao metodo processar_acao do script ui/apoena_game_creator_conector.gd. O conector so executa acoes explicitamente mapeadas; cenas exigem configurar caminhos reais.\\n\\nAVISO: os 52 PNGs sao oficiais do pack enviado. O pack informa que apenas tres pocoes estavam implementadas e 49 eram conceitos. A central NAO habilita efeitos automaticamente. Efeitos novos, combate, modificacao de status e forja dependem de ligacao ao motor real.\\n`]);\n }\n return creatorZipPackBase(files);\n};\n/* Guardar compatibilidade com projetos anteriores; não apagar dados extras durante carregamento. */\nconst creatorLoadOld=$('#projectFile').onchange;\n$('#projectFile').onchange=async function(event){await creatorLoadOld.call(this,event);ensureCreatorState();seedOfficialPotions();refreshAssetLists();creatorRenderHome();creatorRenderCharacters();creatorRenderFlows()};\nensureCreatorState();const seeded=seedOfficialPotions();creatorSetupEvents();refreshAssetLists();creatorRenderHome();creatorRenderCharacters();creatorRenderFlows();creatorCutterDraw();const creatorHash=location.hash.replace('#','');if(['creator','characters','flows','simulator','slicer','validation'].includes(creatorHash)){$(`.tab[data-page=\"${creatorHash}\"]`).click();}status('Game Creator v2 carregado: 52 poções do pack oficial, sem ativação automática de efeitos.');\n\n(function(){const host=document.querySelector('#creatorReadyButtons');if(!host)return;host.innerHTML=CREATOR_ACTIONS.map(a=>`<button data-ready-action=\"${a.id}\" title=\"${creatorEsc(a.desc||a.label)}\">＋ ${creatorEsc(a.label)}</button>`).join('');host.querySelectorAll('[data-ready-action]').forEach(b=>b.onclick=()=>{const action=CREATOR_ACTIONS.find(a=>a.id===b.dataset.readyAction);if(!action)return;history();const e=newElement('button',action.label);e.text=action.label.toUpperCase();e.action=action.id;e.z_index=screen().elements.length;e.x=150+Math.min(9,e.z_index)*18;e.y=100+Math.min(10,e.z_index)*20;screen().elements.push(e);multiSelected.clear();multiSelected.add(e.id);selected=e.id;renderLayout();status('Adicionado botão pronto: '+action.label+'. Arraste no palco para posicioná-lo.');});})();\n</script>\n<script>\n'use strict';\n/* Apoena Game Creator 3.0 — extensão sobre o projeto v2, 100% local e sem dependências.\n   Os dez editores compartilham o mesmo objeto state da Central. Sem execução dinâmica de código. */\n(() => {\nconst V3_VERSION='3.0.0';\nconst V3_DEFS={\n missions:{title:'Missões e campanhas',emoji:'📜',desc:'Missões principais, secundárias, diárias e eventos; objetivos e recompensas.',fields:[\n ['name','Nome da missão','text'],['kind','Tipo','choice',['principal','secundaria','diaria','semanal','evento']],['status','Estado','choice',['rascunho','revisao','aprovado']],['description','História / descrição','textarea'],['giverId','NPC responsável','ref:npcs'],['regionId','Região','ref:regions'],['requiredLevel','Nível mínimo','number'],['nextQuestId','Próxima missão','ref:missions'],['eventId','Passe / evento associado','ref:passes']\n ],groups:{objectives:{title:'Objetivos',fields:[['type','Tipo','choice',['derrotar_npc','coletar_item','entregar_item','visitar_regiao','falar_npc','cumprir_fluxo']],['targetId','Referência / destino','target'],['amount','Quantidade','number']]},rewards:{title:'Recompensas',fields:[['kind','Tipo','choice',['item','moeda','xp','pontos_passe']],['itemId','Item (se aplicável)','ref:items'],['amount','Quantidade / pontos','number']]}}},\n dialogues:{title:'Diálogos e escolhas',emoji:'💬',desc:'Falas com retratos, escolha de respostas e encadeamento.',fields:[['name','Nome do diálogo','text'],['status','Estado','choice',['rascunho','revisao','aprovado']],['npcId','NPC do diálogo','ref:npcs'],['summary','Contexto','textarea']],groups:{lines:{title:'Falas e escolhas',fields:[['lineId','ID da fala','text'],['speaker','Personagem / NPC','text'],['text','Texto da fala','textarea'],['choice','Resposta do jogador (opcional)','text'],['nextId','Próxima fala (ID)','text'],['flowId','Ação ao escolher','ref:flows']]}}},\n passes:{title:'Passes e aniversário',emoji:'🎁',desc:'Passe de aniversário e temporadas, faixas de recompensa e datas offline.',fields:[['name','Nome do passe','text'],['kind','Formato','choice',['aniversario','temporada','evento','gratuito']],['status','Estado','choice',['rascunho','revisao','aprovado']],['start','Início (AAAA-MM-DD)','date'],['end','Fim (AAAA-MM-DD)','date'],['currency','Nome dos pontos','text'],['description','Descrição','textarea']],groups:{levels:{title:'Marcos de recompensas',fields:[['level','Nível / marco','number'],['points','Pontos acumulados exigidos','number'],['itemId','Item de recompensa','ref:items'],['amount','Quantidade','number']]}}},\n regions:{title:'Regiões e mapas',emoji:'🗺️',desc:'Regiões do mundo, portais e vínculos com cenas Godot.',fields:[['name','Nome da região','text'],['kind','Tipo de local','choice',['cidade','mundo_aberto','masmorra','arena','instancia','interior']],['status','Estado','choice',['rascunho','revisao','aprovado']],['scenePath','Cena Godot (res://...)','text'],['unlockMissionId','Missão para liberar','ref:missions'],['description','Descrição / regras','textarea']],groups:{portals:{title:'Portais e saídas',fields:[['name','Nome do acesso','text'],['targetRegionId','Região de destino','ref:regions'],['requiredLevel','Nível mínimo','number']]}}},\n npcs:{title:'NPCs e monstros',emoji:'👹',desc:'NPCs, comerciantes, aliados, monstros e comportamento básico.',fields:[['name','Nome','text'],['kind','Papel','choice',['npc','comerciante','aliado','inimigo','chefe']],['status','Estado','choice',['rascunho','revisao','aprovado']],['regionId','Região de aparição','ref:regions'],['characterId','Ficha de personagem','ref:characters'],['hp','Vida','number'],['damage','Ataque','number'],['behavior','IA pré-programada','choice',['passivo','patrulha','perseguir','guardar_area','vendedor','dialogo']],['aggro','Distância de percepção','number'],['dialogueId','Diálogo','ref:dialogues'],['lootId','Tabela de drops','ref:loot'],['modelPath','Modelo 3D do Godot','text']],groups:{}},\n loot:{title:'Drops e recompensas',emoji:'💎',desc:'Probabilidades, quantidades e moedas sem duplicar o cadastro de itens.',fields:[['name','Nome da tabela','text'],['status','Estado','choice',['rascunho','revisao','aprovado']],['goldMin','Moedas mínimas','number'],['goldMax','Moedas máximas','number'],['notes','Observações','textarea']],groups:{entries:{title:'Itens possíveis',fields:[['itemId','Item do catálogo','ref:items'],['chance','Probabilidade (0–100%)','percent'],['min','Quantidade mínima','number'],['max','Quantidade máxima','number']]}}},\n progression:{title:'Evolução e habilidades',emoji:'✨',desc:'Progressão, XP, constelações e habilidades de personagens.',fields:[['name','Nome da progressão','text'],['status','Estado','choice',['rascunho','revisao','aprovado']],['characterId','Herói / personagem','ref:characters'],['maxLevel','Nível máximo','number'],['xpBase','XP inicial por nível','number'],['xpGrowth','Crescimento da XP (%)','percent'],['notes','Notas','textarea']],groups:{skills:{title:'Desbloqueios',fields:[['skillId','ID da habilidade','text'],['name','Nome do desbloqueio','text'],['level','Nível exigido','number'],['flowId','Fluxo de ação','ref:flows'],['prerequisite','Habilidade anterior (ID)','text']]}}},\n upgrades:{title:'Forja e aprimoramentos',emoji:'⚒️',desc:'Aplicação de cristais, melhorias, custos e atributos.',fields:[['name','Nome da melhoria','text'],['status','Estado','choice',['rascunho','revisao','aprovado']],['station','Estação','choice',['forja','ferreiro','cristais']],['baseItemId','Item base','ref:items'],['resultItemId','Resultado (opcional)','ref:items'],['notes','Notas','textarea']],groups:{levels:{title:'Níveis de melhoria',fields:[['level','Nível','number'],['crystalId','Cristal necessário','ref:items'],['amount','Cristais necessários','number'],['currency','Custo em moedas','number'],['stat','Atributo','choice',['ataque','defesa','hp','aurium','velocidade']],['bonus','Bônus','number']]}}},\n media:{title:'Animações, sons e efeitos',emoji:'🎬',desc:'Vínculos entre recursos, ações e animações sem editar modelos 3D.',fields:[['name','Nome do recurso','text'],['status','Estado','choice',['rascunho','revisao','aprovado']],['kind','Tipo','choice',['efeito_visual','som','musica','animacao','retrato']],['assetId','Imagem da biblioteca','ref:assets'],['path','Arquivo Godot (res://...)','text'],['flowId','Fluxo associado','ref:flows'],['duration','Duração (segundos)','number'],['loop','Repetir','boolean'],['notes','Observações','textarea']],groups:{}},\n modes:{title:'Modos de jogo',emoji:'🎮',desc:'Exploração, treinamento, MOBA, regras de vitória e duração.',fields:[['name','Nome do modo','text'],['status','Estado','choice',['rascunho','revisao','aprovado']],['kind','Tipo','choice',['exploracao','treino','moba','arena','historia','evento']],['scenePath','Cena principal Godot','text'],['minPlayers','Mínimo de participantes','number'],['maxPlayers','Máximo de participantes','number'],['teamCount','Equipes','number'],['roundSeconds','Duração máxima (s)','number'],['winCondition','Vitória ao','choice',['destruir_nucleo','derrotar_chefe','completar_missao','sobreviver_tempo','pontuacao','livre']],['rewardLootId','Recompensa da partida','ref:loot'],['allowRespawn','Permitir renascimento','boolean'],['notes','Notas','textarea']],groups:{}}\n};\nlet v3CurrentModule='missions',v3Selected='',v3StatusFilter='todos',v3Search='',v3AutoAllowed=false,v3AutoTimer=null,v3AutoLast='';\nconst v3HTML=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nfunction v3Data(){if(!state.systemsV3||typeof state.systemsV3!=='object')state.systemsV3={};for(const k of Object.keys(V3_DEFS))if(!Array.isArray(state.systemsV3[k]))state.systemsV3[k]=[];state.creatorSettings=state.creatorSettings||{};state.creatorSettings.schema='apoena.gamecreator.v3';return state.systemsV3;}\nfunction v3New(key){const d=V3_DEFS[key],i={id:'',name:'Novo '+d.title,status:'rascunho'};for(const [p,,type,values]of d.fields){if(i[p]!==undefined)continue;i[p]=type==='boolean'?false:type==='number'||type==='percent'?0:type==='choice'?(values?.[0]||''):''}for(const k of Object.keys(d.groups||{}))i[k]=[];return i}\nfunction v3All(key){if(key==='items')return state.items.map(x=>({id:x.id,name:x.name}));if(key==='characters')return (state.characters||[]).map(x=>({id:x.id,name:x.name}));if(key==='flows')return (state.flows||[]).map(x=>({id:x.id,name:x.name}));if(key==='assets')return (state.assets||[]).map(x=>({id:x.id,name:x.name}));return v3Data()[key]||[]}\nfunction v3Choices(type,value){const key=type.split(':')[1],list=v3All(key);return '<option value=\"\">— Nenhum —</option>'+list.map(x=>`<option value=\"${v3HTML(x.id)}\" ${String(value)===String(x.id)?'selected':''}>${v3HTML(x.name||x.id)} (${v3HTML(x.id)})</option>`).join('')}\nfunction v3Field(field,val,path='',model=null){const [key,label,type,choices]=field,id='v3_'+Math.random().toString(36).slice(2);let input='';const value=val??'';\n if(type==='textarea')input=`<textarea id=\"${id}\" data-v3-field=\"${v3HTML(key)}\" data-v3-path=\"${v3HTML(path)}\" rows=\"3\">${v3HTML(value)}</textarea>`;\n else if(type==='boolean')input=`<input id=\"${id}\" type=\"checkbox\" data-v3-field=\"${v3HTML(key)}\" data-v3-path=\"${v3HTML(path)}\" ${value?'checked':''}>`;\n else if(type==='choice')input=`<select id=\"${id}\" data-v3-field=\"${v3HTML(key)}\" data-v3-path=\"${v3HTML(path)}\">${choices.map(x=>`<option value=\"${v3HTML(x)}\" ${String(value)===String(x)?'selected':''}>${v3HTML(x.replaceAll('_',' '))}</option>`).join('')}</select>`;\n else if(type.startsWith('ref:'))input=`<select id=\"${id}\" data-v3-field=\"${v3HTML(key)}\" data-v3-path=\"${v3HTML(path)}\">${v3Choices(type,value)}</select>`;\n else if(type==='target'){const referenceOptions=['items','npcs','regions','flows'].flatMap(k=>v3All(k).map(x=>({id:x.id,name:x.name,kind:k})));input=`<select id=\"${id}\" data-v3-field=\"${v3HTML(key)}\" data-v3-path=\"${v3HTML(path)}\"><option value=\"\">— Escolha —</option>${referenceOptions.map(x=>`<option value=\"${v3HTML(x.id)}\" ${String(value)===String(x.id)?'selected':''}>${v3HTML(x.name)} · ${x.kind}</option>`).join('')}</select>`;}\n else input=`<input id=\"${id}\" data-v3-field=\"${v3HTML(key)}\" data-v3-path=\"${v3HTML(path)}\" type=\"${type==='percent'||type==='number'?'number':type==='date'?'date':'text'}\" ${type==='percent'?'min=\"0\" max=\"100\"':type==='number'?'min=\"0\" step=\"any\"':''} value=\"${v3HTML(value)}\">`;\n return `<label for=\"${id}\">${v3HTML(label)}</label>${input}`;\n}\nfunction v3Active(){return v3Data()[v3CurrentModule].find(x=>x.id===v3Selected)||null}\nfunction v3Tab(key){v3CurrentModule=key;v3Selected='';v3Draw()}\nfunction v3Draw(){v3Data();const cfg=V3_DEFS[v3CurrentModule],items=v3Data()[v3CurrentModule];\n document.querySelector('#v3ModuleHeader').textContent=cfg.emoji+' '+cfg.title;document.querySelector('#v3ModuleSubtitle').textContent=cfg.desc;\n document.querySelectorAll('[data-v3-module]').forEach(b=>b.classList.toggle('active',b.dataset.v3Module===v3CurrentModule));\n const list=items.filter(x=>v3StatusFilter==='todos'||x.status===v3StatusFilter).filter(x=>[x.name,x.id,x.description,x.notes].some(v=>String(v||'').toLowerCase().includes(v3Search))).sort((a,b)=>String(a.name).localeCompare(String(b.name),'pt-BR'));\n const box=document.querySelector('#v3RecordList');box.innerHTML=list.map(x=>`<button class=\"v3-record ${x.id===v3Selected?'active':''}\" data-v3-id=\"${v3HTML(x.id)}\"><strong>${v3HTML(x.name)}</strong><small>${v3HTML(x.id)} · ${v3HTML(x.status||'rascunho')}</small></button>`).join('')||'<p class=\"hint\">Nenhum registro. Clique em + Novo.</p>';\n box.querySelectorAll('[data-v3-id]').forEach(b=>b.onclick=()=>{v3Selected=b.dataset.v3Id;v3Draw()});\n const record=v3Active(),editor=document.querySelector('#v3RecordEditor');\n if(!record){editor.innerHTML='<div class=\"notice\">Escolha um registro ou clique em <strong>+ Novo</strong>. Os formulários ficam salvos no mesmo projeto editável das 52 poções.</div>';document.querySelector('#v3SelectedMeta').textContent=items.length+' registro(s)';return;}\n document.querySelector('#v3SelectedMeta').textContent=record.id;\n let html=`<div class=\"v3-form-head\"><div><h2>${v3HTML(record.name)}</h2><span class=\"hint\">ID permanente: ${v3HTML(record.id)} (não muda ao renomear)</span></div><div class=\"row\"><button id=\"v3Clone\">Duplicar</button><button id=\"v3Delete\" class=\"danger\">Excluir</button></div></div><div class=\"v3-fields\">`;\n html+=cfg.fields.map(f=>`<div class=\"v3-field\">${v3Field(f,record[f[0]])}</div>`).join('')+'</div>';\n for(const [groupKey,groupDef] of Object.entries(cfg.groups)){const arr=record[groupKey]||[];\n html+=`<section class=\"v3-group\"><div class=\"v3-form-head\"><h3>${v3HTML(groupDef.title)} (${arr.length})</h3><button data-v3-add=\"${groupKey}\">＋ Adicionar</button></div>`;\n if(!arr.length)html+='<p class=\"hint\">Ainda vazio.</p>';\n arr.forEach((row,ix)=>{html+=`<div class=\"v3-child\"><div class=\"v3-form-head\"><strong>${v3HTML(groupDef.title)} ${ix+1}</strong><button data-v3-remove=\"${groupKey}\" data-v3-index=\"${ix}\">Remover</button></div><div class=\"v3-fields\">`;\n html+=groupDef.fields.map(f=>`<div class=\"v3-field\">${v3Field(f,row[f[0]],groupKey+':'+ix)}</div>`).join('')+'</div></div>'});html+='</section>'}\n editor.innerHTML=html;\n editor.querySelectorAll('[data-v3-field]').forEach(node=>node.onchange=()=>v3Update(node));\n editor.querySelector('#v3Clone').onclick=()=>{const copy=structuredClone(record);copy.id=v3Unique(v3CurrentModule,record.id+'_copia');copy.name=record.name+' (cópia)';copy.status='rascunho';items.push(copy);v3Selected=copy.id;v3Mutate('Registro duplicado');v3Draw()};\n editor.querySelector('#v3Delete').onclick=()=>{if(confirm('Excluir '+record.name+'? As ligações em outros registros podem ficar pendentes.')){const idx=items.indexOf(record);items.splice(idx,1);v3Selected='';v3Mutate('Registro excluído');v3Draw()}};\n editor.querySelectorAll('[data-v3-add]').forEach(btn=>btn.onclick=()=>{const key=btn.dataset.v3Add,group=cfg.groups[key];const x={};for(const [p,,t,choices]of group.fields)x[p]=t==='number'||t==='percent'?0:t==='boolean'?false:t==='choice'?(choices?.[0]||''):'';record[key].push(x);v3Mutate('Linha adicionada');v3Draw()});\n editor.querySelectorAll('[data-v3-remove]').forEach(btn=>btn.onclick=()=>{record[btn.dataset.v3Remove].splice(Number(btn.dataset.v3Index),1);v3Mutate('Linha removida');v3Draw()});\n}\nfunction v3Unique(key,base){let id=slug(base||key),n=2;while(v3All(key).some(x=>x.id===id))id=slug(base)+'_'+n++;return id}\nfunction v3Update(node){const cur=v3Active();if(!cur)return;const key=node.dataset.v3Field,path=node.dataset.v3Path;const cfg=V3_DEFS[v3CurrentModule];const def=path?cfg.groups[path.split(':')[0]].fields.find(x=>x[0]===key):cfg.fields.find(x=>x[0]===key);let val=def[2]==='boolean'?node.checked:def[2]==='number'||def[2]==='percent'?Number(node.value||0):node.value;\n if(path){const [group,ix]=path.split(':');cur[group][Number(ix)][key]=val}else cur[key]=val;\n if(key==='name'){const active=document.querySelector('#v3ModuleHeader');if(active)active.title=val}\n v3Mutate('Registro atualizado');v3Draw();\n}\nfunction v3Mutate(label){const el=document.querySelector('#v3Toast');if(el)el.textContent=label+' • salve uma cópia JSON como backup';v3AutoSchedule();}\nfunction v3NewRecord(){const x=v3New(v3CurrentModule);x.id=v3Unique(v3CurrentModule,v3CurrentModule+'_novo');v3Data()[v3CurrentModule].push(x);v3Selected=x.id;v3Mutate('Novo registro criado');v3Draw()}\nfunction v3References(x,module,group=''){const cfg=V3_DEFS[module],fields=group?cfg.groups[group].fields:cfg.fields,issues=[];\n for(const field of fields){const [key,label,type]=field,val=x[key];if(type.startsWith('ref:')&&val&&!v3All(type.split(':')[1]).some(y=>y.id===val))issues.push(label+': '+val+' não encontrado');if(type==='target'&&val&&!['items','npcs','regions','flows'].some(k=>v3All(k).some(y=>y.id===val)))issues.push('Destino não encontrado: '+val)}\n return issues}\nfunction v3Validate(){const issues=[],counts={};for(const [key,cfg] of Object.entries(V3_DEFS)){const rows=v3Data()[key];counts[key]=rows.length;const known=new Set();for(const r of rows){if(!r.id||known.has(r.id))issues.push(cfg.title+': ID duplicado ou vazio');known.add(r.id);if(!r.name)issues.push(key+'/'+r.id+': sem nome');for(const str of v3References(r,key))issues.push(key+'/'+r.id+': '+str);for(const [gk]of Object.entries(cfg.groups||{}))for(const [index,line]of (r[gk]||[]).entries())for(const str of v3References(line,key,gk))issues.push(key+'/'+r.id+'/'+gk+'/'+(index+1)+': '+str);\n if(key==='loot')for(const line of r.entries||[]){if(Number(line.chance)<0||Number(line.chance)>100)issues.push('Drop '+r.id+': chance fora de 0–100%');if(Number(line.max)<Number(line.min))issues.push('Drop '+r.id+': máximo menor que mínimo')}\n if(key==='passes'&&r.start&&r.end&&r.end<r.start)issues.push('Passe '+r.id+': data final anterior à inicial');\n if(key==='modes'&&Number(r.maxPlayers)<Number(r.minPlayers))issues.push('Modo '+r.id+': máximo de jogadores menor que mínimo');\n if(key==='regions'&&r.scenePath&&!r.scenePath.startsWith('res://'))issues.push('Região '+r.id+': caminho da cena deve começar com res://');\n }}return {issues,counts,checked:new Date().toISOString()}}\nfunction v3Review(){const report=v3Validate();const root=document.querySelector('#v3Report');root.innerHTML=`<div class=\"database-stat\">${Object.entries(report.counts).map(([k,n])=>`<div class=\"stat\"><strong>${n}</strong>${v3HTML(V3_DEFS[k].title)}</div>`).join('')}</div><h3>${report.issues.length?'Pendências encontradas: '+report.issues.length:'Referências dos módulos v3 estão consistentes'}</h3>${report.issues.length?report.issues.slice(0,120).map(t=>`<div class=\"db-warn\">${v3HTML(t)}</div>`).join(''):'<p class=\"db-ok\">Sem erros de referência nos registros v3. Isso não substitui os testes das ações no Godot.</p>'}<p class=\"hint\">O verificador confere vínculos e dados locais, não execução de cenas do jogo.</p>`;\n}\nfunction v3LinkReport(){const pairs=[];for(const [key,cfg]of Object.entries(V3_DEFS)){for(const x of v3Data()[key]){for(const [p,label,type]of cfg.fields)if(type.startsWith('ref:')&&x[p])pairs.push({from:key+'/'+x.id,relation:label,to:type.split(':')[1]+'/'+x[p]});for(const [gk,g]of Object.entries(cfg.groups||{}))for(const row of x[gk]||[])for(const [p,label,type]of g.fields)if(type.startsWith('ref:')&&row[p])pairs.push({from:key+'/'+x.id,relation:label,to:type.split(':')[1]+'/'+row[p]})}}\n const holder=document.querySelector('#v3Relations');holder.innerHTML=pairs.length?pairs.map(r=>`<div class=\"v3-relation\"><strong>${v3HTML(r.from)}</strong><span> → ${v3HTML(r.relation)} → </span><strong>${v3HTML(r.to)}</strong></div>`).join(''):'<div class=\"notice\">Crie missões, diálogos, NPCs ou passes e vincule aos itens existentes. As relações aparecerão aqui.</div>';\n}\nfunction v3Preview(){const src=v3Active();const area=document.querySelector('#v3Preview');if(!src){area.innerHTML='Escolha um registro.';return;}\n if(v3CurrentModule==='missions'){const objectives=src.objectives||[],rewards=src.rewards||[];area.innerHTML=`<h3>Simulação local: ${v3HTML(src.name)}</h3><p class=\"hint\">Marque os objetivos sem alterar o inventário real.</p>${objectives.map((o,i)=>`<label class=\"flag\"><input type=\"checkbox\" class=\"v3-objective\"> ${v3HTML(o.type)} — ${v3HTML(o.targetId||'sem alvo')} × ${Number(o.amount)||1}</label>`).join('')||'<p>Sem objetivos cadastrados.</p>'}<div id=\"v3PreviewResult\" class=\"notice\">${objectives.length?'Complete os objetivos acima.':'Cadastre objetivos para testar.'}</div><p><strong>Recompensas previstas:</strong> ${rewards.map(r=>v3HTML(r.kind+' '+r.amount+' '+(r.itemId||''))).join(', ')||'nenhuma'}</p>`;const boxes=[...area.querySelectorAll('.v3-objective')];boxes.forEach(x=>x.onchange=()=>area.querySelector('#v3PreviewResult').textContent=boxes.every(x=>x.checked)?'Objetivos concluídos (apenas simulação).':'Missão em andamento (simulação).');}\n else if(v3CurrentModule==='loot'){area.innerHTML=`<h3>Sortear drops de teste</h3><button id=\"v3RollLoot\">Simular 1 queda</button><p id=\"v3LootResult\" class=\"notice\">Não altera o inventário real.</p>`;area.querySelector('#v3RollLoot').onclick=()=>{const got=(src.entries||[]).filter(r=>Math.random()*100<Number(r.chance||0)).map(r=>{const lo=Math.max(0,Number(r.min||1)),hi=Math.max(lo,Number(r.max||lo));const n=lo+Math.floor(Math.random()*(hi-lo+1));return (v3All('items').find(x=>x.id===r.itemId)?.name||r.itemId||'item sem vínculo')+' × '+n});area.querySelector('#v3LootResult').textContent=got.join(', ')||'Nenhum item caiu nesta simulação.'}}\n else if(v3CurrentModule==='passes'){area.innerHTML=`<h3>Marcos do passe (prévia)</h3>${(src.levels||[]).map(l=>`<div class=\"v3-relation\">Nível ${Number(l.level)||0} — ${Number(l.points)||0} pontos — ${v3HTML(v3All('items').find(x=>x.id===l.itemId)?.name||'recompensa sem item')} × ${Number(l.amount)||1}</div>`).join('')||'Nenhum marco cadastrado.'}<p class=\"hint\">Datas e progresso online dependem de implementação futura no jogo.</p>`}\n else area.innerHTML='<p class=\"notice\">Os dados deste módulo são editáveis e exportáveis; a execução no jogo depende do conector Godot.</p>';\n}\nfunction v3JSONExport(){const report=v3Validate(),data={schema:'apoena.systems.v3',version:3,project:state.name,systems:v3Data(),validation:report};jsonDownload(data,'APOENA_SISTEMAS_RPG_V3.json')}\nconst V3_GODOT_CATALOG=`extends RefCounted\\n## Leitor de dados APOENA Game Creator 3; NAO executa scripts arbitrarios.\\nconst CAMINHO := \"res://dados/apoena_sistemas_v3.json\"\\nstatic func carregar(caminho: String = CAMINHO) -> Dictionary:\\n    if not FileAccess.file_exists(caminho):\\n        push_warning(\"Apoena v3: catalogo nao encontrado: \" + caminho)\\n        return {}\\n    var raw: String = FileAccess.get_file_as_string(caminho)\\n    var parsed: Variant = JSON.parse_string(raw)\\n    if not (parsed is Dictionary):\\n        push_error(\"Apoena v3: JSON invalido.\")\\n        return {}\\n    if str(parsed.get(\"schema\", \"\")) != \"apoena.systems.v3\":\\n        push_error(\"Apoena v3: schema inesperado.\")\\n        return {}\\n    return parsed\\nstatic func registros(tipo: String) -> Array:\\n    var base: Dictionary = carregar()\\n    var sistemas: Dictionary = base.get(\"systems\", {})\\n    var regs: Variant = sistemas.get(tipo, [])\\n    return regs if regs is Array else []\\nstatic func por_id(tipo: String, registro_id: String) -> Dictionary:\\n    for entry in registros(tipo):\\n        if entry is Dictionary and str(entry.get(\"id\", \"\")) == registro_id:\\n            return entry\\n    return {}\\n`;\nconst v3OldZip=zipPack;\nzipPack=function(files){if(files.some(x=>x[0]==='dados/apoena_catalogo_itens.json')){const report=v3Validate();files.push(['dados/apoena_sistemas_v3.json',JSON.stringify({schema:'apoena.systems.v3',version:3,project:state.name,systems:v3Data()},null,2)]);files.push(['dados/apoena_validacao_v3.json',JSON.stringify(report,null,2)]);files.push(['scripts/sistemas/apoena_sistemas_v3_catalogo.gd',V3_GODOT_CATALOG]);files.push(['GUIA_V3_GODOT.txt','Apoena Game Creator v3: extraia em uma COPIA do projeto Godot 4.\\r\\nO arquivo scripts/sistemas/apoena_sistemas_v3_catalogo.gd le dados JSON por ID.\\r\\nEle nao implementa por si so missões, IA, multiplayer, temporadas nem passe online.\\r\\nVincule os dados aos scripts oficiais do jogo e teste antes de publicar.\\r\\nNao sobrescreva a versao principal automaticamente.\\r\\n'])}return v3OldZip(files)};\nfunction v3BackupWarn(){const msg=document.querySelector('#v3AutosaveStatus');if(msg)msg.textContent='Salvamento local automático ativo (IndexedDB, se disponível). Faça também backup pelo botão Salvar projeto.'}\nfunction v3OpenDb(){return new Promise((resolve,reject)=>{if(!window.indexedDB){reject(Error('IndexedDB indisponível'));return}const req=indexedDB.open('apoena_game_creator_v3',1);req.onupgradeneeded=()=>req.result.createObjectStore('backups');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}\nasync function v3DbPut(snapshot){const db=await v3OpenDb();return new Promise((resolve,reject)=>{const tr=db.transaction('backups','readwrite');tr.objectStore('backups').put({at:new Date().toISOString(),state:snapshot},'auto');tr.oncomplete=()=>{db.close();resolve()};tr.onerror=()=>{db.close();reject(tr.error)}})}\nasync function v3DbGet(){const db=await v3OpenDb();return new Promise((resolve,reject)=>{const tr=db.transaction('backups','readonly');const req=tr.objectStore('backups').get('auto');req.onsuccess=()=>{db.close();resolve(req.result)};req.onerror=()=>{db.close();reject(req.error)}})}\nfunction v3AutoSchedule(){if(!v3AutoAllowed)return;clearTimeout(v3AutoTimer);v3AutoTimer=setTimeout(async()=>{try{const snapshot=JSON.stringify(state);await v3DbPut(snapshot);v3AutoLast=new Date().toLocaleTimeString('pt-BR');const el=document.querySelector('#v3AutosaveStatus');if(el)el.textContent='Cópia local salva às '+v3AutoLast+' (não substitui backup JSON).'}catch(err){const el=document.querySelector('#v3AutosaveStatus');if(el)el.textContent='Salvamento local indisponível: '+err.message+'. Use Salvar projeto editável.'}},3500)}\nasync function v3Restore(){try{const data=await v3DbGet();if(!data?.state)throw Error('Não existe cópia local.');if(!confirm('Restaurar a cópia automática salva em '+new Date(data.at).toLocaleString('pt-BR')+'? Substituirá as edições desta sessão.'))return;const imported=JSON.parse(data.state);if(imported.schema!=='apoena.central.v1'||!Array.isArray(imported.assets)||!Array.isArray(imported.items)||!imported.screens)throw Error('Cópia inválida');Object.assign(state,imported);ensureCreatorState();seedOfficialPotions();v3Data();v3Selected='';refreshAssetLists();renderLayout();renderRecipes();renderDatabase();creatorRenderHome();creatorRenderCharacters();creatorRenderFlows();v3Draw();v3Review();document.querySelector('#v3AutosaveStatus').textContent='Cópia automática recuperada.';}catch(e){alert('Não consegui recuperar: '+e.message)}}\nasync function v3OfferRestore(){try{const data=await v3DbGet();const el=document.querySelector('#v3BackupOffer');if(data?.state){el.hidden=false;el.textContent='Há uma cópia automática de '+new Date(data.at).toLocaleString('pt-BR')+'. Clique em Restaurar cópia local para recuperá-la.'}}catch(e){v3BackupWarn()}finally{v3AutoAllowed=true}}\nfunction v3Init(){v3Data();const nav=document.querySelector('nav.tabs'),root=document.querySelector('.main');\n nav.insertAdjacentHTML('beforeend','<button class=\"tab\" data-page=\"v3\">▣ Sistemas RPG v3</button><button class=\"tab\" data-page=\"v3links\">⇄ Relações e segurança</button>');\n root.insertAdjacentHTML('beforeend',`<section class=\"page\" id=\"page-v3\"><div class=\"panel\"><div class=\"v3-form-head\"><div><h2>Sistemas RPG • Apoena Game Creator v3</h2><p class=\"hint\">Missões, passes, diálogos e demais regras compartilham o catálogo de itens e personagens da Central.</p></div><button id=\"v3ExportJSON\">⬇ Exportar sistemas JSON</button></div><div class=\"v3-module-grid\">${Object.entries(V3_DEFS).map(([key,c])=>`<button data-v3-module=\"${key}\">${c.emoji} ${v3HTML(c.title)}</button>`).join('')}</div><div class=\"v3-main\"><aside class=\"v3-pane\"><h3 id=\"v3ModuleHeader\"></h3><p class=\"hint\" id=\"v3ModuleSubtitle\"></p><div class=\"row\"><button id=\"v3New\" class=\"primary\">＋ Novo</button><button id=\"v3Validate\">✓ Validar</button></div><label>Buscar por nome/ID</label><input id=\"v3Search\" placeholder=\"Buscar...\"><label>Filtrar estado</label><select id=\"v3Filter\"><option value=\"todos\">Todos</option><option value=\"rascunho\">Rascunhos</option><option value=\"revisao\">Em revisão</option><option value=\"aprovado\">Aprovados</option></select><div id=\"v3RecordList\" class=\"v3-record-list\"></div></aside><main class=\"v3-pane\"><div id=\"v3SelectedMeta\" class=\"hint\"></div><div id=\"v3RecordEditor\"></div><div id=\"v3Toast\" class=\"hint\"></div><div class=\"v3-group\"><div class=\"v3-form-head\"><h3>Testar (sem alterar dados reais)</h3><button id=\"v3Simulate\">▶ Prévia</button></div><div id=\"v3Preview\" class=\"hint\">Escolha um registro e clique em Prévia.</div></div></main></div></div></section><section class=\"page\" id=\"page-v3links\"><div class=\"panel\"><h2>Relações do banco e segurança</h2><p class=\"hint\">Antes de exportar, confira referências entre receitas, missões, personagens, eventos e recompensas. Ações online continuam pendentes da implementação no Godot.</p><div class=\"row\"><button id=\"v3CheckAll\" class=\"primary\">✓ Verificar dados</button><button id=\"v3ShowLinks\">⇄ Atualizar relações</button><button id=\"v3Restore\" class=\"gold\">↶ Restaurar cópia local</button><button id=\"v3Backup\">⬇ Backup completo JSON</button></div><div class=\"notice\" id=\"v3BackupOffer\" hidden></div><p id=\"v3AutosaveStatus\" class=\"hint\">Preparando salvamento local...</p><div id=\"v3Report\"></div><h3>Mapa de vínculos</h3><div id=\"v3Relations\" class=\"v3-relation-list\"></div></div></section>`);\n document.querySelectorAll('[data-v3-module]').forEach(b=>b.onclick=()=>v3Tab(b.dataset.v3Module));document.querySelector('#v3New').onclick=v3NewRecord;document.querySelector('#v3Validate').onclick=()=>{switchPage('v3links');v3Review();v3LinkReport()};document.querySelector('#v3CheckAll').onclick=v3Review;document.querySelector('#v3ShowLinks').onclick=v3LinkReport;document.querySelector('#v3Simulate').onclick=v3Preview;\n document.querySelector('#v3Search').oninput=e=>{v3Search=e.target.value.toLowerCase();v3Draw()};document.querySelector('#v3Filter').onchange=e=>{v3StatusFilter=e.target.value;v3Draw()};document.querySelector('#v3ExportJSON').onclick=v3JSONExport;\n document.querySelector('#v3Restore').onclick=v3Restore;document.querySelector('#v3Backup').onclick=()=>document.querySelector('#saveProject').click();\n document.querySelectorAll('.tab[data-page=\"v3\"],.tab[data-page=\"v3links\"]').forEach(b=>b.onclick=()=>{switchPage(b.dataset.page);location.hash=b.dataset.page;if(b.dataset.page==='v3'){v3Draw()}else{v3Review();v3LinkReport()}});\n document.querySelector('#projectFile').addEventListener('change',()=>setTimeout(()=>{v3Data();v3Selected='';v3Draw();v3Review();v3AutoSchedule()},600));\n document.addEventListener('change',e=>{if(!e.target?.matches?.('#projectFile'))v3AutoSchedule()},true);document.addEventListener('click',e=>{if(e.target.closest('button')&&!e.target.matches('#v3Restore'))v3AutoSchedule()},true);\n const b=document.createElement('style');b.textContent=`.v3-module-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(142px,1fr));gap:7px;margin:12px 0}.v3-module-grid button{text-align:left;font-size:12px}.v3-module-grid button.active{border-color:var(--gold);color:var(--gold);background:#284652}.v3-main{display:grid;grid-template-columns:minmax(260px,330px) minmax(0,1fr);gap:12px;margin-top:12px}.v3-pane{background:#101e2b;border:1px solid #385365;border-radius:10px;padding:12px;min-width:0}.v3-record-list{max-height:510px;overflow:auto;display:grid;gap:4px;margin-top:10px}.v3-record{display:flex;align-items:flex-start;flex-direction:column;text-align:left;gap:3px;overflow-wrap:anywhere}.v3-record small{font-size:10px;color:var(--muted)}.v3-record.active{background:#215060;border-color:#67d1d8}.v3-form-head{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.v3-form-head h2{margin:0 0 5px}.v3-fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:5px 14px;margin:12px 0}.v3-field{min-width:0}.v3-field>input[type=checkbox]{width:25px;height:25px}.v3-group{background:#172a39;border:1px solid #3d5669;border-radius:9px;padding:13px;margin-top:15px}.v3-child{border:1px solid #395363;background:#10212e;border-radius:7px;margin-top:8px;padding:9px}.v3-relation{padding:10px;border:1px solid var(--border);border-radius:7px;margin-bottom:6px;font-size:12px;overflow-wrap:anywhere}@media(max-width:790px){.v3-main{grid-template-columns:1fr}.v3-module-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}`;document.head.appendChild(b);\n v3Draw();v3OfferRestore();const hash=location.hash.slice(1);if(hash==='v3'||hash==='v3links')document.querySelector('.tab[data-page=\"'+hash+'\"]').click();\n}\nv3Init();window.ApoenaV3Test={schema:()=>Object.keys(V3_DEFS),validate:v3Validate,data:v3Data,newRecord:(k,name)=>{v3Tab(k);v3NewRecord();if(name){v3Active().name=name;v3Draw()}return v3Active()},refs:v3All,autosave:v3AutoSchedule};\n})();\n\n</script>\n<script>\n'use strict';\n/* Apoena Game Creator 3.3 - Animações e controles configuráveis.\n   Não executa scripts das importações, não altera o jogo oficial. */\n(() => {\nconst studioDefs = [\n ['idle','Parado / Idle','idle|parado|stand|breath'],\n ['walk','Andar (movimento)','walk|andar|walking|locomotion'],\n ['run','Correr','run|correr|sprint|jog'],\n ['basic_attack','Ataque simples (A)','punch|soco|attack|jab|hit|boxing'],\n ['defend','Defender','defend|guard|block|shield|defesa'],\n ['jump','Pular','jump|pular|leap'],\n ['aim','Mirar','aim|mira|target'],\n ['skill_q','Q - Poder mágico','cast|spell|magia|magic|water|projectile|sphere'],\n ['skill_w','W - Habilidade','combo|attack|cast|spell'],\n ['skill_e','E - Proteção','guard|shield|defend|barrier'],\n ['skill_r','R - Poder especial','ultimate|special|finisher|skill'],\n ['skill_f','F - Especial','special|ultimate|celebrate|power'],\n ['damage','Receber dano','hurt|damage|pain|hit'],\n ['death','Derrotado','death|die|knockout|fall']\n];\nconst controlActions = {\n exploracao_pc:[['move_forward','Frente','W'],['move_left','Esquerda','A'],['move_back','Trás','S'],['move_right','Direita','D'],['camera','Câmera / mira','MOUSE_MOVE'],['attack','Ataque','MOUSE_LEFT'],['defend','Defender','MOUSE_RIGHT'],['jump','Pular','Space'],['sprint','Correr','Shift'],['interact','Interagir','G'],['inventory','Inventário','I'],['pause','Pausa','Escape']],\n exploracao_android:[['move','Analógico de movimento','TOUCH_MOVE'],['camera','Câmera / mira','TOUCH_DRAG'],['attack','Atacar','TOUCH'],['defend','Defender','TOUCH'],['jump','Pular','TOUCH'],['sprint','Correr','TOUCH'],['interact','Interagir','TOUCH'],['inventory','Inventário','TOUCH'],['pause','Pausa','TOUCH']],\n moba_pc:[['move','Movimentar / selecionar destino','MOUSE_RIGHT'],['target','Selecionar alvo','MOUSE_LEFT'],['attack','Ataque básico','A'],['skill_q','Q','Q'],['skill_w','W','W'],['skill_e','E','E'],['skill_r','R','R'],['skill_f','F / especial','F'],['shop','Loja da partida','P'],['score','Placar','Tab'],['pause','Pausa','Escape']],\n moba_android:[['move','Analógico de movimento','TOUCH_MOVE'],['camera','Mover câmera','TOUCH_DRAG'],['target','Mirar','TOUCH'],['attack','Ataque','TOUCH'],['skill_q','Q','TOUCH'],['skill_w','W','TOUCH'],['skill_e','E','TOUCH'],['skill_r','R','TOUCH'],['skill_f','F','TOUCH'],['shop','Loja da partida','TOUCH'],['score','Placar','TOUCH'],['pause','Pausa','TOUCH']]\n};\nconst $s=id=>document.getElementById(id);\nconst safe=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst keyId=s=>String(s||'sem_nome').normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').toLowerCase().replace(/[^a-z0-9_]+/g,'_').slice(0,70);\nfunction state33(){\n if(!state.creatorStudio || typeof state.creatorStudio!=='object')state.creatorStudio={};\n let x=state.creatorStudio;\n if(!Array.isArray(x.models))x.models=[];\n if(!x.characterBindings||typeof x.characterBindings!=='object')x.characterBindings={};\n if(!x.profiles||typeof x.profiles!=='object')x.profiles={};\n for(const [key,defs]of Object.entries(controlActions))if(!Array.isArray(x.profiles[key])){\n  const touch=key.endsWith('android');let i=0;\n  x.profiles[key]=defs.map(d=>({action:d[0],label:d[1],input:d[2],enabled:true,x:touch?((i%4)*18+30):5,y:touch?(i++<2?74:45+Math.floor((i-2)/4)*15):7+6*i++,size:touch?12:9,opacity:.85}));\n }\n return x;\n}\nfunction characters(){return Array.isArray(state.characters)?state.characters:[]}\nlet charId='',controlProfile='exploracao_android',focusControl='',modelPreviewMode='idle',modelPreviewPos=0,sliderRAF=0;\nfunction characterBinding(id){const all=state33().characterBindings;const k=String(id||'');if(!all[k])all[k]={modelId:'',extraAssetIds:[],mappings:{}};if(!Array.isArray(all[k].extraAssetIds))all[k].extraAssetIds=[];return all[k]}\nfunction modelById(id){return state33().models.find(a=>a.id===id)}\nfunction allCharacterClips(bd){const ids=[bd.modelId,...(bd.extraAssetIds||[])].filter(Boolean);const seen=new Set();return ids.flatMap(id=>{if(seen.has(id))return [];seen.add(id);const m=modelById(id);return m?m.clips.map(c=>({...c,sourceAssetId:id,sourceName:m.name,kind:m.kind})):[]});}\nfunction clipValue(c){return c.sourceAssetId+'::'+c.name;}\nfunction clipMatches(c,m){return String(m.sourceAssetId||'')===c.sourceAssetId && String(m.clip||'')===c.name || (!m.sourceAssetId && m.clip===c.name);}\nfunction modelOptions(sel){return '<option value=\"\">— Sem modelo —</option>'+state33().models.map(m=>`<option value=\"${safe(m.id)}\" ${m.id===sel?'selected':''}>${safe(m.name)} (${m.clips.length} clipes)</option>`).join('')}\nfunction studioOptions(){let all=characters();let old=$s('studioCharacter').value; if(!charId||!all.some(c=>c.id===charId))charId=all[0]?.id||'';\n $s('studioCharacter').innerHTML=all.map(c=>`<option value=\"${safe(c.id)}\">${safe(c.name)}</option>`).join('')||'<option value=\"\">Cadastre um personagem na aba Personagens</option>';\n $s('studioCharacter').value=charId;\n if(old && all.some(c=>c.id===old)){$s('studioCharacter').value=old;charId=old}\n}\nfunction renderStudio(){state33();studioOptions();const ch=characters().find(c=>c.id===charId);const bd=characterBinding(charId);const model=modelById(bd.modelId);\n $s('studioModel').innerHTML=modelOptions(bd.modelId);\n const pic=state.assets?.find(a=>a.id===ch?.retratoId);\n $s('studioPortrait').innerHTML=pic?`<img src=\"${pic.data}\" alt=\"Retrato de ${safe(ch.name)}\" style=\"width:100%;height:100%;object-fit:contain\">`:`<div class=\"studio-mannequin\">♟<small>Sem retrato</small></div>`;\n $s('studioModelStatus').textContent=model?`${model.name} • ${allCharacterClips(bd).length} clipes associados • ${model.kind.toUpperCase()}`:'Importe um GLB com animações ou FBXs separados.';\n $s('studioNo3dNote').textContent=model?'Prévia de pose: retrato do personagem. Clipes detectados abaixo; animação 3D real disponível na cena exportada para Godot.':'O arquivo de modelo 3D ainda não foi cadastrado. A prévia usa o retrato da ficha.';\n const clips=allCharacterClips(bd);\n $s('studioClipList').innerHTML=clips.map(c=>`<div class=\"studio-clip\"><span>▶ ${safe(c.name)}</span><small>${safe(c.sourceName)} • ${safe(c.kind.toUpperCase())}</small></div>`).join('')||'<p class=\"hint\">Nenhuma animação encontrada. Importe arquivos ou use a atribuição manual.</p>';\n $s('studioBindingTable').innerHTML=studioDefs.map(d=>{const m=bd.mappings[d[0]]||{},missing=m.clip&&!clips.some(c=>clipMatches(c,m));return `<tr><td><strong>${safe(d[1])}</strong><small>${safe(d[0])}</small></td><td><select data-studio-map=\"${d[0]}\"><option value=\"\">— Não vinculada —</option>${clips.map(c=>`<option value=\"${safe(clipValue(c))}\" ${clipMatches(c,m)?'selected':''}>${safe(c.name)} · ${safe(c.sourceName)}</option>`).join('')}</select>${missing?'<small class=\"studio-warn\">⚠ Clipe não encontrado no modelo atual</small>':''}</td><td><input aria-label=\"Momento do efeito entre 0 e 1\" type=\"number\" min=\"0\" max=\"1\" step=\"0.05\" value=\"${Number(m.eventAt??.5)}\" data-studio-time=\"${d[0]}\"></td><td><input aria-label=\"Repetir animação\" type=\"checkbox\" data-studio-loop=\"${d[0]}\" ${m.loop?'checked':''}></td></tr>`}).join('');\n $s('studioBindingTable').querySelectorAll('[data-studio-map]').forEach(s=>s.onchange=()=>{let k=s.dataset.studioMap;bd.mappings[k]??={};const c=clips.find(c=>clipValue(c)===s.value);bd.mappings[k].clip=c?.name||'';bd.mappings[k].sourceAssetId=c?.sourceAssetId||'';renderStudio();studioMessage('Vínculo atualizado: '+k)});\n $s('studioBindingTable').querySelectorAll('[data-studio-time]').forEach(el=>el.onchange=()=>{const k=el.dataset.studioTime;bd.mappings[k]??={};bd.mappings[k].eventAt=Math.min(1,Math.max(0,Number(el.value)||0));el.value=bd.mappings[k].eventAt});\n $s('studioBindingTable').querySelectorAll('[data-studio-loop]').forEach(el=>el.onchange=()=>{const k=el.dataset.studioLoop;bd.mappings[k]??={};bd.mappings[k].loop=el.checked});\n $s('studioClipCount').textContent=clips.length+' animações disponíveis';\n updateStudioPreview();\n}\nfunction studioMessage(s){$s('studioMsg').textContent=s;status(s)}\nfunction suggestBindings(){const bd=characterBinding(charId);const clips=allCharacterClips(bd);if(!clips.length)return studioMessage('Importe um GLB ou animações FBX para este personagem.');let count=0;for(const [id,_,pat] of studioDefs){if(bd.mappings[id]?.clip)continue;const expr=new RegExp(pat,'i'),guess=clips.find(c=>expr.test(c.name));if(guess){bd.mappings[id]={clip:guess.name,sourceAssetId:guess.sourceAssetId,eventAt:id==='idle'||id==='walk'||id==='run'?0:.5,loop:['idle','walk','run','aim'].includes(id)};count++;}}renderStudio();studioMessage(count+' sugestões aplicadas; confira os movimentos e altere o que não corresponder.')}\n// Le somente o bloco JSON do GLB (glTF 2.0). Não executa conteúdo importado.\nfunction parseGLB(buffer){const v=new DataView(buffer);if(v.byteLength<20||v.getUint32(0,true)!==0x46546c67||v.getUint32(4,true)!==2)throw Error('Arquivo GLB inválido ou formato diferente de glTF 2.0.');const total=v.getUint32(8,true);if(total!==v.byteLength)throw Error('Tamanho do GLB não corresponde ao arquivo.');let offset=12,json=null;\n while(offset+8<=total){const len=v.getUint32(offset,true),kind=v.getUint32(offset+4,true);offset+=8;if(len>total-offset)throw Error('Bloco GLB incompleto.');if(kind===0x4e4f534a&&!json){const raw=new TextDecoder().decode(new Uint8Array(buffer,offset,len));json=JSON.parse(raw.replace(/\\u0000+$/g,'').trim());}offset+=len;}\n if(!json||!Array.isArray(json.nodes))throw Error('GLB não contém estrutura glTF válida.');return json;}\nfunction makeClips(gltf,origin){return (gltf.animations||[]).map((a,i)=>({name:String(a.name||'Animacao_'+(i+1)).slice(0,100),origin}));}\nfunction loadDataURL(file){return new Promise((resolve,reject)=>{const reader=new FileReader;reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Falha ao ler arquivo'));reader.readAsDataURL(file)});}\nasync function importModels(files){const list=Array.from(files||[]);if(!list.length)return;const allowed=['glb','gltf','fbx'];let done=0;\n for(const file of list){try{const extension=file.name.split('.').pop().toLowerCase();if(!allowed.includes(extension))throw Error('Utilize GLB, GLTF ou FBX.');if(file.size>50_000_000)throw Error('Máximo 50 MB por arquivo.');\n let clips=[];if(extension==='glb')clips=makeClips(parseGLB(await file.arrayBuffer()),'GLB');else if(extension==='gltf'){const g=JSON.parse(await file.text());clips=makeClips(g,'GLTF');}else clips=[{name:file.name.replace(/\\.fbx$/i,''),origin:'FBX (nome do arquivo, verificar rig)'}];\n const id='modelo_'+keyId(file.name)+'_'+Math.random().toString(36).slice(2,8),data=await loadDataURL(file);\n state33().models.push({id,name:file.name,kind:extension,clips,data,filePath:'res://arte/game_creator_3d/'+id+'.'+extension,bytes:file.size});\n const bd=characterBinding(charId);if(extension==='glb'&&!modelById(bd.modelId)){bd.modelId=id;}else if(extension==='glb' && modelById(bd.modelId)?.kind==='fbx'){bd.extraAssetIds.push(bd.modelId);bd.modelId=id;}else if(!bd.modelId){bd.modelId=id;}else{bd.extraAssetIds.push(id);}\n done++;\n }catch(e){studioMessage('Não importei '+file.name+': '+e.message);}}\n renderStudio();studioMessage(done+' arquivo(s) 3D importado(s). Animações FBX isoladas podem exigir retarget no Godot.');}\nfunction refreshBindings(){const bd=characterBinding(charId);const clips=allCharacterClips(bd);for(const d of studioDefs){const cfg=bd.mappings[d[0]];if(cfg?.clip&&!clips.some(c=>clipMatches(c,cfg))){/*preservar aviso*/}}}\nfunction updateStudioPreview(){let action=$s('studioPreviewAction')?.value||'idle';const bd=characterBinding(charId),model=modelById(bd.modelId),cfg=bd.mappings[action]||{};const clip=cfg.clip||'Não vinculada';$s('studioPreviewClip').textContent=clip;$s('studioPreviewActionName').textContent=studioDefs.find(x=>x[0]===action)?.[1]||action;$s('studioPreviewMarker').style.left=Math.round(Number(cfg.eventAt??.5)*100)+'%';}\nfunction studioPlay(){const btn=$s('studioPlay');if(sliderRAF)cancelAnimationFrame(sliderRAF);let start=performance.now();btn.textContent='↻ Reiniciar demonstração';const bar=$s('studioPlayhead');const go=time=>{let pct=Math.min(100,(time-start)/2200*100);bar.style.width=pct+'%';if(pct<100)sliderRAF=requestAnimationFrame(go)};sliderRAF=requestAnimationFrame(go);studioMessage('Linha do tempo ilustrativa — para ver o movimento 3D real, abra a prévia no Godot.')}\nfunction renderProfiles(){const defs=controlActions[controlProfile],pf=state33().profiles[controlProfile];if(!Array.isArray(pf))return;$s('controlProfile').value=controlProfile;\n const preview=$s('controlStage');preview.innerHTML='<div class=\"control-stage-title\">'+safe(controlProfile.replace('_',' / ').toUpperCase())+'</div>';\n for(const c of pf.filter(t=>t.enabled)){const b=document.createElement('div');b.className='control-node';b.dataset.action=c.action;b.title=c.label;b.textContent=c.label;b.style.left=c.x+'%';b.style.top=c.y+'%';b.style.width=c.size+'%';b.style.height='auto';b.style.minHeight=Math.max(34,c.size*3)+'px';b.style.opacity=c.opacity;b.style.borderColor=focusControl===c.action?'#ffd471':'#86d4e0';b.addEventListener('pointerdown',onControlDrag);preview.append(b)}\n $s('controlItemList').innerHTML=pf.map(c=>`<button data-ctl-select=\"${safe(c.action)}\" class=\"studio-action ${focusControl===c.action?'active':''}\">${c.enabled?'●':'○'} ${safe(c.label)} <small>${safe(c.input)}</small></button>`).join('');\n $s('controlItemList').querySelectorAll('[data-ctl-select]').forEach(b=>b.onclick=()=>{focusControl=b.dataset.ctlSelect;renderProfiles()});\n const item=pf.find(c=>c.action===focusControl)||pf[0];if(!item)return;if(!focusControl)focusControl=item.action;\n $s('controlSelectedName').textContent=item.label;for(const [id,val]of [['controlBindKey',item.input],['controlSize',item.size],['controlOpacity',item.opacity],['controlEnabled',item.enabled]]){$s(id)[id==='controlEnabled'?'checked':'value']=val;}\n $s('controlCoords').textContent=`Posição: ${item.x.toFixed(1)}% / ${item.y.toFixed(1)}%`;\n}\nfunction onControlDrag(e){e.preventDefault();let el=e.currentTarget,action=el.dataset.action;if(focusControl!==action){focusControl=action;renderProfiles();el=$s('controlStage').querySelector(`[data-action=\"${CSS.escape(action)}\"]`)}const item=state33().profiles[controlProfile].find(x=>x.action===action);if(!item)return;const rect=$s('controlStage').getBoundingClientRect();\n function move(ev){if(ev.pointerId!==e.pointerId)return;item.x=Math.round(Math.max(0,Math.min(99,((ev.clientX-rect.left)/rect.width)*100))*10)/10;item.y=Math.round(Math.max(0,Math.min(99,((ev.clientY-rect.top)/rect.height)*100))*10)/10;el.style.left=item.x+'%';el.style.top=item.y+'%';$s('controlCoords').textContent=`Posição: ${item.x}% / ${item.y}%`;}\n function end(ev){if(ev.pointerId!==e.pointerId)return;el.removeEventListener('pointermove',move);el.removeEventListener('pointerup',end);el.removeEventListener('pointercancel',end);renderProfiles();}\n el.setPointerCapture(e.pointerId);el.addEventListener('pointermove',move);el.addEventListener('pointerup',end);el.addEventListener('pointercancel',end);\n}\nfunction changeControl(id,v){const item=state33().profiles[controlProfile].find(x=>x.action===focusControl);if(!item)return;item[id]=v;renderProfiles();}\nfunction controlReport(){const s=state33(),errors=[];for(const [id,bd]of Object.entries(s.characterBindings)){const m=modelById(bd.modelId);if(bd.modelId&&!m)errors.push('Personagem '+id+' aponta para modelo não encontrado');const clips=allCharacterClips(bd);for(const [action,cfg]of Object.entries(bd.mappings)){if(cfg?.clip&&!clips.some(c=>clipMatches(c,cfg)))errors.push('Clipe ausente: '+id+' / '+action+' → '+cfg.clip);}}\n for(const [id,profile] of Object.entries(s.profiles)){const map=new Map;for(const x of profile){if(!x.enabled||!x.input||x.input.startsWith('TOUCH')||x.input.startsWith('MOUSE_MOVE'))continue;const key=x.input.toLowerCase();if(map.has(key))errors.push('Controles duplicados no perfil '+id+': '+map.get(key)+' / '+x.action+' ('+x.input+')');map.set(key,x.action);}}\n return errors;}\nconst GODOT_ANIMATIONS=`extends RefCounted\n## Game Creator v3.5: metadados de vinculos de animacoes exportados. Nao usa eval.\nconst PATH := \"res://dados/apoena_animacoes_3d_v1.json\"\nstatic func carregar() -> Dictionary:\n    if not FileAccess.file_exists(PATH):\n        return {}\n    var result: Variant = JSON.parse_string(FileAccess.get_file_as_string(PATH))\n    if not (result is Dictionary) or str(result.get(\"schema\", \"\")) != \"apoena.animations.v1\":\n        return {}\n    return result\nstatic func vinculo(personagem_id: String, acao: String) -> Dictionary:\n    var all: Dictionary = carregar().get(\"bindings\", {})\n    var character: Dictionary = all.get(personagem_id, {})\n    var maps: Dictionary = character.get(\"mappings\", {})\n    return maps.get(acao, {})\nstatic func animacao_para(player: AnimationPlayer, personagem_id: String, acao: String) -> bool:\n    if player == null:\n        return false\n    var cfg: Dictionary = vinculo(personagem_id, acao)\n    var nome: String = str(cfg.get(\"clip\", \"\"))\n    if nome.is_empty():\n        return false\n    if not player.has_animation(nome):\n        push_warning(\"Animacao ainda nao encontrada no AnimationPlayer: \" + nome)\n        return false\n    player.play(nome)\n    return true\n`;\nconst GODOT_CONTROLS=`extends RefCounted\n## Le perfis exportados do Game Creator 3.3; aplicar em cenas reais requer adaptador.\nconst PATH := \"res://dados/apoena_controles_v1.json\"\nstatic func carregar() -> Dictionary:\n    if not FileAccess.file_exists(PATH):\n        return {}\n    var parsed: Variant = JSON.parse_string(FileAccess.get_file_as_string(PATH))\n    if not (parsed is Dictionary) or str(parsed.get(\"schema\", \"\")) != \"apoena.controls.v1\":\n        return {}\n    return parsed\nstatic func perfil(modo: String, plataforma: String) -> Array:\n    var key: String = modo + \"_\" + plataforma\n    var cfg: Dictionary = carregar().get(\"profiles\", {})\n    var arr: Variant = cfg.get(key, [])\n    return arr if arr is Array else []\n`;\nconst GODOT_PREVIEW=`extends Control\n## Visualizador de modelo GLB embutido. Configure modelo e animacao no Inspector.\n@export_file(\"*.glb\") var modelo_glb: String = \"\"\n@export var nome_animacao: String = \"idle\"\nvar sub: SubViewport\nvar holder: Node3D\nvar camera: Camera3D\nvar inst: Node3D\nfunc _ready() -> void:\n    var container := SubViewportContainer.new()\n    container.stretch = true\n    container.set_anchors_and_offsets_preset(Control.PRESET_FULL_RECT)\n    add_child(container)\n    sub = SubViewport.new()\n    sub.size = Vector2i(600, 600)\n    sub.own_world_3d = true\n    sub.render_target_update_mode = SubViewport.UPDATE_ALWAYS\n    container.add_child(sub)\n    holder = Node3D.new()\n    sub.add_child(holder)\n    camera = Camera3D.new()\n    camera.current = true\n    camera.position = Vector3(0, 1.25, 4.5)\n    camera.look_at(Vector3(0, 1.0, 0), Vector3.UP)\n    holder.add_child(camera)\n    var light := DirectionalLight3D.new()\n    light.rotation_degrees = Vector3(-35, -30, 0)\n    holder.add_child(light)\n    var env := WorldEnvironment.new()\n    env.environment = Environment.new()\n    env.environment.background_mode = Environment.BG_COLOR\n    env.environment.background_color = Color(\"#152b3e\")\n    env.environment.ambient_light_source = Environment.AMBIENT_SOURCE_COLOR\n    holder.add_child(env)\n    if modelo_glb.is_empty() or not ResourceLoader.exists(modelo_glb):\n        push_warning(\"Escolha um GLB na propriedade modelo_glb.\")\n        return\n    var packed := load(modelo_glb) as PackedScene\n    if packed == null:\n        push_warning(\"O modelo nao foi importado como cena: \" + modelo_glb)\n        return\n    inst = packed.instantiate() as Node3D\n    if inst == null:\n        return\n    holder.add_child(inst)\n    var players := inst.find_children(\"*\", \"AnimationPlayer\", true, false)\n    for obj in players:\n        var p := obj as AnimationPlayer\n        if p.has_animation(nome_animacao):\n            p.play(nome_animacao)\n            return\n        for lib in p.get_animation_library_list():\n            var key: String = str(lib) + \"/\" + nome_animacao\n            if p.has_animation(key):\n                p.play(key)\n                return\n    push_warning(\"Nao achei a animacao solicitada: \" + nome_animacao)\n`;\nfunction toBytesData(uri){const b64=String(uri||'').split(',')[1];if(!b64)throw Error('Modelo sem dados');const bin=atob(b64),out=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)out[i]=bin.charCodeAt(i);return out}\n// Acrescenta configuracoes ao MESMO zip exportado pelas abas anteriores.\nconst priorZipPack=zipPack;\nzipPack=function(files){if(files.some(f=>f[0]==='dados/apoena_catalogo_itens.json')){const c=state33();files.push(['dados/apoena_animacoes_3d_v1.json',JSON.stringify({schema:'apoena.animations.v1',bindings:c.characterBindings,models:c.models.map(m=>({id:m.id,name:m.name,clips:m.clips,path:m.filePath,kind:m.kind}))},null,2)]);files.push(['dados/apoena_controles_v1.json',JSON.stringify({schema:'apoena.controls.v1',profiles:c.profiles},null,2)]);files.push(['dados/apoena_verificacao_controles_3d.json',JSON.stringify(controlReport(),null,2)]);files.push(['scripts/sistemas/apoena_animacoes_vinculos.gd',GODOT_ANIMATIONS]);files.push(['scripts/sistemas/apoena_controles_perfis.gd',GODOT_CONTROLS]);files.push(['scripts/ui/apoena_previa_animacao_3d.gd',GODOT_PREVIEW]);files.push(['cenas/apoena_previa_animacao_3d.tscn','[gd_scene load_steps=2 format=3]\\n\\n[ext_resource type=\"Script\" path=\"res://scripts/ui/apoena_previa_animacao_3d.gd\" id=\"1\"]\\n\\n[node name=\"ApoenaPreviaAnimacao3D\" type=\"Control\"]\\nlayout_mode = 3\\nanchors_preset = 15\\nanchor_right = 1.0\\nanchor_bottom = 1.0\\nscript = ExtResource(\"1\")\\n']);for(const m of c.models){if(m.data){const path='arte/game_creator_3d/'+m.id+'.'+m.kind;files.push([path,toBytesData(m.data)])}}files.push(['GUIA_ANIMACOES_E_CONTROLES.txt','APOENA GAME CREATOR v3.3\\n\\n1. Importe os arquivos para uma COPIA do projeto Godot 4.\\n2. Animações: dados/apoena_animacoes_3d_v1.json e scripts/sistemas/apoena_animacoes_vinculos.gd.\\n3. Controles: dados/apoena_controles_v1.json e scripts/sistemas/apoena_controles_perfis.gd.\\n4. Teste cena cenas/apoena_previa_animacao_3d.tscn (F6), configure modelo_glb e nome_animacao no Inspector.\\n5. FBXs individuais podem exigir rig compativel/retarget.\\n6. Este pacote exporta vinculos e recursos; NAO muda as cenas de combate existentes automaticamente.\\n7. Os perfis sao DADOS. Conecte os bindings aos InputMap e botoes das cenas oficiais.\\n']);}return priorZipPack(files)};\nfunction init(){state33();studioOptions();\n $s('studioCharacter').onchange=e=>{charId=e.target.value;renderStudio()};\n $s('studioModel').onchange=e=>{const bd=characterBinding(charId);const prev=bd.modelId,next=e.target.value;bd.modelId=next;if(prev&&prev!==next&&!bd.extraAssetIds.includes(prev))bd.extraAssetIds.push(prev);bd.extraAssetIds=bd.extraAssetIds.filter(id=>id!==next);refreshBindings();renderStudio()};\n $s('studioImportModel').onchange=async e=>{await importModels(e.target.files);e.target.value=''};\n $s('studioAutoMap').onclick=suggestBindings;\n $s('studioPreviewAction').innerHTML=studioDefs.map(x=>`<option value=\"${x[0]}\">${safe(x[1])}</option>`).join('');\n $s('studioPreviewAction').onchange=updateStudioPreview;\n $s('studioPlay').onclick=studioPlay;\n $s('studioDownloadBindings').onclick=()=>jsonDownload({schema:'apoena.animations.v1',models:state33().models.map(({data,...rest})=>rest),bindings:state33().characterBindings},'APOENA_ANIMACOES_3D.json');\n $s('studioValidate').onclick=()=>{let e=controlReport();$s('studioMsg').textContent=e.length?e.join(' • '):'Nenhuma referência quebrada encontrada nesta verificação.'};\n $s('studioHelp').onclick=()=>alert('GLB: o programa lê os clipes do arquivo e associa a ações.\\nFBX: cada arquivo aparece como clipe pelo nome; pode precisar de compatibilidade de rig.\\nA prévia 3D real abre no Godot, não dentro do HTML offline.\\nOs dados são exportados, mas não alteram o jogo automaticamente.');\n $s('controlProfile').onchange=e=>{controlProfile=e.target.value;focusControl='';renderProfiles()};\n $s('controlBindKey').onchange=e=>changeControl('input',e.target.value.trim().slice(0,60));\n $s('controlCapture').onclick=()=>{const b=$s('controlCapture');b.textContent='Pressione tecla ou mouse...';const f=e=>{e.preventDefault();e.stopPropagation();const txt=e.type==='mousedown'?'MOUSE_'+(e.button===0?'LEFT':e.button===2?'RIGHT':e.button):e.code;changeControl('input',txt);document.removeEventListener('keydown',f,true);document.removeEventListener('mousedown',f,true);b.textContent='Capturar tecla/clique'};document.addEventListener('keydown',f,true);document.addEventListener('mousedown',f,true)};\n $s('controlSize').oninput=e=>changeControl('size',Number(e.target.value));\n $s('controlOpacity').oninput=e=>changeControl('opacity',Number(e.target.value));\n $s('controlEnabled').onchange=e=>changeControl('enabled',e.target.checked);\n $s('controlReset').onclick=()=>{if(!confirm('Restaurar o perfil atual? Os outros perfis permanecem como estão.'))return;delete state33().profiles[controlProfile];state33();focusControl='';renderProfiles()};\n $s('controlDownload').onclick=()=>jsonDownload({schema:'apoena.controls.v1',profiles:state33().profiles},'APOENA_CONTROLES_JOGADOR.json');\n $s('controlCheck').onclick=()=>{const x=controlReport();$s('controlStatus').textContent=x.length?x.join(' • '):'Perfis sem teclas duplicadas ou referências ausentes.'};\n // As outras extensoes substituem .onclick. Listener nao afeta comportamento antigo.\n document.querySelectorAll('.tab[data-page=\"animacoes\"],.tab[data-page=\"controles\"]').forEach(b=>b.onclick=()=>{switchPage(b.dataset.page);location.hash=b.dataset.page;if(b.dataset.page==='animacoes')renderStudio();else renderProfiles()});\n document.querySelector('#projectFile').addEventListener('change',()=>setTimeout(()=>{state33();renderStudio();renderProfiles()},450));\n if(location.hash==='#animacoes')switchPage('animacoes');if(location.hash==='#controles')switchPage('controles');\n renderStudio();renderProfiles();\n window.ApoenaCreator33={getData:state33,parseGLB,makeClips,controlReport,renderStudio,renderProfiles,studioDefs};\n}\ninit();\n})();\n\n</script>\n<script>\n'use strict';\n/* APOENA GAME CREATOR 3.4 — recursos locais e componentes de interface.\n * O browser somente acessa pastas autorizadas pelo usuario. Nenhum modelo 3D\n * e salvo no JSON editavel; o exportador inclui apenas modelos utilizados.\n */\n(() => {\n const el=id=>document.getElementById(id);\n const html=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\n const allow=new Set(['glb','gltf','fbx']);\n const folderFiles=new Map(); // relPath => File ou FileSystemFileHandle (SOMENTE memoria)\n let folderHandle=null, filtered=[], selectedPath='', lastExportBytes=[];\n function lib(){\n   if(!state.creatorLibrary||typeof state.creatorLibrary!=='object')state.creatorLibrary={schema:'apoena.local_library.v1',rootName:'',entries:[],updatedAt:''};\n   if(!Array.isArray(state.creatorLibrary.entries))state.creatorLibrary.entries=[];\n   return state.creatorLibrary;\n }\n function ext(s){return String(s).split('.').pop().toLowerCase()}\n function hash(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return (h>>>0).toString(16)}\n function modelId(path){return 'local_'+hash(path)}\n function correspondingModel(path){return window.ApoenaCreator33?.getData().models.find(m=>m.id===modelId(path))}\n function entry(path){return lib().entries.find(e=>e.path===path)}\n function sizeLabel(n){return n>1048576?(n/1048576).toFixed(1)+' MB':Math.round(n/1024)+' KB'}\n function available(path){return folderFiles.has(path)}\n function status34(msg){el('localStatus').textContent=msg;typeof status==='function'&&status(msg)}\n async function idb(action,val){\n   return new Promise((resolve,reject)=>{\n    if(!window.indexedDB){resolve(null);return}\n    const req=indexedDB.open('apoena_creator_local_folder_v34',1);\n    req.onupgradeneeded=()=>req.result.createObjectStore('folders');\n    req.onerror=()=>reject(req.error);\n    req.onsuccess=()=>{const db=req.result,tx=db.transaction('folders',action==='load'?'readonly':'readwrite'),st=tx.objectStore('folders');const cmd=action==='load'?st.get('chosen'):st.put(val,'chosen');cmd.onsuccess=()=>resolve(cmd.result);cmd.onerror=()=>reject(cmd.error);tx.oncomplete=()=>db.close()};\n   });\n }\n async function initFolder(){try{folderHandle=await idb('load')}catch{};if(folderHandle){el('localStatus').textContent='Pasta anterior encontrada. Clique em Reconectar para autorizar seu acesso.'}}\n async function readFile(path){const ref=folderFiles.get(path);if(!ref)throw Error('Arquivo fora da pasta conectada: '+path);return ref instanceof File?ref:await ref.getFile()}\n async function collectDirectory(dir,base='',depth=0,paths=[],max=4000){\n   if(depth>7||paths.length>=max)return paths;\n   for await(const [name,handle] of dir.entries()){\n     if(paths.length>=max)break;\n     if(handle.kind==='directory')await collectDirectory(handle,base+name+'/',depth+1,paths,max);\n     else if(allow.has(ext(name))){const path=base+name;paths.push({path,ref:handle})}\n   }\n   return paths;\n }\n async function connectFolder(reuse=false){\n   try{\n    if(!reuse){if(!window.showDirectoryPicker){el('localFallback').click();return}folderHandle=await window.showDirectoryPicker({mode:'read'});try{await idb('save',folderHandle)}catch{}}\n    if(!folderHandle)throw Error('Escolha uma pasta primeiro.');\n    if(reuse){let p=await folderHandle.queryPermission({mode:'read'});if(p!=='granted')p=await folderHandle.requestPermission({mode:'read'});if(p!=='granted')throw Error('O acesso à pasta não foi autorizado.')}\n    status34('Procurando modelos e animações dentro da pasta…');\n    let paths=await collectDirectory(folderHandle);folderFiles.clear();const keep=[];\n    for(const x of paths){const f=await x.ref.getFile();keep.push({path:x.path,size:f.size,modified:f.lastModified});folderFiles.set(x.path,x.ref)}\n    mergeEntries(keep,folderHandle.name);status34(`Biblioteca conectada: ${keep.length} arquivos 3D indexados. Os arquivos continuam no seu disco.`);\n   }catch(e){if(e.name!=='AbortError')status34('Não foi possível abrir a pasta: '+e.message)}\n }\n function mergeEntries(found,root){const old=new Map(lib().entries.map(x=>[x.path,x]));lib().entries=found.map(x=>({...old.get(x.path),...x,kind:ext(x.path),clips:old.get(x.path)?.clips||[],analyzed:old.get(x.path)?.analyzed||false}));lib().rootName=root;lib().updatedAt=new Date().toISOString();selectedPath=lib().entries.some(x=>x.path===selectedPath)?selectedPath:'';renderLocal()}\n async function inputFolder(files){const chosen=[...files].filter(f=>allow.has(ext(f.name)));folderFiles.clear();folderHandle=null;const entries=chosen.map(f=>{const full=f.webkitRelativePath||f.name;const path=full.includes('/')?full.slice(full.indexOf('/')+1):full;folderFiles.set(path,f);return{path,size:f.size,modified:f.lastModified}});mergeEntries(entries,chosen[0]?.webkitRelativePath.split('/')[0]||'Pasta selecionada');status34(`${chosen.length} arquivos ligados para esta sessão. Para reconectar no futuro, selecione a pasta novamente.`)}\n // GLB: le apenas o bloco JSON, SEM ler a malha/texturas pesadas.\n async function clipsFromFile(file){\n   const kind=ext(file.name);\n   if(kind==='fbx')return [{name:file.name.replace(/\\.fbx$/i,''),origin:'FBX: nome presumido; verifique rig no Godot'}];\n   let data;\n   if(kind==='glb'){\n    if(file.size<20)throw Error('GLB pequeno demais');\n    const header=new DataView(await file.slice(0,20).arrayBuffer());\n    if(header.getUint32(0,true)!==0x46546c67||header.getUint32(4,true)!==2||header.getUint32(16,true)!==0x4e4f534a)throw Error('Cabeçalho GLB 2.0 inválido');\n    const len=header.getUint32(12,true);if(len>20_000_000||len+20>file.size)throw Error('JSON de GLB muito grande ou inválido');\n    data=JSON.parse(new TextDecoder().decode(await file.slice(20,20+len).arrayBuffer()).replace(/\\0+$/,''));\n   }else{\n    if(file.size>20_000_000)throw Error('GLTF JSON grande demais');\n    data=JSON.parse(await file.text());\n   }\n   if(!Array.isArray(data.nodes))throw Error('Não há estrutura glTF válida');\n   return (data.animations||[]).map((a,i)=>({name:String(a.name||'Animacao_'+(i+1)).slice(0,100),origin:kind.toUpperCase()}));\n }\n async function analyze(path){const e=entry(path);if(!e)return;try{const f=await readFile(path);e.clips=await clipsFromFile(f);e.analyzed=true;e.error='';const m=correspondingModel(path);if(m){m.clips=e.clips;m.bytes=e.size}status34(`Analisado: ${path} — ${e.clips.length} animações reconhecidas.`)}catch(ex){e.error=ex.message;status34('Falha na análise: '+ex.message)};renderLocal();window.ApoenaCreator33?.renderStudio()}\n function refreshChars(){const x=el('localCharacter'),old=x.value;x.innerHTML=(state.characters||[]).map(c=>`<option value=\"${html(c.id)}\">${html(c.name)}</option>`).join('')||'<option value=\"\">Cadastre um personagem na aba Personagens</option>';if([...x.options].some(o=>o.value===old))x.value=old}\n async function bindToCharacter(){const e=entry(selectedPath),char=el('localCharacter').value;if(!e||!char){status34('Selecione um arquivo e um personagem.');return}if(!available(e.path)){status34('Reconecte a pasta para analisar esse arquivo.');return}\n   if(!e.analyzed)await analyze(e.path);\n   const data=window.ApoenaCreator33.getData(),id=modelId(e.path),kind=ext(e.path);let m=data.models.find(x=>x.id===id);\n   if(!m){m={id,name:e.path.split('/').at(-1),kind,clips:e.clips||[],filePath:`res://arte/game_creator_3d/${id}.${kind}`,localPath:e.path,bytes:e.size};data.models.push(m)}else{Object.assign(m,{clips:e.clips||[],localPath:e.path,bytes:e.size});delete m.data}\n   const bd=data.characterBindings[char] ||= {modelId:'',extraAssetIds:[],mappings:{}};bd.extraAssetIds||=[];\n   if(!bd.modelId||kind==='glb'&&(data.models.find(x=>x.id===bd.modelId)?.kind!=='glb')){if(bd.modelId&&bd.modelId!==id&&!bd.extraAssetIds.includes(bd.modelId))bd.extraAssetIds.push(bd.modelId);bd.modelId=id;bd.extraAssetIds=bd.extraAssetIds.filter(x=>x!==id)}else if(bd.modelId!==id&&!bd.extraAssetIds.includes(id))bd.extraAssetIds.push(id);\n   el('studioCharacter').value=char;el('studioCharacter').dispatchEvent(new Event('change',{bubbles:true}));window.ApoenaCreator33.renderStudio();status34(`${m.name} vinculado a ${char}. Agora use a aba Animações 3D para escolher as ações.`);renderLocal();\n }\n function renderLocal(){refreshChars();const q=el('localSearch').value.toLowerCase().trim(),kind=el('localType').value;filtered=lib().entries.filter(e=>e.path.toLowerCase().includes(q)&&(!kind||e.kind===kind));el('localCount').textContent=`${filtered.length} / ${lib().entries.length} arquivos • ${lib().rootName||'nenhuma pasta'}`;\n  el('localItems').innerHTML=filtered.slice(0,180).map(x=>`<button class=\"v34-file ${selectedPath===x.path?'on':''}\" data-p=\"${html(x.path)}\"><span>▣ ${html(x.path)}</span><small>${html(x.kind.toUpperCase())} · ${sizeLabel(x.size)} · ${x.analyzed?x.clips.length+' clipes': 'não analisado'} ${available(x.path)?'● conectado':'○ offline'}</small></button>`).join('')||'<p class=\"hint\">Nenhum arquivo indexado. Escolha uma pasta para começar.</p>';\n  if(filtered.length>180)el('localCount').textContent+=' · listando primeiros 180';\n  el('localItems').querySelectorAll('[data-p]').forEach(b=>b.onclick=()=>{selectedPath=b.dataset.p;renderLocal()});\n  let x=entry(selectedPath);el('localDetail').innerHTML=x?`<b>${html(x.path)}</b><p class=\"hint\">${sizeLabel(x.size)} • Modificado: ${new Date(x.modified).toLocaleString('pt-BR')}</p><p class=\"hint\">${available(x.path)?'Arquivo acessível':'Arquivo não conectado; reconecte a pasta.'}</p><p>${x.clips.map(c=>`<span class=\"v34-clip\">▶ ${html(c.name)}</span>`).join(' ')||'<span class=\"hint\">Clique em Analisar para identificar clipes disponíveis.</span>'}</p>${x.error?`<p class=\"warning\">${html(x.error)}</p>`:''}`:'Escolha um arquivo na lista para analisar ou vincular.';\n  el('localAnalyze').disabled=!x||!available(selectedPath);el('localBind').disabled=!x||!available(selectedPath)\n }\n async function makeExportFiles(){lastExportBytes=[];const data=window.ApoenaCreator33.getData();const used=new Set();for(const v of Object.values(data.characterBindings)){if(v.modelId)used.add(v.modelId);for(const id of v.extraAssetIds||[])used.add(id)}\n  let sum=0;for(const id of used){const model=data.models.find(x=>x.id===id);if(!model?.localPath)continue;\n    if(!available(model.localPath))throw Error(`Modelo usado não encontrado na pasta: ${model.localPath}. Reconecte sua biblioteca.`);\n    if(model.kind==='gltf')throw Error(`O arquivo GLTF ${model.name} pode depender de texturas/binários externos. Converta-o para GLB antes de exportar.`);\n    const f=await readFile(model.localPath);if(f.size>90_000_000)throw Error('Arquivo individual maior que 90 MB: '+f.name);\n    sum+=f.size;if(sum>180_000_000)throw Error('Recursos 3D selecionados passam de 180 MB. Reduza os modelos usados.');\n    lastExportBytes.push([`arte/game_creator_3d/${id}.${model.kind}`,new Uint8Array(await f.arrayBuffer())]);\n  }\n }\n function validateRefs(){const models=window.ApoenaCreator33.getData().models,used=new Set();for(const c of Object.values(window.ApoenaCreator33.getData().characterBindings)){if(c.modelId)used.add(c.modelId);for(const id of c.extraAssetIds||[])used.add(id)}\n  return [...used].map(id=>models.find(m=>m.id===id)).filter(Boolean).filter(m=>m.localPath&&!available(m.localPath)).map(m=>m.name+' • pasta desconectada')}\n // Exportador v3.3 inclui vínculos; complementa o pacote com arquivos do disco local.\n const oldZipPack=zipPack;\n zipPack=function(files){if(files.some(x=>x[0]==='dados/apoena_catalogo_itens.json')){\n   files.push(['dados/apoena_biblioteca_local_v1.json',JSON.stringify({schema:'apoena.library.v1',rootName:lib().rootName,entries:lib().entries.map(({path,kind,size,clips})=>({path,kind,size,clips}))},null,2)]);\n   files.push(...lastExportBytes);\n   files.push(['dados/apoena_componentes_v34.json',JSON.stringify({schema:'apoena.components.v1',screens:Object.fromEntries(Object.entries(state.screens).map(([k,v])=>[k,v.elements.filter(e=>e.component_type||e.owner_window||e.preview3d).map(e=>({id:e.id,type:e.type,component_type:e.component_type||'',owner_window:e.owner_window||'',source_scope:e.source_scope||'',preview3d:!!e.preview3d,action:e.action||'',action_icon_path:e.action_icon_path||'',window_id:e.window_id||''}))]))},null,2)]);\n   files.push(['scripts/ui/apoena_acoes_janelas_v34.gd',`extends RefCounted\\n## Helpers de janela local - o jogo conecta a acao_solicitada do leitor.\\nstatic func fechar_janela_local(origem: Node, window_id: String) -> bool:\\n    if origem == null or window_id.is_empty():\\n        return false\\n    var no: Node = origem\\n    while no != null:\\n        if str(no.get_meta(\"apoena_window_id\", \"\")) == window_id:\\n            if no is CanvasItem:\\n                (no as CanvasItem).hide()\\n                return true\\n            return false\\n        no = no.get_parent()\\n    return false\\n`]);\n   files.push(['INSTRUCOES_V34_BIBLIOTECA_LOCAL.txt',`GAME CREATOR 3.4 — BIBLIOTECA LOCAL\\n\\nO JSON editavel contem somente referencias e metadados de arquivos 3D locais.\\nOs GLB/FBX usados em personagens vinculados foram adicionados ao pacote ao exportar.\\nGLTF externo precisa ser convertido a GLB antes da exportacao.\\nFBX com rig incompatível continua exigindo retarget.\\nA biblioteca local nunca apaga ou modifica originais do PC.\\n\\nComponentes: veja layouts/*.json e dados/apoena_componentes_v34.json.\\nA acao fechar_janela_local e um ID de evento: para funcionar na cena real, conecte o signal do leitor ao helper scripts/ui/apoena_acoes_janelas_v34.gd.\\nOs quadros de itens e o preview 3D sao componentes configurados, NAO inventarios runtime conectados automaticamente.\\nPerfis de controles continuam dados ate integracao das cenas reais.\\n`]);\n  }\n  return oldZipPack(files)\n };\n const exp=el('exportGodot'),oldExport=exp.onclick;\n exp.onclick=async function(ev){try{exp.disabled=true;el('localExportReport').textContent='Preparando somente os modelos 3D usados…';await makeExportFiles();el('localExportReport').textContent=`Pacote pronto: ${lastExportBytes.length} arquivo(s) 3D local(is) usado(s).`;await oldExport.call(exp,ev)}catch(e){el('localExportReport').textContent='Exportação cancelada: '+e.message;alert('Antes de exportar: '+e.message)}finally{exp.disabled=false;lastExportBytes=[]}};\n // Propriedades de botoes e janelas: todo elemento continua movivel pelo editor existente.\n const origInspector=renderInspector;\n renderInspector=function(){origInspector();let chosen=typeof element==='function'?element():null;\n  if(!chosen)return;let box=el('inspector');if(el('v34ExtraProps'))return;\n  const extra=document.createElement('div');extra.id='v34ExtraProps';extra.innerHTML=`<div class=\"v34-separator\"><h3>⚙ Componente inteligente 3.4</h3>\n  <label>ID da janela proprietária</label><input id=\"v34Window\" placeholder=\"ex.: janela_inventario\" value=\"${html(chosen.owner_window||chosen.window_id||'')}\">\n  ${chosen.type==='button'?`<label>Ação predefinida</label><select id=\"v34Action\"><option value=\"\">— Escolher —</option><option value=\"fechar_janela_local\">Fechar somente esta janela</option><option value=\"abrir_inventario\">Abrir inventário</option><option value=\"abrir_loja_moba\">Abrir loja da partida</option><option value=\"abrir_laboratorio\">Abrir laboratório</option><option value=\"equipar_item\">Equipar item</option><option value=\"usar_item\">Usar item</option></select><label>Ícone do botão (opcional)</label><select id=\"v34Icon\"><option value=\"\">— Sem imagem —</option>${state.assets.map(a=>`<option value=\"${html(a.id)}\">${html(a.name)}</option>`).join('')}</select>`:''}\n  ${chosen.component_type==='item_grid'?`<label>Fonte dos itens</label><select id=\"v34Scope\"><option value=\"permanente\">Inventário permanente</option><option value=\"partida_moba\">Inventário temporário da partida</option></select>`:''}\n  ${chosen.preview3d?`<label>Personagem (ID)</label><input id=\"v34PreviewChar\" value=\"${html(chosen.preview_character||'')}\"><label>Animação inicial</label><select id=\"v34PreviewAction\"><option>idle</option><option>walk</option><option>run</option><option>basic_attack</option><option>skill_q</option><option>skill_w</option><option>skill_e</option><option>skill_r</option><option>skill_f</option></select>`:''}\n  <p class=\"hint\">Esses campos são exportados no layout. A execução real depende do leitor de componentes do jogo.</p></div>`;box.append(extra);\n  el('v34Window').onchange=e=>{chosen.owner_window=e.target.value;chosen.window_id=chosen.window_id||e.target.value};\n  if(el('v34Action')){el('v34Action').value=chosen.action||'';el('v34Action').onchange=e=>{chosen.action=e.target.value;renderStage()}}\n  if(el('v34Icon')){el('v34Icon').value=chosen.action_icon_asset||'';el('v34Icon').onchange=e=>{chosen.action_icon_asset=e.target.value;renderStage()}}\n  if(el('v34Scope')){el('v34Scope').value=chosen.source_scope||'permanente';el('v34Scope').onchange=e=>{chosen.source_scope=e.target.value}}\n  if(el('v34PreviewChar'))el('v34PreviewChar').onchange=e=>{chosen.preview_character=e.target.value};\n  if(el('v34PreviewAction')){el('v34PreviewAction').value=chosen.preview_action||'idle';el('v34PreviewAction').onchange=e=>{chosen.preview_action=e.target.value}}\n };\n const origStage=renderStage;\n renderStage=function(){origStage();for(const n of document.querySelectorAll('#stage .art')){const e=screen().elements.find(x=>x.id===n.dataset.id);if(!e)continue;\n   if(e.type==='button'&&e.action_icon_asset){const a=state.assets.find(x=>x.id===e.action_icon_asset);if(a){const icon=document.createElement('img');icon.src=a.data;icon.className='v34-button-icon';n.prepend(icon)}}\n   if(e.preview3d){n.classList.add('v34-viewport');const mark=document.createElement('small');mark.textContent='▣ 3D • '+(e.preview_action||'idle');mark.className='v34-viewport-label';n.append(mark)}\n   if(e.component_type==='item_grid'){n.classList.add('v34-itemgrid');n.title='Caixa de itens: '+(e.source_scope||'permanente');}\n  }};\n const origNorm=normScreenForGodot;\n normScreenForGodot=function(s){const c=origNorm(s);for(const e of c.elements){if(e.action_icon_asset){const a=state.assets.find(x=>x.id===e.action_icon_asset);e.action_icon_path=a?assetPath(a):'';delete e.action_icon_asset}}return c};\n function addPreset(template){history();const id='janela_'+Math.random().toString(36).slice(2,9),base=screen().elements.length;\n  function add(type,name,x,y,w,h,text,extra={}){const e=newElement(type,name);Object.assign(e,{x,y,w,h,text,z_index:screen().elements.length,owner_window:id,...extra});screen().elements.push(e);return e}\n  if(template==='janela'){add('panel','Janela independente',390,120,520,430,'',{window_id:id,background:'#142e40'});add('label','Título da janela',420,135,310,55,'MINHA JANELA',{font_size:22});add('button','Fechar janela local',804,135,78,61,'✕',{action:'fechar_janela_local',font_size:30})}\n  if(template==='mochila'||template==='moba'){\n    const moba=template==='moba',x=200,y=96;add('panel','Janela '+(moba?'loja MOBA':'mochila'),x,y,790,520,'',{window_id:id,background:'#152c3b'});\n    add('label','Título da janela',x+25,y+15,555,50,moba?'LOJA • PARTIDA':'MOCHILA • INVENTÁRIO',{font_size:24});\n    add('button','Fechar local',x+650,y+12,110,62,'✕',{action:'fechar_janela_local',font_size:24});\n    const slotW=93,slotH=89;for(let k=0;k<20;k++)add('panel','Slot '+(k+1),x+38+(k%5)*138,y+118+Math.floor(k/5)*93,slotW,slotH,'',{component_type:'item_grid',source_scope:moba?'partida_moba':'permanente',slot_index:k,background:'#203d4d'});\n    if(moba)add('button','Comprar selecionado',x+480,y+75,175,41,'COMPRAR',{action:'comprar_item_partida',font_size:15});\n  }\n  if(template==='preview'){add('character_preview','Prévia 3D 1:1',465,170,330,330,'PRÉVIA 3D',{component_type:'viewport_3d',preview3d:true,preview_character:'',preview_action:'idle',background:'#102c3d'});}\n  selected=screen().elements.at(-1)?.id;multiSelected.clear();if(selected)multiSelected.add(selected);renderLayout();status('Componente adicionado. Selecione para configurar e arraste para posicionar.');\n }\n function init(){\n  let nav=document.querySelector('nav.tabs');let button=document.createElement('button');button.className='tab';button.dataset.page='biblioteca-local';button.textContent='📁 Biblioteca 3D local';nav.append(button);button.addEventListener('click',()=>{switchPage('biblioteca-local');location.hash='biblioteca-local';renderLocal()});\n  el('localChoose').onclick=()=>connectFolder(false);el('localReconnect').onclick=async()=>{if(folderHandle)await connectFolder(true);else await connectFolder(false)};\n  el('localFallback').onchange=e=>{inputFolder(e.target.files);e.target.value=''};\n  el('localSearch').oninput=renderLocal;el('localType').onchange=renderLocal;\n  el('localAnalyze').onclick=()=>analyze(selectedPath);el('localBind').onclick=bindToCharacter;\n  el('localValidate').onclick=()=>{const issues=validateRefs();status34(issues.length?'Pendências: '+issues.join(' • '):'Nenhuma referência LOCAL quebrada entre os personagens vinculados.')};\n  el('localClear').onclick=()=>{if(!confirm('Desconectar a pasta nesta sessão? O catálogo e os vínculos serão preservados.'))return;folderFiles.clear();folderHandle=null;renderLocal();status34('Pasta desconectada. A lista e os vínculos continuam salvos no projeto.')};\n  const bar=document.querySelector('.creator-v31-components');if(bar){const section=document.createElement('div');section.className='v34-templates';section.innerHTML=`<h3>Componentes inteligentes • 3.4</h3><p class=\"hint\">Todos arrastáveis. Regras exportadas por ID; conexão ao inventário real no Godot é uma etapa separada.</p><button id=\"v34Mochila\" class=\"full\">＋ Caixa de inventário geral</button><button id=\"v34Moba\" class=\"full\">＋ Loja temporária MOBA</button><button id=\"v34Janela\" class=\"full\">＋ Janela com fechar local</button><button id=\"v34Preview\" class=\"full\">＋ Prévia 3D quadrada</button>`;bar.append(section);\n   for(const [id,tpl]of [['v34Mochila','mochila'],['v34Moba','moba'],['v34Janela','janela'],['v34Preview','preview']])el(id).onclick=()=>addPreset(tpl)}\n  // Atualiza lista depois de restaurar um JSON editavel.\n  el('projectFile').addEventListener('change',()=>setTimeout(()=>{selectedPath='';renderLocal()},600));\n  initFolder();renderLocal();if(location.hash==='#biblioteca-local')switchPage('biblioteca-local');\n  window.ApoenaCreator34={readFile,clipsFromFile,mergeEntries,analyze,bindToCharacter,makeExportFiles,validateRefs,renderLocal,addPreset,getLibrary:lib,getLoadedFiles:()=>folderFiles.size};\n }\n init();\n})();\n\n</script>\n<script>\n'use strict';\n/* Apoena Game Creator 3.5: áreas clicáveis sobre arte, janela proprietária,\n   diagnóstico preventivo. Sem executar lógica do jogo no HTML. */\n(() => {\n const H=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\n const KEY='APOENA_V35';\n const $id=id=>document.getElementById(id);\n let placing=false, drafting=null, checkTimer=0;\n const stage=$id('stage'), layout=$id('page-layouts');\n if(!stage||!layout)return;\n const actionDefs=[\n ['','Escolher ação (ainda sem função)'],\n ['fechar_janela_local','Fechar esta janela'],['abrir_inventario','Abrir inventário'],\n ['abrir_loja','Abrir loja'],['abrir_laboratorio','Abrir laboratório'],\n ['abrir_configuracoes','Abrir configurações'],['abrir_herois','Abrir heróis'],\n ['abrir_poderes','Abrir poderes'],['abrir_missoes','Abrir missões'],\n ['abrir_forja','Abrir forja'],['abrir_menu','Abrir menu'],\n ['voltar','Voltar'],['jogar','Jogar'],['comprar_item_partida','Comprar item de partida'],\n ['comprar_item','Comprar item'],['vender_item','Vender item'],\n ['usar_item','Usar item'],['equipar_item','Equipar item'],\n ['desequipar_item','Desequipar item'],['confirmar','Confirmar'],['cancelar','Cancelar']\n ];\n const workspace=document.createElement('section');workspace.id='v35Panel';workspace.className='panel v35-panel';\n workspace.innerHTML=`<div class=\"v35-heading\"><strong>Ferramentas de edição 3.5</strong><span>Menus com imagem • Segurança do projeto</span></div>\n <div class=\"v35-actions\"><button id=\"v35Hotspot\" class=\"primary\" type=\"button\">▣ Criar área clicável</button>\n <button id=\"v35Select\" type=\"button\">↖ Selecionar / mover</button>\n <button id=\"v35Audit\" type=\"button\">✓ Verificar projeto</button>\n <button id=\"v35ExportAudit\" type=\"button\">↓ Relatório JSON</button>\n <button id=\"v35Save\" type=\"button\">↓ Salvar projeto</button></div>\n <p class=\"v35-help\" id=\"v35Help\">Se os botões estiverem desenhados na imagem do menu, clique em “Criar área clicável” e desenhe um retângulo sobre cada botão. Cada área será um botão independente, transparente no jogo e editável por arraste.</p>\n <div id=\"v35Results\" class=\"v35-results\" hidden aria-live=\"polite\"></div>`;\n const editor=layout.querySelector('.layout-area');\n if(editor)editor.parentNode.insertBefore(workspace,editor);\n else layout.prepend(workspace);\n const modeButton=$id('v35Hotspot');\n const setMode=(on)=>{\n  placing=on;modeButton.classList.toggle('v35-active',placing);\n  stage.classList.toggle('v35-drawing',placing);\n  $id('v35Help').textContent=placing?\n   'Clique e arraste um retângulo na imagem para criar o botão. Esc cancela. Para mover novamente os objetos, clique em “Selecionar / mover”.':\n   'Se a imagem do menu já tem botões desenhados, crie áreas clicáveis por cima. Elas ficam transparentes no jogo, mas visíveis e selecionáveis neste editor.';\n };\n modeButton.addEventListener('click',()=>setMode(!placing));\n $id('v35Select').onclick=()=>setMode(false);\n function pt(ev){const r=stage.getBoundingClientRect(),f=stageScale||1;return {x:Math.min(screen().resolution.width,Math.max(0,(ev.clientX-r.left)/f)),y:Math.min(screen().resolution.height,Math.max(0,(ev.clientY-r.top)/f))}}\n function findOwner(e){\n  const parts=screen().elements.filter(x=>x!==e&&(x.window_id||x.component_type==='window')&&x.x<=e.x+e.w/2&&x.y<=e.y+e.h/2&&x.x+x.w>=e.x+e.w/2&&x.y+x.h>=e.y+e.h/2);\n  parts.sort((a,b)=>a.w*a.h-b.w*b.h);return parts[0]?.window_id||parts[0]?.owner_window||'';\n }\n function finishDraft(ev,cancel=false){if(!drafting)return;const d=drafting;drafting=null;\n  document.removeEventListener('pointermove',moveDraft,true);document.removeEventListener('pointerup',upDraft,true);document.removeEventListener('pointercancel',cancelDraft,true);\n  d.rect.remove();if(cancel)return;\n  const end=pt(ev),x=Math.round(Math.min(d.point.x,end.x)),y=Math.round(Math.min(d.point.y,end.y)),w=Math.round(Math.abs(end.x-d.point.x)),h=Math.round(Math.abs(end.y-d.point.y));\n  if(w<12||h<12){status('Desenhe uma área maior (mínimo 12 × 12 px).');return}\n  history();multiSelected.clear();const e=newElement('button','Área clicável '+(screen().elements.filter(e=>e.hotspot).length+1));\n  Object.assign(e,{x,y,w,h,text:'',background:'#00000000',border_color:'#00000000',color:'#ffffff00',font_size:14,action:'',hotspot:true,visible:true,z_index:Math.max(-1,...screen().elements.map(a=>Number(a.z_index)||0))+1});\n  const owner=findOwner(e);if(owner)e.owner_window=owner;\n  screen().elements.push(e);selected=e.id;multiSelected.add(e.id);renderLayout();setMode(false);\n  status('Área clicável criada. Escolha a ação no inspetor; o desenho original da imagem permanece intacto.');\n }\n function moveDraft(ev){if(!drafting)return;ev.preventDefault();const p=pt(ev),x=Math.min(drafting.point.x,p.x),y=Math.min(drafting.point.y,p.y);Object.assign(drafting.rect.style,{left:x+'px',top:y+'px',width:Math.abs(p.x-drafting.point.x)+'px',height:Math.abs(p.y-drafting.point.y)+'px'});}\n function upDraft(ev){finishDraft(ev)}function cancelDraft(ev){finishDraft(ev,true)}\n stage.addEventListener('pointerdown',ev=>{\n  if(!placing||drafting||ev.button!==0)return;\n  ev.preventDefault();ev.stopImmediatePropagation();\n  const point=pt(ev),rect=document.createElement('div');rect.className='v35-draft';Object.assign(rect.style,{left:point.x+'px',top:point.y+'px',width:'0',height:'0'});stage.append(rect);\n  drafting={point,rect};document.addEventListener('pointermove',moveDraft,true);document.addEventListener('pointerup',upDraft,true);document.addEventListener('pointercancel',cancelDraft,true);\n },true);\n document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&placing){if(drafting)finishDraft(ev,true);setMode(false);ev.stopPropagation()}},true);\n // Inspeção aprimorada: a janela do botão é identificada pelo painel proprietário,\n // mas continua editável sem forçar uma associação errada.\n const originalInspector=renderInspector;\n renderInspector=function(){originalInspector();const e=typeof element==='function'?element():null;\n  if(!e||multiSelected.size>1)return;\n  const box=$id('inspector');if(!box||box.querySelector('#v35Inspector'))return;\n  const extra=document.createElement('section');extra.id='v35Inspector';extra.className='v35-inspector';\n  const windows=screen().elements.filter(x=>x.window_id).map(x=>({id:x.window_id,name:x.name}));\n  const options='<option value=\"\">— Sem janela vinculada —</option>'+[...new Map(windows.map(x=>[x.id,x])).values()].map(x=>`<option value=\"${H(x.id)}\">${H(x.name)} (${H(x.id)})</option>`).join('');\n  extra.innerHTML=`<h3>Ferramentas avançadas 3.5</h3>\n  <label class=\"flag\"><input type=\"checkbox\" id=\"v35Lock\" ${e.locked?'checked':''}> Bloquear movimento acidental</label>\n  ${e.type==='button'?`<label class=\"flag\"><input type=\"checkbox\" id=\"v35IsHotspot\" ${e.hotspot?'checked':''}> Botão invisível sobre imagem</label>\n   <label>Biblioteca de ações</label><select id=\"v35Action\">${actionDefs.map(([v,t])=>`<option value=\"${H(v)}\">${H(t)}</option>`).join('')}</select>\n   <label>Janela que este botão controla</label><select id=\"v35Owner\">${options}</select>\n   <button type=\"button\" id=\"v35GuessOwner\">Identificar janela pela posição</button>\n   <p class=\"hint\">A ação FECHAR age somente na janela vinculada. Se não houver uma janela, o verificador mostrará um aviso. O desenho do botão na imagem não se torna editável; a área clicável por cima é editável.</p>`:''}\n   <p class=\"hint\">Mudanças de configuração podem ser desfeitas com Ctrl+Z. Os dados são exportados, mas as ações exigem seu executor no Godot.</p>`;\n  box.appendChild(extra);\n  // Remove o seletor redundante da versão anterior para não gerar ações conflitantes.\n  const antigo=$id('v34Action');if(antigo){antigo.previousElementSibling?.remove();antigo.remove()}\n  $id('v35Lock').onchange=ev=>{history();e.locked=ev.target.checked;renderLayout()};\n  if(e.type==='button'){\n   $id('v35IsHotspot').onchange=ev=>{history();e.hotspot=ev.target.checked;if(e.hotspot){e.background='#00000000';e.border_color='#00000000';e.text=''}renderLayout()};\n   $id('v35Action').value=e.action||'';\n   $id('v35Action').onchange=ev=>{history();e.action=ev.target.value;if(e.action==='fechar_janela_local'&&!e.owner_window)e.owner_window=findOwner(e);renderLayout()};\n   $id('v35Owner').value=e.owner_window||'';\n   $id('v35Owner').onchange=ev=>{history();e.owner_window=ev.target.value;renderLayout()};\n   $id('v35GuessOwner').onclick=()=>{const id=findOwner(e);if(id){history();e.owner_window=id;renderLayout();status('Janela identificada: '+id)}else status('Nenhuma janela com ID está cobrindo o centro deste botão. Crie ou selecione uma janela primeiro.')};\n  }\n };\n const origRenderStage=renderStage;\n renderStage=function(){origRenderStage();\n  for(const div of stage.querySelectorAll('.art')){const e=screen().elements.find(a=>a.id===div.dataset.id);if(!e)continue;\n   if(e.hotspot){div.classList.add('v35-hotspot');div.style.background='rgba(0,160,240,.11)';div.style.border='2px dashed #39d7fe';div.title=(e.name||'Área clicável')+' • '+(e.action||'SEM AÇÃO')}\n   if(e.locked){div.classList.add('v35-locked');div.title='BLOQUEADO • '+(e.name||'elemento')}\n  }\n };\n stage.addEventListener('pointerdown',ev=>{const a=ev.target.closest('.art');if(!a||placing)return;const e=screen().elements.find(x=>x.id===a.dataset.id);if(!e?.locked)return;\n  ev.stopImmediatePropagation();ev.preventDefault();if(ev.altKey||$id('marqueeMode')?.checked){beginMarquee(ev)}else{selected=e.id;multiSelected.clear();multiSelected.add(e.id);renderLayout();status('Elemento bloqueado. Desmarque Bloquear movimento no inspetor para mover.')}} ,true);\n // Bloqueio também para seleção por área: previne arrastar travados dentro de grupos.\n const origPointerMove=pointerMove;\n pointerMove=function(ev){if(drag?.group){drag.group=drag.group.filter(g=>!screen().elements.find(e=>e.id===g.id)?.locked)}if(drag?.id&&screen().elements.find(e=>e.id===drag.id)?.locked){pointerEnd();return}origPointerMove(ev)};\n // Normalização exportada não deve conter sinais gráficos do modo de edição.\n const originalNorm=normScreenForGodot;\n normScreenForGodot=function(s){const out=originalNorm(s);for(const e of out.elements){if(e.hotspot){e.background='#00000000';e.border_color='#00000000';e.text='';e.visible=e.visible!==false}}return out};\n function collectDiagnostics(){const warnings=[],infos=[],errors=[];const ids=new Set();let total=0;const assetIds=new Set(state.assets.map(a=>a.id));const windowByScreen={};\n  for(const [key,s] of Object.entries(state.screens)){\n   const ws=new Set(s.elements.filter(e=>e.window_id).map(e=>e.window_id));windowByScreen[key]=[...ws];\n   for(const e of s.elements){total++;if(ids.has(key+'|'+e.id))errors.push(`${key}: ID repetido em ${e.name}`);ids.add(key+'|'+e.id);\n    if(e.x<0||e.y<0||e.x+e.w>s.resolution.width+1||e.y+e.h>s.resolution.height+1)warnings.push(`${key}: ${e.name} ultrapassa os limites da tela`);\n    if(e.assetId&&!assetIds.has(e.assetId))errors.push(`${key}: imagem ausente em ${e.name}`);\n    if(e.action_icon_asset&&!assetIds.has(e.action_icon_asset))errors.push(`${key}: ícone do botão ausente em ${e.name}`);\n    if(e.type==='button'&&(!e.action||!String(e.action).trim()))warnings.push(`${key}: botão \"${e.name}\" sem ação vinculada`);\n    if(e.type==='button'&&e.action==='fechar_janela_local'&&!e.owner_window)warnings.push(`${key}: botão \"${e.name}\" fecha janela, mas não tem janela proprietária`);\n    if(e.type==='button'&&e.action==='fechar_janela_local'&&e.owner_window&&!ws.has(e.owner_window))warnings.push(`${key}: botão \"${e.name}\" referencia janela que não existe (${e.owner_window})`);\n    if(e.hotspot&&e.type!=='button')warnings.push(`${key}: área clicável \"${e.name}\" não é botão`);\n    if(e.w<12||e.h<12)warnings.push(`${key}: \"${e.name}\" pequeno demais para interação`);\n   }\n  }\n  const lib=state.creatorLibrary;const studio=window.ApoenaCreator33?.getData?.();\n  if(studio){const mids=new Set((studio.models||[]).map(m=>m.id));for(const [char,v] of Object.entries(studio.characterBindings||{})){for(const id of [v.modelId,...(v.extraAssetIds||[])].filter(Boolean))if(!mids.has(id))errors.push(`3D: ${char} vincula modelo inexistente (${id})`);}\n   const local=(studio.models||[]).filter(m=>m.localPath);if(local.length)infos.push(`${local.length} modelos locais: reconecte a pasta antes de exportar`);\n  }\n  if(!Object.keys(state.screens).length)errors.push('Projeto sem telas');\n  const incomplete=state.items.filter(i=>!i.iconId).length;if(incomplete)warnings.push(`${incomplete} itens do catálogo sem ícone`);\n  if(lib?.entries?.length)infos.push(`${lib.entries.length} entradas na biblioteca 3D local`);\n  if(state.assets.length>300)infos.push(`${state.assets.length} imagens incorporadas ao projeto: considere manter modelos 3D fora do JSON`);\n  return {schema:'apoena.preflight.v1',createdAt:new Date().toISOString(),screens:Object.keys(state.screens).length,elements:total,items:state.items.length,assets:state.assets.length,errors,warnings,notes:infos,important:'Este verificador analisa dados e layouts. Não comprova a execução de ações no Godot.'};\n }\n function report(){const r=collectDiagnostics(),out=$id('v35Results');out.hidden=false;out.innerHTML=`<strong>Pré-verificação: ${r.errors.length} erro(s), ${r.warnings.length} aviso(s)</strong><p class=\"hint\">${r.screens} telas • ${r.elements} elementos • ${r.items} itens • ${r.assets} imagens</p>`+\n  (r.errors.length?`<h4>Erros</h4>${r.errors.slice(0,40).map(x=>`<p class=\"v35-err\">${H(x)}</p>`).join('')}`:'')+\n  (r.warnings.length?`<h4>Avisos</h4>${r.warnings.slice(0,60).map(x=>`<p class=\"v35-warning\">${H(x)}</p>`).join('')}`:'')+\n  (r.notes.length?`<h4>Observações</h4>${r.notes.map(x=>`<p>${H(x)}</p>`).join('')}`:'')+\n  '<p class=\"hint\">O relatório não garante que todos os scripts estejam conectados no Godot. Reveja avisos antes de exportar.</p>';\n  status(`Verificação concluída: ${r.errors.length} erros e ${r.warnings.length} avisos.`);\n  return r;\n }\n $id('v35Audit').onclick=report;\n $id('v35ExportAudit').onclick=()=>{const r=report();jsonDownload(r,'APOENA_DIAGNOSTICO_V35.json')};\n $id('v35Save').onclick=()=>$id('saveProject').click();\n // Avisar antes de exportar. Nunca interrompe sem permissão: avisa e deixa escolher.\n const godot=$id('exportGodot');godot.addEventListener('click',ev=>{if(!ev.isTrusted)return;const r=collectDiagnostics();if(r.errors.length){if(!confirm(`Há ${r.errors.length} erro(s) no projeto. Exportar mesmo assim?\\nUse \"Verificar projeto\" para visualizar os detalhes.`)){ev.preventDefault();ev.stopImmediatePropagation();report();return}}},true);\n // Expor apenas para testes manuais, sem mexer na persistência.\n window.ApoenaCreator35={collectDiagnostics,report,setMode,getMode:()=>placing,actionDefs};\n status('Game Creator 3.5: edição de botões sobre imagem e diagnóstico preventivo disponíveis.');\n})();\n\n\n/* APOENA GAME CREATOR 3.6 — Upload direto, logos, fundos e novo projeto vazio. */\n(()=>{\n const el=id=>document.getElementById(id),safe=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\n function persistNow(){if(window.ApoenaV3Test?.autosave)window.ApoenaV3Test.autosave()}\n function saveImportedNow(){persistNow();if(typeof v3DbPut==='function'&&typeof v3AutoAllowed!=='undefined'&&v3AutoAllowed){v3DbPut(JSON.stringify(state)).catch(err=>status('Imagem no projeto, mas o navegador não salvou a cópia local: '+err.message+'. Use Salvar projeto editável.'))}} \n const rawMakeAsset=makeAsset;makeAsset=function(name,data,source='upload',category='nao_classificado'){if(source==='upload'){const duplicate=state.assets.find(a=>a.data===data);if(duplicate)return duplicate}return rawMakeAsset(name,data,source,category)};\n function note(m){status(m);persistNow()}\n function clearReferences(){\n   const oldIds=new Set(state.assets.map(x=>x.id));\n   for(const s of Object.values(state.screens)){\n     if(s.background&&oldIds.has(s.background.assetId)){s.background.assetId='';s.background.texture=''}\n     for(const e of s.elements||[]){if(oldIds.has(e.assetId))e.assetId='';if(oldIds.has(e.action_icon_asset))e.action_icon_asset='';if(oldIds.has(e.iconId))e.iconId=''}\n   }\n   for(const item of state.items||[])if(oldIds.has(item.iconId))item.iconId='';\n   for(const c of state.characters||[])if(oldIds.has(c.iconId))c.iconId='';\n }\n function imageAsset(file){return fileToPNG(file).then(data=>{\n   const existing=state.assets.find(a=>a.data===data);\n   return existing||makeAsset(file.name,data,'upload','nao_classificado');\n })}\n async function importIntoElement(file,screenId,elementId,prop){\n   if(!file)return;\n   const a=await imageAsset(file);const obj=state.screens[screenId]?.elements.find(e=>e.id===elementId);\n   if(!obj){note('Imagem adicionada à biblioteca; o elemento antigo não está mais nesta tela.');return}\n   if(screenId===current)history();obj[prop]=a.id;\n   refreshAssetLists();renderLayout();saveImportedNow();\n   note('Imagem \"'+a.name+'\" vinculada ao elemento e guardada no projeto. Salve o projeto JSON como cópia permanente.');\n }\n async function insertNewImages(files,asLogo=false){\n   if(!files.length)return;\n   let count=0;\n   for(const f of files){try{\n     const a=await imageAsset(f);history();\n     const e=newElement('image',asLogo?'Logotipo • '+a.name:'Foto • '+a.name);\n     e.assetId=a.id;e.x=asLogo?Math.round(screen().resolution.width*.08):128+count*24;\n     e.y=asLogo?Math.round(screen().resolution.height*.07):120+count*24;\n     e.w=asLogo?260:320;e.h=asLogo?130:220;e.z_index=screen().elements.length;\n     e.image_fit='contain';screen().elements.push(e);selected=e.id;multiSelected=new Set([e.id]);count++;\n   }catch(err){alert('Não consegui importar '+f.name+': '+err.message)}}\n   if(count){refreshAssetLists();renderLayout();saveImportedNow();note(count+' imagem(ns) inserida(s) no layout e registrada(s) na biblioteca do projeto.')}\n }\n el('v36DatabaseManage').onclick=()=>{switchPage('assets');el('v36BlankProject').scrollIntoView({block:'center'});};\n el('v36InsertFile').onchange=async ev=>{const files=[...ev.target.files];ev.target.value='';await insertNewImages(files)};\n el('v36AddLogo').onclick=()=>{\n   const picker=document.createElement('input');picker.type='file';picker.accept='image/png,image/jpeg,image/webp';picker.onchange=async()=>insertNewImages([...picker.files],true);picker.click();\n };\n // Diretamente no elemento botão — edição permite escolher uma foto sem passar pela biblioteca.\n const beforeInspector=renderInspector;\n renderInspector=function(){beforeInspector();const e=element();if(!e||multiSelected.size>1)return;\n   const area=el('inspector');if(!area||area.querySelector('#v36Props'))return;\n   const wrap=document.createElement('section');wrap.id='v36Props';wrap.className='v36-upload-block';\n   if(e.type==='button'){\n     wrap.innerHTML=`<h3>📤 Imagem deste botão</h3><label>Enviar PNG / JPG / WebP diretamente</label><input id=\"v36ButtonFile\" type=\"file\" accept=\"image/png,image/jpeg,image/webp\"><label>Ou escolher da biblioteca</label><select id=\"v36ButtonAsset\">${assetOptions(e.action_icon_asset)}</select><label>Como mostrar</label><select id=\"v36ButtonLook\"><option value=\"image\">Só imagem</option><option value=\"image_text\">Imagem + texto</option><option value=\"text\">Só texto</option></select><label><input id=\"v36NoButtonFrame\" type=\"checkbox\" ${e.hide_button_frame?'checked':''}> Sem moldura (imagem livre)</label><div id=\"v36ButtonPrev\"></div><p class=\"hint\">O comando do botão continua separado da imagem. A mesma imagem fica disponível para reutilizar em outras telas e no Godot.</p>`;\n     area.append(wrap);el('v36ButtonLook').value=e.button_look||'image_text';\n     const preview=()=>{const a=asset(e.action_icon_asset);el('v36ButtonPrev').innerHTML=a?`<img class=\"v36-preview\" src=\"${a.data}\" alt=\"Prévia da imagem\">`:'<p class=\"hint\">Sem imagem personalizada.</p>'};preview();\n     el('v36ButtonFile').onchange=async event=>{const f=event.target.files?.[0];if(!f)return;try{await importIntoElement(f,current,e.id,'action_icon_asset')}catch(err){alert(err.message)}};\n     el('v36ButtonAsset').onchange=ev=>{history();e.action_icon_asset=ev.target.value;renderLayout();persistNow()};\n     el('v36ButtonLook').onchange=ev=>{history();e.button_look=ev.target.value;renderLayout();persistNow()};\n     el('v36NoButtonFrame').onchange=ev=>{history();e.hide_button_frame=ev.target.checked;renderLayout();persistNow()};\n   }else if(e.type==='image'||e.type==='character_preview'){\n     wrap.innerHTML=`<h3>📤 Foto ou logotipo</h3><label>Substituir imagem diretamente</label><input id=\"v36DirectImageFile\" type=\"file\" accept=\"image/png,image/jpeg,image/webp\"><label>Enquadramento do elemento</label><select id=\"v36ImageFit\"><option value=\"contain\">Inteira, sem corte</option><option value=\"cover\">Preencher, cortar excesso</option><option value=\"fill\">Esticar</option></select><p class=\"hint\">A largura e altura continuam editáveis nas propriedades de cima ou por arraste.</p>`;\n     area.append(wrap);el('v36ImageFit').value=e.image_fit||'contain';\n     el('v36DirectImageFile').onchange=async ev=>{const f=ev.target.files?.[0];if(!f)return;try{await importIntoElement(f,current,e.id,'assetId')}catch(err){alert(err.message)}};\n     el('v36ImageFit').onchange=ev=>{history();e.image_fit=ev.target.value;renderLayout();persistNow()};\n   }\n };\n const beforeStage=renderStage;\n renderStage=function(){beforeStage();const s=screen();const b=s.background||{};const bg=asset(b.assetId),node=el('stage');\n   if(bg){node.style.backgroundSize=b.fit==='contain'?'contain':b.fit==='stretch'?'100% 100%':b.fit==='custom'?(Number(b.scale||100)+'%'):'cover';node.style.backgroundPosition=`${Number(b.x??50)}% ${Number(b.y??50)}%`;node.style.backgroundRepeat='no-repeat'}\n   for(const box of node.querySelectorAll('.art')){\n     const e=s.elements.find(x=>x.id===box.dataset.id);if(!e)continue;\n     if(e.type==='image'){const img=box.querySelector('img');if(img)img.style.objectFit=e.image_fit||'contain'}\n     if(e.type==='button'){\n       const a=asset(e.action_icon_asset),look=e.button_look||'image_text';\n       if(e.hide_button_frame){box.style.border='0';box.style.background='transparent'}\n       if(a&&look!=='text'){\n         box.classList.add('v36-image-button');if(look==='image_text')box.classList.add('v36-button-text');\n         // A versão 3.4 já inseriu a prévia do ícone. Não duplicar a mesma imagem.\n         let image=box.querySelector('img.v34-button-icon');\n         if(!image){image=document.createElement('img');image.src=a.data;box.prepend(image)}\n         image.classList.add('v36-button-photo');image.style.objectFit='contain';\n       }\n       if(look==='image'&&a){const t=box.querySelector('.txt');if(t)t.style.display='none'}\n       if(look==='text'){const i=box.querySelector('img.v34-button-icon');if(i)i.style.display='none'}\n     }\n   }\n };\n // Preserve selectable background settings in the editable JSON and exports.\n function updateBgControls(){const bg=screen().background;el('v36BgMode').value=bg.fit||'cover';el('v36BgScale').value=bg.scale||100;el('v36BgX').value=bg.x??50;el('v36BgY').value=bg.y??50}\n const priorLayout=renderLayout;renderLayout=function(){priorLayout();updateBgControls()};\n for(const [id,prop] of [['v36BgMode','fit'],['v36BgScale','scale'],['v36BgX','x'],['v36BgY','y']])el(id).onchange=ev=>{history();screen().background[prop]=id==='v36BgMode'?ev.target.value:Number(ev.target.value);renderStage();persistNow()};\n // Explicit destructive operations: no silent deletion of other users' content or original PC files.\n el('v36ClearAssets').onclick=()=>{\n   if(!state.assets.length){alert('Esta biblioteca já está vazia.');return}\n   if(!confirm('Excluir TODAS as '+state.assets.length+' imagens da biblioteca deste projeto? Os layouts perderão as imagens associadas. Os arquivos do seu PC não serão apagados.'))return;\n   const word=prompt('Para confirmar, digite LIMPAR IMAGENS (sem aspas):');if(word!=='LIMPAR IMAGENS')return;\n   clearReferences();state.assets=[];ensureCreatorState();state.creatorSettings.officialPackEnabled=false;\n   refreshAssetLists();renderLayout();renderDatabase();creatorRenderHome();note('Biblioteca zerada. Itens e receitas foram preservados, mas agora estão sem imagens. Salve um novo JSON.');\n };\n el('v36BlankProject').onclick=()=>{\n   if(!confirm('Criar um projeto novo COMPLETAMENTE VAZIO? Você perderá todas as telas, itens, poções, imagens, receitas, personagens, vínculos 3D e sistemas do projeto aberto.'))return;\n   const check=prompt('Digite NOVO PROJETO para confirmar:');if(check!=='NOVO PROJETO')return;\n   // Safest path: erase only state data in current HTML document; do not affect PC files or prior JSON backups.\n   for(const key of Object.keys(state))delete state[key];\n   Object.assign(state,{schema:'apoena.central.v1',name:'Meu Jogo',screens:{menu_principal:newScreen('menu_principal')},assets:[],items:[],recipes:[],characters:[],flows:[],systemsV3:{},creatorSettings:{schema:'apoena.gamecreator.v3',officialPackEnabled:false},integration:{sceneTargets:{},bridgeVersion:1},creatorLibrary:{entries:[]}});\n   current='menu_principal';selected=null;multiSelected.clear();undos=[];redos=[];\n   ensureCreatorState();if(typeof v3Data==='function')v3Data();refreshAssetLists();renderLayout();renderRecipes();renderDatabase();if(typeof creatorRenderHome==='function')creatorRenderHome();if(typeof creatorRenderCharacters==='function')creatorRenderCharacters();if(typeof creatorRenderFlows==='function')creatorRenderFlows();if(typeof v3Draw==='function')v3Draw();switchPage('layouts');\n   note('Novo projeto sem dados do Apoena criado. Use Salvar projeto editável para manter uma cópia.');\n };\n // Avoid display inconsistency when selecting screen. Background controls update on selection, including switches.\n el('screenSelect').addEventListener('change',()=>setTimeout(updateBgControls,0));\n const norm=normScreenForGodot;normScreenForGodot=function(layout){const c=norm(layout);\n   for(const e of c.elements){if(e.type==='button'){e.button_look=e.button_look||'image_text';e.hide_button_frame=!!e.hide_button_frame}}\n   return c;\n };\n window.ApoenaCreator36={insertNewImages,clearReferences,updateBgControls,version:'3.6'};\n updateBgControls();\n status('Game Creator 3.6: upload direto de botões/logotipos, ajustes de fundo e projeto vazio disponíveis.');\n})();\n\n/* APOENA GAME CREATOR v3.7 | Produção guiada, drops, economia e HUD. */\n(()=>{\n'use strict';\nconst byId=id=>document.getElementById(id);\nconst esc37=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst validId=s=>slug(String(s||''));\nconst $st=()=>state;\nconst save37=()=>{if(window.ApoenaV3Test?.autosave)window.ApoenaV3Test.autosave();};\nfunction notice37(message){status(message);save37()}\n// UMA navegação para iniciantes. A barra antiga continua acessível nas ferramentas avançadas.\nconst navItems=[\n ['Início e telas',[['producao','🧭 Começar / fluxo guiado'],['layouts','▣ Montar telas'],['images','▧ Editar imagem'],['assets','▤ Fotos e biblioteca'],['icons','◈ Criar ícones'],['slicer','✂ Cortador de ícones']]],\n ['Itens e economia',[['inventory','🎒 Itens e regras'],['drops','🧪 Ingredientes e drops'],['recipes','⚗ Receitas'],['database','▰ Banco de dados'],['cards','✦ Cards']]],\n ['Personagens e jogo',[['characters','◉ Personagens'],['animacoes','🎬 Animações 3D'],['controles','🎮 Controles PC/Android'],['creator','◈ Conteúdo oficial']]],\n ['Lógica e testes',[['flows','⤷ Ações e eventos'],['simulator','▷ Simulador'],['validation','✓ Verificar projeto'],['guide','? Exportar Godot']]]\n];\nconst nav37=byId('v37Nav');\nfor(const [group,links] of navItems){const det=document.createElement('details');det.className='v37-group';const summary=document.createElement('summary');summary.textContent=group;det.append(summary);const content=document.createElement('div');content.className='v37-menu';for(const [pg,title] of links){const btn=document.createElement('button');btn.type='button';btn.textContent=title;btn.dataset.goto=pg;btn.onclick=()=>{go37(pg);det.open=false};content.append(btn)}det.append(content);nav37.append(det)}\nconst jump=document.createElement('select');jump.id='v37QuickJump';jump.setAttribute('aria-label','Ir rapidamente para uma área');jump.innerHTML='<option value=\"\">🔎 Ir para ferramenta…</option>'+navItems.map(([g,links])=>`<optgroup label=\"${esc37(g)}\">`+links.map(([pg,title])=>`<option value=\"${pg}\">${esc37(title)}</option>`).join('')+'</optgroup>').join('');jump.onchange=()=>{if(jump.value)go37(jump.value);jump.value=''};nav37.append(jump);\nconst help=document.createElement('button');help.textContent='Como começar';help.className='v37-help';help.onclick=()=>go37('producao');nav37.append(help);\nfunction go37(pg){if(pg==='drops'||pg==='producao'){switchPage(pg);if(pg==='drops')drawDrops37();else drawGuide37();return}switchPage(pg);if(pg==='inventory')refreshExtraItem37();if(pg==='recipes')refreshRecipeAssistant37()}\n// Preservar os painéis técnicos já existentes: a nova interface reutiliza state.systemsV3.loot e npcs.\nfunction records37(){const s=state.systemsV3||(state.systemsV3={});for(const key of [\"npcs\",\"loot\"])if(!Array.isArray(s[key]))s[key]=[];return s;}\nfunction renderOptions37(rows,selected='',empty='Selecione…'){\n return '<option value=\"\">'+esc37(empty)+'</option>'+rows.map(x=>`<option value=\"${esc37(x.id)}\" ${String(selected)===String(x.id)?'selected':''}>${esc37(x.name||x.id)} (${esc37(x.id)})</option>`).join('');\n}\nfunction updateCombos37(){\n const npcs=records37().npcs||[];const mobs=npcs.filter(x=>x.kind==='inimigo'||x.kind==='chefe');\n byId('v37Monster').innerHTML=renderOptions37(mobs,byId('v37Monster').value,'Novo monstro (digitar abaixo)');\n for(const id of ['v37DropItem','v37RecipeIngredient','v37ItemLink']){\n  if(byId(id))byId(id).innerHTML=renderOptions37(state.items,byId(id).value,'Selecione um item cadastrado');\n }\n if(byId('v37RecipeResult'))byId('v37RecipeResult').innerHTML=renderOptions37(state.items,byId('v37RecipeResult').value,'Item produzido na receita');\n if(byId('v37MonsterList'))byId('v37MonsterList').textContent=mobs.length+' monstro(s) cadastrados';\n}\nfunction newIngredient37(){\n const name=byId('v37IngName').value.trim(),id=validId(byId('v37IngId').value||name);\n if(!name||!id)return alert('Preencha o nome do ingrediente.');\n if(state.items.some(x=>x.id===id))return alert('Já existe um item com esse ID. Selecione-o na lista de drops.');\n let item={id,name,category:'material',rarity:'comum',iconId:'',description:byId('v37IngDesc').value.trim(),price:0,equippable:false,equipmentSlot:'',effect:{type:'nenhum',value:0,duration:0},consumable:false,maxStack:99,craftCost:0,visibility:{inventory:true,lab:true,store:false,forge:false,crystal:false,available:true},gameplayEnabled:false,source:'custom',origin:'drop',scope:'permanente',actionId:'',targetType:'nenhum',allowedCharacters:[],currency:'ouro',diamonds:0};\n state.items.push(item);\n byId('v37IngName').value='';byId('v37IngId').value='';byId('v37IngDesc').value='';\n refreshItemIcons();renderItems();renderDatabase();updateCombos37();byId('v37DropItem').value=id;byId('v37RecipeIngredient').value=id;\n notice37('Ingrediente criado no banco central: '+name+'. Agora defina qual monstro o entrega.');drawGuide37();drawDrops37();\n}\nbyId('v37CreateIngredient').onclick=newIngredient37;\nbyId('v37NewIngredientIcon').onchange=async ev=>{\n const file=ev.target.files?.[0];if(!file)return;\n try{const data=await fileToPNG(file);const a=makeAsset(file.name,data,'upload','material');const selected=byId('v37DropItem').value;if(selected){const i=state.items.find(x=>x.id===selected);if(i)i.iconId=a.id}refreshAssetLists();renderItems();save37();notice37('Ícone importado e salvo na biblioteca.');}\n catch(e){alert('Erro ao importar ícone: '+e.message)}\n ev.target.value='';\n};\nfunction getOrCreateMonster37(){\n let selected=byId('v37Monster').value;\n if(selected)return records37().npcs.find(x=>x.id===selected)||null;\n const name=byId('v37MonsterName').value.trim(),id=validId(byId('v37MonsterId').value||name);\n if(!name||!id){alert('Selecione um monstro ou informe o nome de um novo.');return null}\n if(records37().npcs.some(x=>x.id===id)){alert('ID de monstro já existe. Selecione na lista.');return null}\n const npc={id,name,kind:'inimigo',status:'rascunho',regionId:'',characterId:'',hp:0,damage:0,behavior:'perseguir',aggro:0,dialogueId:'',lootId:'',modelPath:''};records37().npcs.push(npc);return npc;\n}\nfunction addDrop37(){\n const itemId=byId('v37DropItem').value, chance=Number(byId('v37Chance').value),min=Number(byId('v37DropMin').value),max=Number(byId('v37DropMax').value);\n if(!state.items.some(x=>x.id===itemId))return alert('Escolha um ingrediente/item cadastrado.');\n if(!Number.isFinite(chance)||chance<0||chance>100)return alert('A chance deve ficar entre 0 e 100%.');\n if(!Number.isInteger(min)||!Number.isInteger(max)||min<1||max<min||max>9999)return alert('Quantidades precisam ser inteiras, entre 1 e 9999, com mínimo menor ou igual ao máximo.');\n const npc=getOrCreateMonster37();if(!npc)return;\n let table=records37().loot.find(x=>x.id===npc.lootId);\n if(!table){const base='drop_'+npc.id;let id=base,num=2;while(records37().loot.some(x=>x.id===id))id=base+'_'+num++;\n  table={id,name:'Itens de '+npc.name,status:'rascunho',entries:[],goldMin:0,goldMax:0,notes:''};records37().loot.push(table);npc.lootId=id;\n }\n const existing=table.entries.find(x=>x.itemId===itemId);\n if(existing){if(!confirm('Este monstro já dropa esse item. Substituir a chance e quantidade?'))return;Object.assign(existing,{chance,min,max})}\n else table.entries.push({itemId,chance,min,max});\n updateCombos37();byId('v37Monster').value=npc.id;\n drawDrops37();drawGuide37();notice37('Drop salvo: '+npc.name+' → '+state.items.find(x=>x.id===itemId).name+' ('+chance+'%).');\n}\nbyId('v37AddDrop').onclick=addDrop37;\nfunction drawDrops37(){updateCombos37();const box=byId('v37DropRecords');let rows=[];\n for(const mob of records37().npcs.filter(x=>x.lootId)){const table=records37().loot.find(x=>x.id===mob.lootId);if(!table)continue;for(const e of table.entries||[])rows.push({mob,table,e,item:state.items.find(i=>i.id===e.itemId)});}\n box.innerHTML=rows.length?rows.map((r,index)=>`<div class=\"v37-drop-row\"><div><strong>${esc37(r.mob.name)}</strong> → ${esc37(r.item?.name||r.e.itemId)}<small>${esc37(r.e.itemId)} • ${Number(r.e.chance)}% • ${Number(r.e.min)}–${Number(r.e.max)} un.</small></div><button data-drop-edit=\"${index}\">Editar</button><button class=\"danger\" data-drop-del=\"${index}\">Excluir</button></div>`).join(''):'<p class=\"hint\">Ainda não há drops vinculados a monstros. Cadastre acima; os itens continuarão no mesmo banco de receitas e lojas.</p>';\n box.querySelectorAll('[data-drop-edit]').forEach(btn=>btn.onclick=()=>{const r=rows[Number(btn.dataset.dropEdit)];byId('v37Monster').value=r.mob.id;byId('v37DropItem').value=r.e.itemId;byId('v37Chance').value=r.e.chance;byId('v37DropMin').value=r.e.min;byId('v37DropMax').value=r.e.max;byId('v37AddDrop').scrollIntoView({block:'center'})});\n box.querySelectorAll('[data-drop-del]').forEach(btn=>btn.onclick=()=>{const r=rows[Number(btn.dataset.dropDel)];if(!confirm('Excluir esse drop? O item cadastrado continuará no banco de dados.'))return;r.table.entries=r.table.entries.filter(x=>x!==r.e);drawDrops37();save37()});\n}\nfunction refreshRecipeAssistant37(){updateCombos37()}\nbyId('v37PutIngredient').onclick=()=>{\n const id=byId('v37RecipeIngredient').value,qty=Number(byId('v37RecipeQty').value);\n if(!id||!Number.isInteger(qty)||qty<1)return alert('Escolha o ingrediente e uma quantidade válida.');\n const textarea=byId('recipeIngredients');const lines=textarea.value.split(/\\n/).map(x=>x.trim()).filter(Boolean).filter(x=>x.split(':')[0]!==id);lines.push(id+':'+qty);textarea.value=lines.join('\\n');notice37('Ingrediente '+id+' inserido na receita em edição. Salve a receita para confirmar.');\n};\nbyId('v37GoRecipe').onclick=()=>{const item=byId('v37DropItem').value;go37('recipes');refreshRecipeAssistant37();if(item)byId('v37RecipeIngredient').value=item};\nbyId('v37GoInventory').onclick=()=>{const id=byId('v37DropItem').value;const i=state.items.find(x=>x.id===id);if(i)fillItem(i);else go37('inventory')};\n// Campos avançados utilizam o registro central do item, inclusive quando o ícone é gerado em outra aba.\nconst metaDefault={scope:'permanente',currency:'ouro',diamonds:0,allowedCharacters:[],useAction:'nenhuma',targetType:'usuario',auriumCost:0,quantityOnUse:1,sourceType:'exploracao',unlockLevel:0,requiredMode:'ambos',bonusAttribute:'nenhum',bonusValue:0};\nfunction extraMeta37(){return {\n scope:byId('v37ItemScope').value,currency:byId('v37ItemCurrency').value,diamonds:Math.max(0,Number(byId('v37ItemDiamonds').value)||0),allowedCharacters:byId('v37ItemUsers').value.split(',').map(x=>validId(x)).filter(Boolean),useAction:byId('v37ItemUseAction').value,targetType:byId('v37ItemTarget').value,auriumCost:Math.max(0,Number(byId('v37ItemAurium').value)||0),quantityOnUse:Math.max(1,Number(byId('v37ItemQtyUsed').value)||1),sourceType:byId('v37ItemOrigin').value,unlockLevel:Math.max(0,Number(byId('v37ItemLevel').value)||0),requiredMode:byId('v37ItemMode').value,bonusAttribute:byId('v37ItemBonusStat').value,bonusValue:Number(byId('v37ItemBonusVal').value)||0\n}}\nfunction fillMeta37(item={}){\n const a={...metaDefault,...item};\n for(const [id,k] of [['v37ItemScope','scope'],['v37ItemCurrency','currency'],['v37ItemDiamonds','diamonds'],['v37ItemUseAction','useAction'],['v37ItemTarget','targetType'],['v37ItemAurium','auriumCost'],['v37ItemQtyUsed','quantityOnUse'],['v37ItemOrigin','sourceType'],['v37ItemLevel','unlockLevel'],['v37ItemMode','requiredMode'],['v37ItemBonusStat','bonusAttribute'],['v37ItemBonusVal','bonusValue']])byId(id).value=a[k];\n byId('v37ItemUsers').value=(a.allowedCharacters||[]).join(', ');\n}\nconst fillPrevious=fillItem;fillItem=function(item){fillPrevious(item);fillMeta37(item)};\nconst saveItemPrev=byId('addItem').onclick;\nbyId('addItem').onclick=function(e){const oldEditing=editingItem;const requested=validId(byId('itemId').value||byId('itemName').value);\n const meta=extraMeta37();saveItemPrev.call(this,e);\n const item=state.items.find(x=>x.id===requested);\n if(item&&(editingItem===requested||oldEditing===requested)){Object.assign(item,meta);renderItems();renderDatabase();save37();updateCombos37()}\n};\nbyId('clearItem').addEventListener('click',()=>fillMeta37());\nbyId('v37ItemIconDirect').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;\n try{const image=await fileToPNG(file),assetObj=makeAsset(file.name,image,'upload',byId('itemCategory').value);refreshItemIcons(assetObj.id);notice37('Ícone importado diretamente e escolhido para o item. Clique em Salvar item.');}\n catch(err){alert('Não foi possível importar: '+err.message)}e.target.value=''};\n// Gerador de ícones: linka a arte ao item existente sem cadastrar o mesmo conteúdo duas vezes.\nfunction lastAsset37(){return state.assets.at(-1)}\nconst keepIconPrev=byId('keepIcon').onclick;\nbyId('keepIcon').onclick=function(ev){const before=new Set(state.assets.map(x=>x.id));keepIconPrev.call(this,ev);const result=state.assets.findLast(x=>!before.has(x.id));if(result){byId('v37IconAssetNow').innerHTML='<option value=\"'+esc37(result.id)+'\">'+esc37(result.name)+'</option>';byId('v37IconAssetNow').value=result.id;notice37('Ícone criado. Selecione o item que deverá utilizá-lo e clique em Vincular.')}};\nbyId('v37IconBind').onclick=()=>{\n const id=byId('v37ItemLink').value,artId=byId('v37IconAssetNow').value;\n const it=state.items.find(x=>x.id===id),a=state.assets.find(x=>x.id===artId);\n if(!it||!a)return alert('Primeiro salve um ícone e escolha um item do banco central.');\n it.iconId=a.id;renderItems();renderDatabase();save37();notice37('Imagem '+a.name+' vinculada ao item '+it.name+'. Loja, mochila, drops e receitas utilizam o mesmo ID.')\n};\nconst iconPrev=byId('refreshIcon').onclick;\nbyId('refreshIcon').addEventListener('click',()=>updateCombos37());\n// Ficha de herói: cada peça é um elemento arrastável/editável; as barras levam chaves de ligação.\nconst hudSamples={hp:{name:'HP / Vida',color:'#c55762',value:0.8},aurium:{name:'AUR / Aurium',color:'#3687d5',value:0.65},especial:{name:'Especial',color:'#d3a33d',value:0.35},xp:{name:'XP / Evolução',color:'#58b87a',value:0.45}};\nfunction addHud37(){\n const s=screen();if(!s)return;\n history();const id='hud_'+uid();const midX=Math.round(s.resolution.width*0.09),midY=Math.round(s.resolution.height*0.11);let index=0;\n const add=(type,name,x,y,w,h,text,props={})=>{const e=newElement(type,name);Object.assign(e,{x,y,w,h,text,z_index:s.elements.length,component_group:id,...props});s.elements.push(e);index++;return e};\n add('panel','Ficha do herói',midX,midY,435,237,'',{background:'#132c3e',border_color:'#8ba5ad',component_type:'hero_hud_background'});\n add('image','Rosto do herói',midX+13,midY+18,92,99,'',{hud_portrait:true,component_type:'hero_hud_portrait'});\n add('label','Nome do herói',midX+116,midY+13,292,31,'NOME DO HERÓI',{font_size:20,text_align:'left',hud_metric:'hero_name',component_type:'hero_hud_text'});\n add('label','Nível do herói',midX+116,midY+46,200,25,'NÍVEL 1',{font_size:16,text_align:'left',hud_metric:'hero_level',component_type:'hero_hud_text'});\n let yy=midY+106;for(const [key,def] of Object.entries(hudSamples)){add('panel',def.name,midX+112,yy,296,25,def.name.toUpperCase(),{background:'#1a2d35',border_color:'#68818d',font_size:12,component_type:'hero_hud_bar',binding_metric:key,bar_color:def.color,preview_value:def.value});yy+=31}\n selected=s.elements.at(-1).id;multiSelected=new Set(s.elements.filter(x=>x.component_group===id).map(x=>x.id));\n renderLayout();notice37('Ficha completa inserida: retrato, nome, nível, HP, Aurium, Especial e XP. Edite, mova ou selecione as peças como desejar.');\n}\nbyId('v37AddHUD').onclick=addHud37;\nconst prevStage37=renderStage;renderStage=function(){prevStage37();const s=screen(),root=byId('stage');\n for(const e of s.elements){const node=[...root.querySelectorAll('.art')].find(n=>n.dataset.id===e.id);if(!node)continue;\n if(e.component_type==='hero_hud_bar'){\n  node.classList.add('v37-statusbar');node.style.background='#17303b';const part=document.createElement('div');part.className='v37-bar-fill';part.style.background=e.bar_color||hudSamples[e.binding_metric]?.color||'#468dd1';part.style.width=(Math.min(1,Math.max(0,Number(e.preview_value??0.7)))*100)+'%';node.prepend(part);\n  const text=node.querySelector('.txt');if(text){text.classList.add('v37-bar-label');text.textContent=(hudSamples[e.binding_metric]?.name||e.text)+' • Prévia'}\n }\n if(e.hud_portrait&&!e.assetId){node.classList.add('v37-portrait-empty');node.title='Arraste uma imagem para o retrato ou envie uma foto no inspetor';}\n }\n};\nconst beforeInspector37=renderInspector;renderInspector=function(){beforeInspector37();const e=element(),box=byId('inspector');if(!e||multiSelected.size>1||!box)return;\n if(e.component_type==='hero_hud_bar'){\n  const wrap=document.createElement('div');wrap.className='v37-inspector';wrap.innerHTML=`<h3>🩺 Barra do herói</h3><label>Mostra qual valor</label><select id=\"v37InspectMetric\">${Object.entries(hudSamples).map(([k,v])=>`<option value=\"${k}\" ${e.binding_metric===k?'selected':''}>${esc37(v.name)}</option>`).join('')}</select><label>Cor da barra</label><input id=\"v37InspectColor\" type=\"color\" value=\"${esc37(e.bar_color||'#3687d5')}\"><label>Valor na prévia (%)</label><input id=\"v37InspectValue\" type=\"range\" min=\"0\" max=\"100\" value=\"${Math.round(Number(e.preview_value??0.7)*100)}\"><p class=\"hint\">Valores reais serão ligados à ficha do herói quando o componente for integrado ao Godot. Essa barra é configurável e exporta seu ID de dado.</p>`;box.append(wrap);\n  byId('v37InspectMetric').onchange=ev=>{history();e.binding_metric=ev.target.value;renderStage();save37()};byId('v37InspectColor').onchange=ev=>{history();e.bar_color=ev.target.value;renderStage();save37()};byId('v37InspectValue').oninput=ev=>{e.preview_value=Number(ev.target.value)/100;renderStage();save37()};\n }\n};\n// Extensão Godot: metadados além dos ícones. Somente executores ligados no Godot ativam efeitos.\nconst prevPack37=zipPack;zipPack=function(files){if(files.some(([name])=>name==='dados/apoena_catalogo_itens.json')){\n files.push(['dados/apoena_drop_tables_v37.json',JSON.stringify({schema:'apoena.drops.v1',tables:records37().loot,npcs:records37().npcs.map(x=>({id:x.id,name:x.name,kind:x.kind,lootId:x.lootId||''}))},null,2)]);\n files.push(['dados/apoena_itens_regras_v37.json',JSON.stringify({schema:'apoena.item_logic.v1',items:state.items.map(x=>({id:x.id,scope:x.scope||'permanente',currency:x.currency||'ouro',priceGold:x.price||0,priceDiamonds:x.diamonds||0,allowedCharacters:x.allowedCharacters||[],useAction:x.useAction||'nenhuma',targetType:x.targetType||'usuario',auriumCost:x.auriumCost||0,quantityOnUse:x.quantityOnUse||1,sourceType:x.sourceType||'',unlockLevel:x.unlockLevel||0,requiredMode:x.requiredMode||'ambos',bonusAttribute:x.bonusAttribute||'',bonusValue:x.bonusValue||0,visibility:itemVisibility(x),effect:x.effect||{}}))},null,2)]);\n files.push(['LEIA-DROPS-ITENS-HUD-v37.txt','Apoena Game Creator 3.7 | Dados de drops, regras e HUD\\nOs JSONs contêm ligações declarativas. A execução dos drops, compras, moedas e barras dinâmicas exige conectores/testes no Godot.\\nAba Drops usa o MESMO state.systemsV3.loot do editor técnico v3.0; não é outro banco.\\nHud: layouts/* contém component_type, binding_metric e bar_color por elemento.\\n']);\n }return prevPack37(files)};\n// Projetos: persistência e relatório de vínculos inválidos sem contaminar a biblioteca oficial.\nconst prevDB37=dbReportData;dbReportData=function(){const report=prevDB37();for(const npc of records37().npcs){if(npc.lootId&&!records37().loot.some(x=>x.id===npc.lootId))report.avisos.push('Monstro '+npc.name+': tabela de drops inexistente ('+npc.lootId+')')}\n for(const table of records37().loot){for(const entry of table.entries||[]){if(!state.items.some(x=>x.id===entry.itemId))report.avisos.push('Drop '+table.name+': item '+entry.itemId+' não existe');if(!(Number(entry.chance)>=0&&Number(entry.chance)<=100))report.avisos.push('Chance inválida em '+table.name)}}\n for(const i of state.items){if(i.currency==='diamantes'&&!(Number(i.diamonds)>=0))report.avisos.push('Preço em diamantes inválido: '+i.name);if(i.scope==='partida'&&i.visibility?.inventory===true)report.avisos.push('Conferir escopo: '+i.name+' é temporário, mas aparece na mochila permanente');if(i.useAction&&i.useAction!=='nenhuma'&&!i.gameplayEnabled)report.avisos.push('Item '+i.name+': comportamento cadastrado, mas não aprovado para execução Godot')}\n return report;\n};\nfunction drawGuide37(){const numbers={materials:state.items.filter(x=>x.category==='material').length,mobs:records37().npcs.filter(x=>x.kind==='inimigo'||x.kind==='chefe').length,loot:records37().loot.reduce((n,t)=>n+(t.entries||[]).length,0),recipes:state.recipes.length};\n byId('v37FlowProgress').textContent=`${numbers.materials} materiais • ${numbers.mobs} monstros • ${numbers.loot} drops • ${numbers.recipes} receitas`;\n}\nfor(const btn of document.querySelectorAll('[data-v37-open]'))btn.onclick=()=>{const pg=btn.dataset.v37Open;go37(pg);if(btn.dataset.v37Module){switchPage('v3');const sub=document.querySelector('[data-v3-module=\"'+btn.dataset.v37Module+'\"]');if(sub)sub.click()}};\n// Importar JSON antigo/salvo: atualizar menus quando necessário, sem obrigar dados oficiais.\nconst prevSwitch37=switchPage;switchPage=function(pg){prevSwitch37(pg);if(pg==='drops')drawDrops37();if(pg==='producao')drawGuide37();if(pg==='inventory')refreshExtraItem37();if(pg==='recipes')refreshRecipeAssistant37()};\nfunction refreshExtraItem37(){updateCombos37();if(editingItem){const i=state.items.find(x=>x.id===editingItem);if(i)fillMeta37(i)}}\n// Tornar a limpeza de projeto do 3.6 também zerar registros auxiliares criados no assistente.\nconst oldBlank37=byId('v36BlankProject').onclick;byId('v36BlankProject').onclick=function(e){oldBlank37.call(this,e);if(state.creatorSettings?.officialPackEnabled===false&&state.name==='Meu Jogo'){fillMeta37();drawGuide37();drawDrops37();updateCombos37()}};\n// Após importar projeto JSON, não exigir reload: re-renderiza as seleções no mesmo documento.\nbyId('projectFile').addEventListener('change',()=>setTimeout(()=>{updateCombos37();drawGuide37();drawDrops37();},250));\nupdateCombos37();fillMeta37();drawGuide37();drawDrops37();\nwindow.ApoenaCreator37={newIngredient:newIngredient37,addDrop:addDrop37,addHUD:addHud37,go:go37,version:'3.7',update:()=>{updateCombos37();drawGuide37();drawDrops37()}};\nconst entry37=location.hash.replace('#','');if(['producao','drops'].includes(entry37))go37(entry37);\nnotice37('v3.7: fluxo guiado, ingredientes/drops integrados, ficha HP/Aurium/Especial/XP e navegação simplificada.');\n})();\n\n</script><script>\n'use strict';\n/* v3.8: gerenciador de janelas que preserva todas as páginas, formulários e dados existentes.\n   O editor de loja é uma prévia de desenvolvedor: não executa compras reais no Godot. */\n(() => {\n const workspace=document.querySelector('main.main');\n if(!workspace||!document.querySelector('#page-layouts'))return;\n const labels={producao:'Guia de criação',drops:'Ingredientes e drops',layouts:'Editor de layouts',assets:'Biblioteca de imagens',icons:'Gerador de ícones',inventory:'Itens e economia',database:'Banco central',recipes:'Receitas e poções',cards:'Cards de heróis',images:'Editor de imagens',guide:'Ajuda e exportação',characters:'Personagens',creator:'Pacote Apoena',v3:'Editor avançado',v3links:'Relações do banco',flows:'Eventos e ações',simulator:'Simulador',validation:'Validador',animacoes:'Animações 3D',controles:'Controles do jogador','biblioteca-local':'Biblioteca 3D local','loja-moba':'Loja MOBA visual'};\n const key='apoena.creator.workspace.v38',registry=new Map(),order=[];\n let active='',z=20,grab=null;\n let stored={};try{stored=JSON.parse(localStorage.getItem(key)||'{}')}catch(e){}\n const clamp38=(v,min,max)=>Math.max(min,Math.min(max,v));\n const saveWorkspace=()=>{const v={};for(const [id,w]of registry){if(w.open)v[id]={open:true,minimized:w.minimized,maximized:w.maximized,x:w.x,y:w.y,w:w.w,h:w.h}};try{localStorage.setItem(key,JSON.stringify({windows:v,active}))}catch(e){}};\n const dock=document.createElement('div');dock.id='workspaceDock';dock.setAttribute('aria-label','Ferramentas abertas e minimizadas');\n dock.innerHTML='<strong class=\"ws-dock-caption\">Janelas</strong><button type=\"button\" id=\"wsAllTools\" title=\"Abrir escolha rápida de ferramentas\">☰ Ferramentas</button><button type=\"button\" id=\"wsTile\" title=\"Organizar duas janelas lado a lado\">▥ Lado a lado</button><button type=\"button\" id=\"wsMinAll\" title=\"Minimizar todas as janelas\">— Minimizar todas</button><span id=\"wsDockTabs\" class=\"row\" style=\"flex-wrap:nowrap;gap:5px\"></span>';\n workspace.classList.add('ws-area');workspace.after(dock);\n const dockTabs=dock.querySelector('#wsDockTabs');\n function surfaceRect(){return {w:Math.max(350,workspace.clientWidth),h:Math.max(230,workspace.clientHeight)}}\n function applyBounds(w){const p=w.el;if(!p)return;const r=surfaceRect(),small=matchMedia('(max-width:780px)').matches;\n  p.classList.toggle('ws-open',w.open);p.classList.toggle('ws-minimized',w.minimized);p.classList.toggle('ws-maximized',w.maximized||small);p.classList.toggle('ws-focused',active===w.id);\n  if(small||w.maximized){p.style.left='0px';p.style.top='0px';p.style.width='100%';p.style.height='100%'}else{\n   w.w=clamp38(w.w,Math.min(360,r.w),r.w);w.h=clamp38(w.h,Math.min(220,r.h),r.h);\n   w.x=clamp38(w.x,0,Math.max(0,r.w-w.w));w.y=clamp38(w.y,0,Math.max(0,r.h-w.h));\n   p.style.left=w.x+'px';p.style.top=w.y+'px';p.style.width=w.w+'px';p.style.height=w.h+'px';}\n  p.style.zIndex=String(w.z||20);\n }\n function focus(id){const w=registry.get(id);if(!w)return;active=id;w.z=++z;for(const v of registry.values())applyBounds(v);drawDock();saveWorkspace()}\n function newWin(page){const id=page.id.slice(5);if(registry.has(id))return registry.get(id);\n  const pos=registry.size,r=surfaceRect(),last=stored.windows?.[id]||{};\n  const w={id,el:page,open:false,minimized:false,maximized:true,x:18+(pos%5)*25,y:12+(pos%5)*19,w:Math.max(360,Math.min(1020,r.w-40)),h:Math.max(230,Math.min(680,r.h-36)),z:20,...last};\n  page.classList.add('ws-window');page.dataset.ws=id;\n  const title=document.createElement('header');title.className='ws-titlebar';title.innerHTML='<strong class=\"ws-name\"></strong><button class=\"ws-minimize\" type=\"button\" title=\"Minimizar sem perder o trabalho\" aria-label=\"Minimizar janela\">−</button><button class=\"ws-maximize\" type=\"button\" title=\"Maximizar ou restaurar tamanho\" aria-label=\"Maximizar ou restaurar\">▢</button><button class=\"ws-close\" type=\"button\" title=\"Fechar painel (mantém os dados na sessão)\" aria-label=\"Fechar esta ferramenta\">×</button>';\n  title.querySelector('.ws-name').textContent=labels[id]||id.replaceAll('-',' ').toUpperCase();\n  page.prepend(title);\n  const handle=document.createElement('div');handle.className='ws-grip';handle.title='Arraste para redimensionar janela';page.append(handle);\n  title.querySelector('.ws-minimize').onclick=e=>{e.stopPropagation();minimize(id)};\n  title.querySelector('.ws-close').onclick=e=>{e.stopPropagation();close(id)};\n  title.querySelector('.ws-maximize').onclick=e=>{e.stopPropagation();w.maximized=!w.maximized;applyBounds(w);focus(id)};\n  title.ondblclick=e=>{if(e.target.closest('button'))return;w.maximized=!w.maximized;applyBounds(w);focus(id)};\n  page.addEventListener('pointerdown',()=>{if(w.open&&!w.minimized&&active!==id)focus(id)},true);\n  title.addEventListener('pointerdown',e=>startMove(e,w,'move'));\n  handle.addEventListener('pointerdown',e=>startMove(e,w,'size'));\n  registry.set(id,w);return w;\n }\n function startMove(e,w,mode){if(e.button!==0||e.target.closest('button')||w.maximized||matchMedia('(max-width:780px)').matches)return;\n   e.preventDefault();e.stopPropagation();focus(w.id);grab={id:w.id,mode,startX:e.clientX,startY:e.clientY,x:w.x,y:w.y,w:w.w,h:w.h};\n   window.addEventListener('pointermove',onMove,true);window.addEventListener('pointerup',endMove,true);window.addEventListener('pointercancel',endMove,true)\n }\n function onMove(e){if(!grab)return;const w=registry.get(grab.id);if(!w)return;const dx=e.clientX-grab.startX,dy=e.clientY-grab.startY,r=surfaceRect();\n  if(grab.mode==='move'){w.x=clamp38(grab.x+dx,0,Math.max(0,r.w-w.w));w.y=clamp38(grab.y+dy,0,Math.max(0,r.h-w.h))}\n  else {w.w=clamp38(grab.w+dx,Math.min(360,r.w),r.w-w.x);w.h=clamp38(grab.h+dy,Math.min(220,r.h),r.h-w.y)}applyBounds(w);\n }\n function endMove(){grab=null;window.removeEventListener('pointermove',onMove,true);window.removeEventListener('pointerup',endMove,true);window.removeEventListener('pointercancel',endMove,true);saveWorkspace()}\n function drawDock(){dockTabs.replaceChildren();for(const id of order){const w=registry.get(id);if(!w?.open)continue;const b=document.createElement('button');b.type='button';b.className='ws-dock-item'+(active===id&&!w.minimized?' ws-dock-active':'')+(w.minimized?' ws-dock-minimized':'');b.textContent=(w.minimized?'▁ ':'▣ ')+(labels[id]||id);b.title=w.minimized?'Clique para restaurar':'Clique para minimizar ou trazer à frente';b.onclick=()=>{if(!w.minimized&&active===id)minimize(id);else open(id,true)};dockTabs.append(b)}\n }\n function open(id,keep=false){const page=document.getElementById('page-'+id);if(!page)return false;const w=newWin(page);if(!w.open){w.open=true;w.minimized=false;if(!order.includes(id))order.push(id)}\n   if(!keep&&w.minimized)w.minimized=false;else w.minimized=false;\n   applyBounds(w);focus(id);return true;\n }\n function minimize(id){const w=registry.get(id);if(!w||!w.open)return;w.minimized=true;if(active===id)active='';applyBounds(w);drawDock();saveWorkspace()}\n function close(id){const w=registry.get(id);if(!w)return;w.open=false;w.minimized=false;if(active===id)active='';applyBounds(w);drawDock();saveWorkspace()}\n function tile(){let visible=order.map(id=>registry.get(id)).filter(w=>w?.open&&!w.minimized);if(visible.length<2){const favorites=['layouts','drops','inventory'];for(const id of favorites){if(visible.length>=2)break;if(!visible.some(w=>w.id===id)&&document.getElementById('page-'+id)){switchPage(id);visible=order.map(id=>registry.get(id)).filter(w=>w?.open&&!w.minimized)}}}\n  visible=visible.slice(-2);const r=surfaceRect();for(let i=0;i<visible.length;i++){const w=visible[i];w.maximized=false;w.x=i===0?0:Math.floor(r.w/2)+3;w.y=0;w.w=Math.floor(r.w/2)-3;w.h=r.h;applyBounds(w)}if(visible[1])focus(visible[1].id);saveWorkspace()}\n dock.querySelector('#wsTile').onclick=tile;dock.querySelector('#wsMinAll').onclick=()=>{for(const w of registry.values())if(w.open){w.minimized=true;applyBounds(w)}active='';drawDock();saveWorkspace()};\n dock.querySelector('#wsAllTools').onclick=()=>{const adv=document.getElementById('v37AdvancedNav');adv.open=!adv.open;if(adv.open)adv.scrollIntoView({behavior:'smooth',block:'nearest'})};\n // Todas as rotas antigas passam a usar a mesma janela, sem desmontar DOM ou apagar campos.\n const previousSwitch38=switchPage;\n switchPage=function(pg){const id=String(pg||'');previousSwitch38(id);open(id);if(document.getElementById('v37AdvancedNav')?.open)document.getElementById('v37AdvancedNav').open=false;};\n document.querySelectorAll('nav.tabs button.tab').forEach(b=>{b.addEventListener('click',()=>{if(b.dataset.page)queueMicrotask(()=>open(b.dataset.page))})});\n document.querySelectorAll('main.main>.page').forEach(newWin);\n if(!registry.get('layouts')?.open){open('layouts')}else{for(const w of registry.values())if(w.open)applyBounds(w);const preferred=stored.active;if(preferred&&registry.get(preferred)?.open&&!registry.get(preferred)?.minimized)focus(preferred);else drawDock()}\n window.addEventListener('resize',()=>{for(const w of registry.values())if(w.open)applyBounds(w)});\n // Conexão da loja MOBA ao catálogo EXISTENTE: IDs e imagens não são duplicados.\n const shop=document.createElement('section');shop.id='page-loja-moba';shop.className='page';\n shop.innerHTML=`<div class=\"panel\"><h2>Loja MOBA — criador visual e teste</h2><p class=\"hint\">Crie dois layouts distintos usando o banco de itens atual. A prévia simula compras somente nesta tela: o jogo Godot não será alterado.</p>\n  <div class=\"ws-toolbar-moba\"><button id=\"wsShopStart\" class=\"primary\">＋ Tela da loja inicial</button><button id=\"wsShopDuring\">＋ Tela da loja durante a partida</button><button id=\"wsShopEdit\">▣ Abrir layouts para editar</button><button id=\"wsShopItems\">▦ Editar itens do catálogo</button></div>\n  <div class=\"ws-sim-head\"><label style=\"margin:0\">Fase</label><select id=\"wsShopPhase\" class=\"ws-compact\"><option value=\"inicio\">Início (movimento bloqueado)</option><option value=\"partida\">Durante a partida</option></select><label style=\"margin:0\">Ouro de teste</label><input id=\"wsShopGold\" class=\"ws-compact\" type=\"number\" min=\"0\" max=\"999999\" value=\"2000\"><label class=\"row\" style=\"margin:0\"><input id=\"wsShopInBase\" type=\"checkbox\" checked> Herói na base</label><button id=\"wsShopReset\">↶ Reiniciar teste</button></div>\n  <div class=\"ws-sim-grid\"><div class=\"panel\"><div class=\"toolbar\"><input id=\"wsShopSearch\" type=\"search\" placeholder=\"Pesquisar item...\" aria-label=\"Pesquisar item da loja\"><select id=\"wsShopCat\" class=\"ws-compact\"><option value=\"todos\">Todos</option><option value=\"arma\">Armas</option><option value=\"escudo\">Escudos</option><option value=\"armadura\">Armaduras</option><option value=\"acessorio\">Acessórios</option><option value=\"pocao\">Poções</option><option value=\"cristal\">Cristais</option></select></div><div id=\"wsShopProducts\" class=\"ws-sim-product-grid\"></div></div>\n  <aside class=\"panel\"><h3>Estado do jogador (simulação)</h3><div id=\"wsShopSummary\" class=\"notice\"></div><h3>Inventário temporário</h3><div id=\"wsShopBag\" class=\"flex-list\"></div><p id=\"wsShopFeedback\" class=\"ws-note\" role=\"status\">As compras feitas aqui não alteram o banco real.</p><button id=\"wsShopExportSample\">⬇ Exportar resultados de teste</button></aside></div>\n  <div class=\"ws-note\" style=\"margin-top:10px\">A loja consulta somente os itens MOBA cadastrados e publicados. Para compras reais no Godot ainda são necessárias validações de servidor/partida, autorização na base e conexão com o inventário temporário.</div></div>`;\n workspace.append(shop);newWin(shop);\n const get=id=>document.getElementById(id);\n const session={gold:2000,owned:[],phase:'inicio',inBase:true};\n function eligible(i){const scope=i.scope||'';return (['partida','partida_moba','moba'].includes(scope)||(!scope&&i.destino==='moba'))&&(i.visibility?.loja!==false)&&(i.visibility?.store!==false)&&(i.visibility?.disponivel!==false)&&(i.visibility?.available!==false)&&(i.publishState!=='rascunho')}\n function cost(i){return Math.max(0,Number(i.priceGold??i.price??0)||0)}\n function showShop(){const q=get('wsShopSearch').value.toLowerCase().trim(),cat=get('wsShopCat').value,list=state.items.filter(i=>eligible(i)&&(cat==='todos'||i.category===cat)&&(!q||(i.name+' '+i.id+' '+i.category).toLowerCase().includes(q)));\n  const parent=get('wsShopProducts');parent.replaceChildren();if(!list.length){const note=document.createElement('p');note.className='hint';note.textContent='Nenhum item MOBA disponível. Cadastre um item em Itens e economia e defina seu escopo como partida.';parent.append(note)}\n  for(const it of list){const b=document.createElement('div');b.className='ws-sim-product';const a=state.assets.find(x=>x.id===it.iconId);if(a?.data){const img=document.createElement('img');img.src=a.data;img.alt=it.name;b.append(img)}else{const sym=document.createElement('div');sym.style.cssText='font-size:35px;height:66px';sym.textContent='◇';b.append(sym)}const strong=document.createElement('strong');strong.textContent=it.name;const small=document.createElement('small');small.textContent=cost(it)+' ouro • '+(it.category||'item');const buy=document.createElement('button');buy.type='button';buy.textContent='Comprar';const validCurrency=!it.currency||['ouro','ouro_partida','moedas_partida'].includes(it.currency);const validCost=Number.isFinite(Number(it.priceGold??it.price??0))&&Number(it.priceGold??it.price??0)>=0;buy.disabled=!validCurrency||!validCost||cost(it)>session.gold||session.phase==='partida'&&!session.inBase;buy.title=!validCurrency?'Moeda de fora da partida: não confundir diamantes com ouro MOBA':!validCost?'Preço inválido':session.phase==='partida'&&!session.inBase?'Compras disponíveis apenas na base':'';if(!validCurrency)small.textContent='MOEDA EXTERNA • Não vendável nesta partida';buy.onclick=()=>{if(!validCurrency||!validCost){feedback('Este item não usa moeda de partida válida.');return}if(session.phase==='partida'&&!session.inBase){feedback('Compra indisponível: o herói está fora da base.');return}if(session.gold<cost(it)){feedback('Ouro insuficiente.');return}if(session.owned.length>=6){feedback('Inventário de teste cheio (6 espaços).');return}session.gold-=cost(it);session.owned.push(it.id);feedback('Compra simulada: '+it.name+'.');showShop()};b.append(strong,small,buy);parent.append(b)}\n  get('wsShopSummary').textContent='Fase: '+(session.phase==='inicio'?'pré-partida':'partida')+' • Saldo: '+session.gold+' ouro • Itens: '+session.owned.length+'/6 • '+(session.inBase?'Na base':'Fora da base');const bag=get('wsShopBag');bag.replaceChildren();for(const id of session.owned){const item=state.items.find(x=>x.id===id);const div=document.createElement('div');div.className='row';const t=document.createElement('span');t.textContent=item?.name||'(item indisponível: '+id+')';t.style.flex='1';const remove=document.createElement('button');remove.textContent='Vender (70%)';remove.onclick=()=>{session.owned.splice(session.owned.indexOf(id),1);session.gold+=Math.floor(cost(item||{price:0})*.7);feedback('Venda simulada.');showShop()};div.append(t,remove);bag.append(div)}\n }\n function feedback(v){get('wsShopFeedback').textContent=v}\n get('wsShopPhase').onchange=e=>{session.phase=e.target.value;showShop()};get('wsShopInBase').onchange=e=>{session.inBase=e.target.checked;showShop()};get('wsShopGold').onchange=e=>{session.gold=clamp38(Math.floor(Number(e.target.value)||0),0,999999);session.owned=[];showShop()};get('wsShopSearch').oninput=showShop;get('wsShopCat').onchange=showShop;\n get('wsShopReset').onclick=()=>{session.gold=2000;session.owned=[];session.phase='inicio';session.inBase=true;get('wsShopPhase').value='inicio';get('wsShopInBase').checked=true;get('wsShopGold').value='2000';feedback('Simulador reiniciado.');showShop()};\n get('wsShopExportSample').onclick=()=>jsonDownload({type:'apoena.shop.preview.v1',mock:true,initialGold:2000,phase:session.phase,goldRemaining:session.gold,owned:session.owned},'TESTE_LOJA_MOBA_NAO_AFETA_JOGO.json');\n function shopScreen(which){const id=which==='inicio'?'loja_moba_inicio':'loja_moba_partida',name=which==='inicio'?'LOJA • ANTES DA PARTIDA':'LOJA • DURANTE A PARTIDA';\n  if(state.screens[id]){current=id;selected=null;multiSelected.clear();switchPage('layouts');feedback('Tela existente aberta sem substituir seus ajustes.');return}\n  const s=newScreen(id,1280,720);s.workspace='loja';s.background.color='#0e1e2b';s.shop_mode=which;s.shop_scope='partida';s.layout_version=1;\n  const group='window_loja_'+which;\n  const add=(type,name,x,y,w,h,text,props={})=>{const e=newElement(type,name);Object.assign(e,{x,y,w,h,text,z_index:s.elements.length,owner_window:group,...props});s.elements.push(e);return e};\n  add('panel','Janela loja MOBA',82,45,1116,625,'',{window_id:group,background:'#162f42',border_color:'#caaf7d'});\n  add('label','Título',125,64,690,58,name,{font_size:28,text_align:'left'});\n  add('button','Fechar loja local',1065,65,87,61,'✕',{action:'fechar_janela_local',owner_window:group});\n  add('panel','Busca',124,141,660,50,'PESQUISAR EQUIPAMENTO',{component_type:'search_box',source_scope:'partida',background:'#233d4f'});\n  add('label','Categorias',124,198,680,46,'TODOS  •  ARMAS  •  DEFESA  •  MAGIA  •  CONSUMÍVEIS',{font_size:17,text_align:'left',component_type:'shop_categories',source_scope:'partida'});\n  add('panel','Grade de produtos',122,253,690,341,'',{component_type:'shop_grid',source_scope:'partida',background:'#1b3345'});\n  const candidate=state.items.filter(eligible).slice(0,12);for(let i=0;i<12;i++){const col=i%4,row=Math.floor(i/4),it=candidate[i];const e=add(it?'item':'panel','Produto '+(i+1),148+col*164,268+row*104,88,85,'',{component_type:'shop_item_slot',source_scope:'partida',slot_index:i,background:'#244357',itemId:it?.id||'',category_id:it?.category||''});}\n  add('panel','Descrição de item',843,166,300,250,'SELECIONE UM ITEM',{component_type:'shop_item_details',source_scope:'partida',background:'#213a48',font_size:20});\n  add('label','Saldo MOBA',849,428,284,44,'OURO • PARTIDA',{font_size:18,component_type:'shop_currency',binding_metric:'match_gold'});\n  add('button','Comprar selecionado',844,483,290,66,'COMPRAR',{action:'comprar_item_partida',component_type:'shop_buy',source_scope:'partida',font_size:22});\n  add('label','Aviso sobre compra',841,559,302,34,which==='inicio'?'MOVIMENTO BLOQUEADO • FASE INICIAL':'COMPRAR SOMENTE NA BASE',{font_size:12});\n  state.screens[id]=s;current=id;selected=null;multiSelected.clear();switchPage('layouts');status('Tela '+name+' criada e vinculada ao banco de itens. Personalize livremente e salve o projeto.');feedback('Modelo criado: '+name+'. Edição visual disponível no editor de layouts.');\n }\n get('wsShopStart').onclick=()=>shopScreen('inicio');get('wsShopDuring').onclick=()=>shopScreen('partida');get('wsShopEdit').onclick=()=>switchPage('layouts');get('wsShopItems').onclick=()=>switchPage('inventory');\n // Ferramenta sempre disponível no menu de trabalho; sem aumentar a barra horizontal.\n const nav=document.getElementById('v37Nav');const newGroup=document.createElement('details');newGroup.className='v37-group';newGroup.innerHTML='<summary>🛒 Loja MOBA</summary><div class=\"v37-menu\"><button type=\"button\" id=\"wsShopOpenNav\">Editor e simulador da loja</button><button type=\"button\" id=\"wsShopOpenStart\">Layout inicial</button><button type=\"button\" id=\"wsShopOpenDuring\">Layout durante partida</button></div>';nav.append(newGroup);\n get('wsShopOpenNav').onclick=()=>{switchPage('loja-moba');newGroup.open=false};get('wsShopOpenStart').onclick=()=>{shopScreen('inicio');newGroup.open=false};get('wsShopOpenDuring').onclick=()=>{shopScreen('partida');newGroup.open=false};\n const quick=document.getElementById('v37QuickJump');if(quick)quick.add(new Option('🛒 Loja MOBA — editor e simulador','loja-moba'));\n // Visão inicial preservada; prévia do catálogo atual não faz alterações nos itens.\n const initialShopHash=location.hash.replace('#','');if(initialShopHash==='loja-moba')switchPage('loja-moba');\n showShop();saveWorkspace();status('v3.8: janelas minimizáveis, navegação persistente e loja MOBA em teste visual. Salve seu JSON ao concluir o trabalho.');\n window.ApoenaWorkspace38={open,close,minimize,tile,registry,shopScreen,refreshShop:showShop,version:'3.8'};\n})();\n\n</script><script id=\"apoena-v39-script\">\n/* APOENA GAME CREATOR v3.9 — Extensão in-place do editor da v3.8.\n * O estado central, schemas, geradores, biblioteca e exportadores legados permanecem.\n * Nenhum código remoto. Fonte incluída para manutenção.\n */\n(function(){\n'use strict';\nconst by=id=>document.getElementById(id);\nconst html=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst num=(v,d=0)=>Number.isFinite(Number(v))?Number(v):d;\nconst bound=(v,min,max)=>Math.max(min,Math.min(max,num(v)));\nconst notify=s=>{if(typeof status==='function')status(s);};\nconst currentEl=()=>screen().elements.find(e=>e.id===selected);\nconst isLocked=e=>!!e?.locked;\nconst canChange=e=>!!e&&!isLocked(e);\nconst mark=()=>{if(typeof v3AutoSchedule==='function')v3AutoSchedule()};\nfunction normalize(){const s=screen();if(!s.resolution)s.resolution={width:1280,height:720};if(!s.background)s.background={color:'#152d3e'};s.elements=s.elements||[];for(const e of s.elements){if(!e.id)e.id=uid();e.opacity=bound(e.opacity??100,0,100);e.rotation=bound(e.rotation??0,-360,360);e.scale_x=bound(e.scale_x??1,.1,4);e.scale_y=bound(e.scale_y??1,.1,4);e.anchor_x=e.anchor_x||'left';e.anchor_y=e.anchor_y||'top';e.group_id=e.group_id||'';e.binding_path=e.binding_path||'';e.corner_radius=bound(e.corner_radius??(e.type==='button'?11:5),0,100);e.z_index=num(e.z_index,0)}}\nconst ui=document.createElement('section');ui.id='v39Shell';ui.className='v39-shell';\nui.innerHTML=`<div class=\"v39-head\"><div><span class=\"v39-edition\">EDITOR LIVRE • V3.9</span><strong>Composição visual de páginas</strong></div><div class=\"v39-head-actions\"><button id=\"v39Preview\" type=\"button\">▶ Testar interface</button><button id=\"v39Fit\" type=\"button\">Encaixar</button><label class=\"v39-zoom-label\">Zoom <input id=\"v39Zoom\" type=\"range\" min=\"40\" max=\"250\" step=\"10\" value=\"100\"><output id=\"v39ZoomOutput\">100%</output></label></div></div>\n<div class=\"v39-toolbar\">\n <label>Formato <select id=\"v39Preset\"><option value=\"custom\">Personalizado</option><option value=\"1280x720\">PC • 1280 × 720</option><option value=\"1920x1080\">PC • 1920 × 1080</option><option value=\"1080x1920\">Celular • 1080 × 1920</option><option value=\"720x1280\">Celular • 720 × 1280</option><option value=\"800x800\">Quadrado • 800 × 800</option></select></label>\n <label>L <input type=\"number\" id=\"v39W\" min=\"320\" max=\"8192\" step=\"1\"></label><label>A <input type=\"number\" id=\"v39H\" min=\"180\" max=\"8192\" step=\"1\"></label>\n <label>Redimensionar <select id=\"v39ResizeMethod\"><option value=\"keep\">Manter as posições</option><option value=\"scale\">Ajustar proporcionalmente</option><option value=\"anchors\">Usar âncoras</option></select></label><button type=\"button\" id=\"v39ApplyPage\">Aplicar resolução</button>\n <span class=\"v39-divider\"></span><button id=\"v39AlignLeft\" title=\"Alinhar à esquerda\">⇤</button><button id=\"v39AlignCenter\" title=\"Centralizar horizontalmente\">↔</button><button id=\"v39AlignRight\" title=\"Alinhar à direita\">⇥</button><button id=\"v39AlignTop\" title=\"Alinhar ao topo\">⇡</button><button id=\"v39AlignMiddle\" title=\"Centralizar verticalmente\">↕</button><button id=\"v39AlignBottom\" title=\"Alinhar embaixo\">⇣</button><button id=\"v39SpaceH\" title=\"Distribuir horizontalmente\">H ⇄</button><button id=\"v39SpaceV\" title=\"Distribuir verticalmente\">V ⇅</button>\n <span class=\"v39-divider\"></span><button id=\"v39Group\" title=\"Agrupar seleção • Ctrl+G\">Agrupar</button><button id=\"v39Ungroup\" title=\"Desagrupar • Ctrl+Shift+G\">Desagrupar</button><button id=\"v39Front\">Ao topo</button><button id=\"v39Back\">Ao fundo</button>\n</div>`;\nconst page=by('page-layouts');const toolbar=page?.querySelector('.toolbar');if(!page||!toolbar)return;\npage.insertBefore(ui,toolbar);\nconst palette=page.querySelector('.layout-side');\nconst paletteExtra=document.createElement('div');paletteExtra.className='v39-palette';paletteExtra.innerHTML=`<h3>Composição livre v3.9</h3><p class=\"hint\">Todas as telas usam este mesmo editor. Os geradores existentes fornecem os dados.</p>\n<div class=\"v39-tool-grid\"><button data-v39-add=\"building\">🏛 Construção clicável</button><button data-v39-add=\"sign\">▰ Placa interativa</button><button data-v39-add=\"slot\">▣ Slot de inventário</button><button data-v39-add=\"grid\">▦ Grade de itens</button><button data-v39-add=\"hud\">▰ Barra de status</button><button data-v39-add=\"portrait\">◉ Retrato</button><button data-v39-add=\"view3d\">⬡ Visualizador 3D</button><button data-v39-add=\"panel\">▤ Caixa transparente</button></div>`;\npalette.insertBefore(paletteExtra,palette.querySelector('h3.border-top')||palette.lastChild);\nconst layerArea=by('layerList');const layerHeader=document.createElement('div');layerHeader.className='v39-layer-header';layerHeader.innerHTML='<span>CAMADAS • arraste para ordenar</span><button id=\"v39SelectAll\" type=\"button\">Todas</button>';layerArea.before(layerHeader);\nconst inspector=by('inspector');\nlet zoomPercent=100, fitScale=1, previewScreen='', previewHidden=new Set();\n// A v3.8 calcula encaixe automático. Multiplicador permite zoom livre sem alterar a resolução do documento.\nconst baseComputeScale=computeScale;\ncomputeScale=function(){baseComputeScale();fitScale=stageScale;const sc=bound(fitScale*zoomPercent/100,.05,3.5),r=screen().resolution;stageScale=sc;by('stageFrame').style.width=Math.round(r.width*sc)+'px';by('stageFrame').style.height=Math.round(r.height*sc)+'px';by('stage').style.transform='scale('+sc+')';by('zoomText').textContent=Math.round(sc*100)+'%';};\nfunction properties(){normalize();const e=currentEl();if(!e||multiSelected.size>1)return;const box=by('inspector');const part=document.createElement('div');part.className='v39-inspector';part.id='v39Properties';\n const chooses=(arr,current)=>arr.map(([v,t])=>`<option value=\"${html(v)}\" ${current===v?'selected':''}>${html(t)}</option>`).join('');\n part.innerHTML=`<h3>Transformação e comportamento</h3>\n <label>Opacidade <span id=\"v39OpacityValue\">${e.opacity}%</span></label><input id=\"v39Opacity\" type=\"range\" min=\"0\" max=\"100\" value=\"${e.opacity}\">\n <div class=\"two\"><div><label>Rotação (°)</label><input id=\"v39Rotation\" type=\"number\" min=\"-360\" max=\"360\" value=\"${e.rotation}\"></div><div><label>Arredondamento (px)</label><input id=\"v39Corner\" type=\"number\" min=\"0\" max=\"100\" value=\"${e.corner_radius}\"></div><div><label>Escala X</label><input id=\"v39ScaleX\" type=\"number\" min=\"0.1\" max=\"4\" step=\"0.1\" value=\"${e.scale_x}\"></div><div><label>Escala Y</label><input id=\"v39ScaleY\" type=\"number\" min=\"0.1\" max=\"4\" step=\"0.1\" value=\"${e.scale_y}\"></div></div>\n <div class=\"two\"><div><label>Âncora horizontal</label><select id=\"v39AnchorX\">${chooses([['left','Esquerda'],['center','Centro'],['right','Direita'],['stretch','Esticar']],e.anchor_x)}</select></div><div><label>Âncora vertical</label><select id=\"v39AnchorY\">${chooses([['top','Topo'],['center','Centro'],['bottom','Inferior'],['stretch','Esticar']],e.anchor_y)}</select></div></div>\n <label>Grupo (ID)</label><input id=\"v39GroupId\" type=\"text\" value=\"${html(e.group_id||'')}\" placeholder=\"Sem grupo\">\n <label>Vinculação de dados (caminho declarativo)</label><input id=\"v39Binding\" value=\"${html(e.binding_path||'')}\" placeholder=\"Ex.: jogador.hp / inventario.itens\">\n ${['building','sign','portrait','view3d'].includes(e.component_type)?`<label>Imagem / textura do componente</label><select id=\"v39ComponentAsset\"><option value=\"\">Sem imagem</option>${state.assets.map(a=>`<option value=\"${html(a.id)}\" ${e.assetId===a.id?'selected':''}>${html(a.name)}</option>`).join('')}</select><label>Enviar imagem do computador</label><input type=\"file\" id=\"v39ComponentUpload\" accept=\"image/png,image/jpeg,image/webp\">`:''}\n <label>Comportamento ao clicar</label><select id=\"v39Behavior\">${chooses([['','Nenhum / herdado'],['navegar','Abrir outra tela do projeto'],['acao','Enviar ação ao Godot'],['fechar','Fechar janela vinculada']],e.click_behavior||'')}</select>\n <label>Tela de destino</label><select id=\"v39TargetScreen\"><option value=\"\">Escolha uma tela…</option>${Object.keys(state.screens).map(n=>`<option value=\"${html(n)}\" ${e.target_screen===n?'selected':''}>${html(n)}</option>`).join('')}</select>\n ${['building','sign','grid','slot','hud','portrait','view3d'].includes(e.component_type)?`<label>Componente: ${html(e.component_type)}</label>`:''}\n ${e.component_type==='grid'?`<div class=\"two\"><div><label>Colunas</label><input id=\"v39Cols\" type=\"number\" min=\"1\" max=\"15\" value=\"${bound(e.columns??5,1,15)}\"></div><div><label>Linhas</label><input id=\"v39Rows\" type=\"number\" min=\"1\" max=\"15\" value=\"${bound(e.rows??3,1,15)}\"></div></div><label>Catálogo (ID / grupo)</label><input id=\"v39Catalog\" value=\"${html(e.catalog_source||'itens')}\">`:''}\n ${e.component_type==='hud'?`<label>Progresso visual de prévia (%)</label><input id=\"v39Progress\" type=\"range\" min=\"0\" max=\"100\" value=\"${bound(e.preview_percent??70,0,100)}\"><label>Cor da barra</label><input id=\"v39BarColor\" type=\"color\" value=\"${/^#[a-f\\d]{6}$/i.test(e.bar_color||'')?e.bar_color:'#2ca6cf'}\">`:''}\n <p class=\"hint\">IDs, propriedades, âncoras e vínculos são gravados no JSON. Um comportamento jogável depende do executor correspondente no Godot.</p>`;\n box.append(part);\n function wire(id,key,parse=x=>x,continuous=false){const input=by(id);if(!input)return;let initial;\n input.addEventListener('focus',()=>{initial=e[key]});\n if(continuous)input.addEventListener('input',()=>{if(!canChange(e))return;e[key]=parse(input.value);if(id==='v39Opacity')by('v39OpacityValue').textContent=e.opacity+'%';renderStage()});\n input.addEventListener('change',()=>{if(!canChange(e)){renderInspector();return}let old=initial;if(continuous){const changed=e[key];e[key]=old??changed;history();e[key]=parse(input.value)}else{history();e[key]=parse(input.value)}renderLayout();mark()});}\n wire('v39Opacity','opacity',v=>bound(v,0,100),true);wire('v39Rotation','rotation',v=>bound(v,-360,360));wire('v39Corner','corner_radius',v=>bound(v,0,100));wire('v39ScaleX','scale_x',v=>bound(v,.1,4));wire('v39ScaleY','scale_y',v=>bound(v,.1,4));\n const componentAsset=by('v39ComponentAsset');if(componentAsset)componentAsset.onchange=ev=>{history();e.assetId=ev.target.value;renderLayout();mark()};\n const upload=by('v39ComponentUpload');if(upload)upload.onchange=async ev=>{const f=ev.target.files?.[0];if(!f)return;try{const image=await fileToPNG(f);history();const a=makeAsset(f.name,image,'upload','nao_classificado');e.assetId=a.id;renderAssets();renderLayout();mark();notify('Imagem vinculada ao componente e à biblioteca.')}catch(err){alert('Não foi possível importar: '+err.message)}};\n wire('v39AnchorX','anchor_x');wire('v39AnchorY','anchor_y');wire('v39GroupId','group_id');wire('v39Binding','binding_path');wire('v39Behavior','click_behavior');wire('v39TargetScreen','target_screen');\n wire('v39Cols','columns',v=>bound(Math.round(num(v,5)),1,15));wire('v39Rows','rows',v=>bound(Math.round(num(v,3)),1,15));wire('v39Catalog','catalog_source');wire('v39Progress','preview_percent',v=>bound(v,0,100),true);wire('v39BarColor','bar_color');\n}\nconst previousInspector=renderInspector;\nrenderInspector=function(){previousInspector();properties()};\nconst previousStage=renderStage;\nrenderStage=function(){normalize();previousStage();const r=by('stage');for(const n of r.querySelectorAll('.art')){const e=screen().elements.find(x=>x.id===n.dataset.id);if(!e)continue;\n n.style.opacity=String(e.opacity/100);n.style.transform=`rotate(${e.rotation}deg) scale(${e.scale_x},${e.scale_y})`;n.style.transformOrigin='center center';n.style.borderRadius=e.corner_radius+'px';n.dataset.group=e.group_id||'';\n if(e.locked)n.classList.add('v39-lock');if(e.group_id)n.title=(n.title?n.title+' • ':'')+'Grupo: '+e.group_id;\n if(e.component_type==='building'||e.component_type==='sign'){n.classList.add('v39-building');n.title=(e.name||'Construção')+' • '+(e.action||e.target_screen||'Configure uma ação');if(e.assetId){const a=asset(e.assetId);if(a&&!n.querySelector('img.v39-component-image')){const img=document.createElement('img');img.className='v39-component-image';img.src=a.data;img.alt=e.name;img.draggable=false;n.prepend(img)}}}\n if(e.component_type==='grid') {n.classList.add('v39-grid-component');n.style.setProperty('--v39-columns',String(bound(e.columns??5,1,15)));n.style.setProperty('--v39-rows',String(bound(e.rows??3,1,15)));const area=document.createElement('div');area.className='v39-grid-cells';for(let k=0;k<Math.min(100,bound(e.columns??5,1,15)*bound(e.rows??3,1,15));k++){const cell=document.createElement('i');area.append(cell)}n.append(area)}\n if(e.component_type==='slot'){n.classList.add('v39-slot-component');const tag=document.createElement('small');tag.textContent='SLOT';n.append(tag)}\n if(e.component_type==='hud'){n.classList.add('v39-hud-component');const bar=document.createElement('div');bar.className='v39-hud-track';const fill=document.createElement('i');fill.style.width=bound(e.preview_percent??70,0,100)+'%';fill.style.background=e.bar_color||'#2ca6cf';bar.append(fill);n.prepend(bar)}\n if(e.component_type==='view3d'){n.classList.add('v39-viewport-component');n.title='Área 3D declarativa; modelo e animações renderizados no Godot';}\n if(e.component_type==='portrait')n.classList.add('v39-portrait-component');\n if(e.click_behavior==='navegar'&&e.target_screen)n.title=(n.title||'')+' → '+e.target_screen;\n }\n};\nconst previousLayers=renderLayers;\nrenderLayers=function(){normalize();const list=by('layerList');list.replaceChildren();const all=[...screen().elements].sort((a,b)=>num(b.z_index)-num(a.z_index));for(const e of all){const b=document.createElement('div');b.className='v39-layer'+(multiSelected.has(e.id)||selected===e.id?' v39-active':'');b.draggable=true;b.dataset.id=e.id;\n const name=document.createElement('button');name.type='button';name.className='v39-layer-select';name.title=e.name+' • '+e.type+' • '+e.id;name.textContent=(e.group_id?'◈ ':'')+e.name+'  ·  '+e.type;name.onclick=ev=>{selectLayoutElement(e.id,ev.ctrlKey||ev.shiftKey||ev.metaKey);renderLayout()};\n const eye=document.createElement('button');eye.type='button';eye.className='v39-layer-icon';eye.textContent=e.visible===false?'◌':'◉';eye.title=e.visible===false?'Mostrar camada':'Ocultar camada';eye.setAttribute('aria-label',eye.title);eye.onclick=()=>{history();e.visible=e.visible===false;renderLayout();mark()};\n const lock=document.createElement('button');lock.type='button';lock.className='v39-layer-icon';lock.textContent=e.locked?'🔒':'♢';lock.title=e.locked?'Desbloquear':'Bloquear';lock.setAttribute('aria-label',lock.title);lock.onclick=()=>{history();e.locked=!e.locked;renderLayout();mark()};\n b.append(eye,lock,name);b.ondragstart=ev=>{ev.dataTransfer.setData('text/plain',e.id);ev.dataTransfer.effectAllowed='move';b.classList.add('v39-moving')};b.ondragend=()=>b.classList.remove('v39-moving');b.ondragover=ev=>{ev.preventDefault();ev.dataTransfer.dropEffect='move'};b.ondrop=ev=>{ev.preventDefault();const source=ev.dataTransfer.getData('text/plain');if(!source||source===e.id)return;reorder(source,e.id)};list.append(b)}};\nfunction reorder(id,target){const s=screen(),rows=[...s.elements].sort((a,b)=>num(a.z_index)-num(b.z_index));const from=rows.findIndex(x=>x.id===id),to=rows.findIndex(x=>x.id===target);if(from<0||to<0)return;history();const [moving]=rows.splice(from,1);rows.splice(to,0,moving);rows.forEach((v,i)=>v.z_index=i);renderLayout();mark()}\nconst previousLayout=renderLayout;\nrenderLayout=function(){normalize();previousLayout();by('v39W').value=screen().resolution.width;by('v39H').value=screen().resolution.height;const sz=screen().resolution.width+'x'+screen().resolution.height;by('v39Preset').value=[...by('v39Preset').options].some(o=>o.value===sz)?sz:'custom';};\nfunction updateResolution(width,height,method){width=Math.round(bound(width,320,8192));height=Math.round(bound(height,180,8192));const l=screen(),oldW=l.resolution.width,oldH=l.resolution.height;if(width===oldW&&height===oldH)return;history();const dx=width-oldW,dy=height-oldH,sx=width/oldW,sy=height/oldH;for(const e of l.elements){if(method==='scale'){e.x=Math.round(e.x*sx);e.y=Math.round(e.y*sy);e.w=Math.max(16,Math.round(e.w*sx));e.h=Math.max(16,Math.round(e.h*sy))}else if(method==='anchors'){\n if(e.anchor_x==='right')e.x+=dx;else if(e.anchor_x==='center')e.x+=dx/2;else if(e.anchor_x==='stretch')e.w+=dx;\n if(e.anchor_y==='bottom')e.y+=dy;else if(e.anchor_y==='center')e.y+=dy/2;else if(e.anchor_y==='stretch')e.h+=dy;\n e.x=Math.round(e.x);e.y=Math.round(e.y);e.w=Math.max(16,Math.round(e.w));e.h=Math.max(16,Math.round(e.h));\n }}l.resolution={width,height};renderLayout();mark();notify('Resolução alterada para '+width+' × '+height+'.');}\nby('v39Preset').onchange=ev=>{if(ev.target.value==='custom')return;const [w,h]=ev.target.value.split('x').map(Number);by('v39W').value=w;by('v39H').value=h};\nby('v39ApplyPage').onclick=()=>updateResolution(num(by('v39W').value),num(by('v39H').value),by('v39ResizeMethod').value);\nby('v39Zoom').oninput=ev=>{zoomPercent=bound(ev.target.value,40,250);by('v39ZoomOutput').textContent=zoomPercent+'%';computeScale()};\nby('v39Fit').onclick=()=>{zoomPercent=100;by('v39Zoom').value=100;by('v39ZoomOutput').textContent='100%';computeScale()};\nby('stageScroll').addEventListener('wheel',ev=>{if(!ev.ctrlKey)return;ev.preventDefault();zoomPercent=bound(zoomPercent+(ev.deltaY<0?10:-10),40,250);by('v39Zoom').value=zoomPercent;by('v39ZoomOutput').textContent=zoomPercent+'%';computeScale()},{passive:false});\nconst ADD={\n building:{type:'button',name:'Construção interativa',w:185,h:155,text:'LOCAL',component_type:'building',background:'#00000000',border_color:'#00000000',hide_button_frame:true,click_behavior:'navegar'},\n sign:{type:'button',name:'Placa interativa',w:210,h:72,text:'ENTRAR',component_type:'sign',background:'#355245',border_color:'#8ac6a1',click_behavior:'navegar'},\n slot:{type:'panel',name:'Slot de inventário',w:95,h:95,text:'',component_type:'slot',source_scope:'permanente',binding_path:'inventario.itens'},\n grid:{type:'panel',name:'Grade de itens',w:540,h:340,text:'',component_type:'grid',columns:5,rows:3,catalog_source:'itens',source_scope:'permanente',binding_path:'inventario.itens'},\n hud:{type:'panel',name:'Barra de status',w:300,h:47,text:'HP',component_type:'hud',bar_color:'#35a9c1',preview_percent:70,binding_path:'jogador.hp'},\n portrait:{type:'image',name:'Retrato do herói',w:135,h:135,component_type:'portrait',binding_path:'jogador.retrato'},\n view3d:{type:'character_preview',name:'Visualizador 3D',w:330,h:360,text:'PERSONAGEM 3D',component_type:'view3d',preview3d:true,preview_action:'idle',binding_path:'jogador.modelo_3d'},\n panel:{type:'panel',name:'Painel personalizável',w:330,h:225,text:'',background:'#22394999',border_color:'#87a8b2'}\n};\nfunction addComponent(kind){const spec=ADD[kind];if(!spec)return;history();const e=newElement(spec.type,spec.name);Object.assign(e,spec,{id:uid(),x:Math.max(8,Math.round((screen().resolution.width-spec.w)/2)),y:Math.max(8,Math.round((screen().resolution.height-spec.h)/2)),z_index:Math.max(0,...screen().elements.map(x=>num(x.z_index,0)))+1});screen().elements.push(e);selected=e.id;multiSelected=new Set([e.id]);renderLayout();mark();}\npaletteExtra.querySelectorAll('[data-v39-add]').forEach(b=>b.onclick=()=>addComponent(b.dataset.v39Add));\nfunction targetElements(){return screen().elements.filter(e=>(multiSelected.size?multiSelected.has(e.id):e.id===selected)&&!e.locked)}\nfunction align(kind){const list=targetElements();if(!list.length)return;history();const r=screen().resolution;\n if(kind==='spaceH'||kind==='spaceV'){if(list.length<3){notify('Selecione ao menos 3 elementos para distribuir.');return}const x=kind==='spaceH',key=x?'x':'y',size=x?'w':'h';const sorted=[...list].sort((a,b)=>a[key]-b[key]);const a=sorted[0][key],max=sorted.at(-1)[key]+sorted.at(-1)[size],total=sorted.reduce((n,e)=>n+e[size],0),gap=(max-a-total)/(sorted.length-1);let start=a;for(const e of sorted){e[key]=Math.round(start);start+=e[size]+gap}}\n else{const minX=Math.min(...list.map(e=>e.x)),minY=Math.min(...list.map(e=>e.y)),maxX=Math.max(...list.map(e=>e.x+e.w)),maxY=Math.max(...list.map(e=>e.y+e.h));for(const e of list){if(kind==='left')e.x=list.length===1?0:minX;if(kind==='right')e.x=list.length===1?r.width-e.w:maxX-e.w;if(kind==='center')e.x=list.length===1?Math.round((r.width-e.w)/2):Math.round((minX+maxX-e.w)/2);if(kind==='top')e.y=list.length===1?0:minY;if(kind==='bottom')e.y=list.length===1?r.height-e.h:maxY-e.h;if(kind==='middle')e.y=list.length===1?Math.round((r.height-e.h)/2):Math.round((minY+maxY-e.h)/2)}}renderLayout();mark()}\nfor(const [id,cmd] of Object.entries({v39AlignLeft:'left',v39AlignCenter:'center',v39AlignRight:'right',v39AlignTop:'top',v39AlignMiddle:'middle',v39AlignBottom:'bottom',v39SpaceH:'spaceH',v39SpaceV:'spaceV'}))by(id).onclick=()=>align(cmd);\nfunction group(on){const es=targetElements();if(!es.length)return;if(on&&es.length<2){notify('Selecione dois ou mais elementos com Ctrl/Shift.');return}history();const gid=on?'grupo_'+uid().slice(-8):'';for(const e of es)e.group_id=gid;renderLayout();mark()}\nby('v39Group').onclick=()=>group(true);by('v39Ungroup').onclick=()=>group(false);\nby('v39Front').onclick=()=>{const e=currentEl();if(!canChange(e))return;history();e.z_index=Math.max(0,...screen().elements.map(x=>num(x.z_index)))+1;renderLayout();mark()};\nby('v39Back').onclick=()=>{const e=currentEl();if(!canChange(e))return;history();e.z_index=Math.min(0,...screen().elements.map(x=>num(x.z_index)))-1;renderLayout();mark()};\nby('v39SelectAll').onclick=()=>{multiSelected=new Set(screen().elements.filter(e=>e.visible!==false&&!e.locked).map(e=>e.id));selected=[...multiSelected].at(-1)||null;renderLayout()};\n// Selecionar grupo por um toque; não deixar camadas bloqueadas serem arrastadas.\nconst previousStartPointer=startPointer;\nstartPointer=function(ev){const e=screen().elements.find(x=>x.id===ev.currentTarget.dataset.id);if(isLocked(e)){ev.preventDefault();ev.stopPropagation();selected=e.id;multiSelected=new Set([e.id]);renderLayout();return}if(!ev.ctrlKey&&!ev.shiftKey&&!ev.metaKey&&e?.group_id){const matches=screen().elements.filter(v=>v.group_id===e.group_id&&!v.locked);if(matches.length>1){multiSelected=new Set(matches.map(v=>v.id));selected=e.id}}previousStartPointer(ev)};\n// O manipulador original tenta redimensionar/mover todos os selecionados. Seu histórico e snap continuam ativos.\nconst previousDelete=delElement;delElement=function(){if(!selected)return;const locked=screen().elements.filter(e=>multiSelected.has(e.id)&&e.locked);if(locked.length){notify('Desbloqueie as camadas antes de excluí-las.');return}previousDelete()};\nwindow.addEventListener('keydown',ev=>{if(page!=='layouts'||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;const mod=ev.ctrlKey||ev.metaKey;if(mod&&ev.key.toLowerCase()==='g'){ev.preventDefault();ev.stopImmediatePropagation();group(!ev.shiftKey);return}if(['Delete','Backspace','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(ev.key)&&targetElements().length===0&&selected){ev.preventDefault();ev.stopImmediatePropagation();notify('Camada bloqueada: desbloqueie para alterar.')}},true);\nconst beforeNorm=normScreenForGodot;\nnormScreenForGodot=function(layout){const out=beforeNorm(layout);out.editor_version='3.9';for(const e of out.elements){e.opacity=bound(e.opacity??100,0,100);e.rotation=num(e.rotation);e.scale_x=num(e.scale_x,1);e.scale_y=num(e.scale_y,1);if(e.component_type==='building'||e.component_type==='sign'){const obj=layout.elements.find(v=>v.id===e.id);const a=asset(obj?.assetId);if(a)e.texture=assetPath(a)}}return out};\n// Previsão visual independente: sem executar transações, animações ou efeitos reais.\nconst modal=document.createElement('div');modal.className='v39-preview';modal.id='v39PreviewModal';modal.hidden=true;modal.innerHTML=`<div class=\"v39-preview-top\"><strong>▶ Prévia navegável — sem alterar o jogo</strong><span id=\"v39PreviewName\"></span><button id=\"v39PreviewClose\">✕ Fechar prévia</button></div><div class=\"v39-preview-content\"><div class=\"v39-preview-frame\" id=\"v39PreviewFrame\"></div></div><div class=\"v39-preview-foot\"><select id=\"v39PreviewSelect\"></select><span id=\"v39PreviewHint\">Os cliques entre telas são simulados; funções de jogo exigem integração com Godot 4.</span></div>`;\ndocument.body.append(modal);\nby('v39Preview').onclick=()=>{previewScreen=current;previewHidden.clear();modal.hidden=false;drawPreview()};by('v39PreviewClose').onclick=()=>modal.hidden=true;\nmodal.addEventListener('pointerdown',ev=>{if(ev.target===modal)modal.hidden=true});\nby('v39PreviewSelect').onchange=e=>{previewScreen=e.target.value;previewHidden.clear();drawPreview()};\nfunction drawPreview(){if(!state.screens[previewScreen])previewScreen=current;const layout=state.screens[previewScreen],r=layout.resolution,frame=by('v39PreviewFrame');frame.replaceChildren();by('v39PreviewName').textContent=previewScreen+' • '+r.width+' × '+r.height;const sel=by('v39PreviewSelect');sel.replaceChildren();for(const k of Object.keys(state.screens)){const opt=new Option(k,k);sel.add(opt)}sel.value=previewScreen;\n const view=by('v39PreviewFrame').parentElement;const scale=Math.min((view.clientWidth-36)/r.width,(view.clientHeight-36)/r.height,1.5);const surface=document.createElement('div');surface.className='v39-preview-surface';surface.style.width=r.width+'px';surface.style.height=r.height+'px';surface.style.transform='scale('+scale+')';surface.style.background=layout.background?.color||'#152d3e';const bg=asset(layout.background?.assetId);if(bg){surface.style.backgroundImage=`url(\"${bg.data}\")`;surface.style.backgroundSize=layout.background.fit==='contain'?'contain':layout.background.fit==='stretch'?'100% 100%':layout.background.fit==='custom'?num(layout.background.scale,100)+'%':'cover';surface.style.backgroundPosition=`${num(layout.background.x,50)}% ${num(layout.background.y,50)}%`}\n frame.style.width=(r.width*scale)+'px';frame.style.height=(r.height*scale)+'px';frame.append(surface);\n for(const e of [...layout.elements].sort((a,b)=>num(a.z_index)-num(b.z_index))){if(e.visible===false||previewHidden.has(e.owner_window)||previewHidden.has(e.window_id))continue;const clickable=e.type==='button'||e.click_behavior;const node=document.createElement(clickable?'button':'div');node.className='v39-preview-element';node.style.cssText=`left:${num(e.x)}px;top:${num(e.y)}px;width:${num(e.w)}px;height:${num(e.h)}px;z-index:${10+num(e.z_index)};color:${e.color||'#fff'};font:${num(e.font_weight,700)} ${num(e.font_size,20)}px ${e.font_family||'Arial'};text-align:${e.text_align||'center'};border-radius:${num(e.corner_radius,6)}px;opacity:${bound(e.opacity??100,0,100)/100};transform:rotate(${num(e.rotation)}deg) scale(${num(e.scale_x,1)},${num(e.scale_y,1)});background:${e.background||'transparent'};border:${e.type==='image'||e.type==='label'?'none':'2px solid '+(e.border_color||'transparent')}`;\n if((e.type==='button'&&e.hide_button_frame)||e.hotspot||e.component_type==='building'){node.style.border='none';node.style.background='transparent'}\n let image=asset(e.assetId)||asset(e.action_icon_asset);if(e.itemId){const item=state.items.find(i=>i.id===e.itemId);image=asset(item?.iconId)||image}if(image){const im=document.createElement('img');im.src=image.data;im.alt='';node.append(im)}\n if(e.component_type==='hud'||e.component_type==='hero_hud_bar'){const fill=document.createElement('div');fill.className='v39-hud-track';const i=document.createElement('i');i.style.background=e.bar_color||'#2ca6cf';i.style.width=bound(e.preview_percent??num(e.preview_value,0.7)*100,0,100)+'%';fill.append(i);node.append(fill)}\n if(e.component_type==='grid'){node.classList.add('v39-grid-component');node.style.setProperty('--v39-columns',String(e.columns||5));node.style.setProperty('--v39-rows',String(e.rows||3));const cells=document.createElement('div');cells.className='v39-grid-cells';for(let j=0;j<Math.min(100,(e.columns||5)*(e.rows||3));j++)cells.append(document.createElement('i'));node.append(cells)}\n if(e.type==='character_preview'&&!image){const x=document.createElement('span');x.textContent='▣ 3D • prévia';node.append(x)}\n if(e.text&&!(e.type==='image'||e.type==='item'||e.button_look==='image'||e.hotspot)){const span=document.createElement('span');span.className='v39-preview-label';span.textContent=e.text;node.append(span)}\n if(clickable){node.title=e.name+' • '+(e.target_screen||e.action||'sem ação');node.onclick=()=>previewClick(e)}surface.append(node)}\n}\nfunction previewClick(e){const action=e.action||'',target=e.target_screen;const map={abrir_inventario:'inventario',abrir_laboratorio:'laboratorio',abrir_loja_moba:'loja_moba_partida',abrir_forja:'forja',abrir_mercado:'loja',abrir_receitas:'receitas',selecionar_heroi:'selecao_herois',abrir_configuracoes:'configuracoes'};const dest=(e.click_behavior==='navegar'&&target)||map[action]||target;\n if(dest&&state.screens[dest]){previewScreen=dest;previewHidden.clear();drawPreview();by('v39PreviewHint').textContent='Navegou para '+dest+' (prévia local).';return}if(action==='fechar_janela_local'||e.click_behavior==='fechar'){const id=e.owner_window||e.window_id;if(id){previewHidden.add(id);drawPreview();return}by('v39PreviewHint').textContent='Vincule a janela que este botão deverá fechar.';return}by('v39PreviewHint').textContent='Ação '+(action||'não configurada')+': execução depende dos scripts reais do Godot.';}\nwindow.addEventListener('resize',()=>{if(!modal.hidden)drawPreview()});\n// Exposição limitada para testes locais e futuras ferramentas, sem registrar nada nos servidores.\nwindow.ApoenaLayout39={version:'3.9',getCurrent:()=>screen(),addComponent,updateResolution,align,group,reorder,drawPreview,openPreview:()=>by('v39Preview').click(),normalize};\nnormalize();renderLayout();notify('Game Creator 3.9: editor visual avançado carregado. O restante dos módulos da v3.8 foi preservado.');\n})();\n\n</script><script id=\"apoena-v39-workspace-fix-script\">\n/* v3.9 — Modo de trabalho foco, painéis recolhíveis/destacáveis, zoom por roda,\n * pan com Espaço + arrastar, e botões sem moldura/texto quando usam apenas imagem.\n * Complemento aplicado depois dos módulos oficiais; nenhum módulo substituído. */\n(()=>{\n'use strict';\nconst pg=document.getElementById('page-layouts'),area=pg?.querySelector('.layout-area');\nconst editor=window.ApoenaLayout39;if(!pg||!area||!editor)return;\nconst by=id=>document.getElementById(id);\nconst left=area.querySelector(':scope > .layout-side:first-child'),right=area.querySelector(':scope > .layout-side:last-child');\nconst stageScroll=by('stageScroll');if(!left||!right||!stageScroll)return;\nconst key='apoena.creator.layout.ui.v39';\nconst defaults={mode:'floating',focus:true,left:false,right:false,tab:'elements',xleft:12,yleft:12,xright:null,yright:12};\nlet settings={...defaults};try{const prior=JSON.parse(localStorage.getItem(key)||'null');if(prior&&typeof prior==='object')settings={...settings,...prior}}catch(e){}\nsettings.mode=['floating','docked'].includes(settings.mode)?settings.mode:'floating';\nconst save=()=>{try{localStorage.setItem(key,JSON.stringify(settings))}catch(e){}};\nconst bar=document.createElement('div');bar.className='v391-header';bar.id='v391WorkspaceBar';\nbar.innerHTML=`<h2>APOENA • Editor de Layout</h2><div class=\"v391-actions\"><button type=\"button\" id=\"v391Focus\">⛶ Área completa</button><button id=\"v391Elements\" type=\"button\">＋ Elementos</button><button id=\"v391Layers\" type=\"button\">▤ Camadas</button><button id=\"v391Properties\" type=\"button\">⚙ Propriedades</button><label style=\"font-size:11px\">Painéis <select id=\"v391Mode\" aria-label=\"Modo dos painéis\"><option value=\"floating\">Flutuantes</option><option value=\"docked\">Laterais retráteis</option></select></label><span class=\"v391-fill\"></span><button id=\"v391Fit\" type=\"button\">Encaixar</button><button id=\"v391Preview\" class=\"v391-primary\" type=\"button\">▶ Testar</button><button id=\"v391Advanced\" type=\"button\" aria-expanded=\"false\">☷ Ferramentas</button><button id=\"v391Exit\" type=\"button\">↩ Creator</button></div>`;\nconst advanced=document.createElement('div');advanced.className='v391-advanced';advanced.id='v391AdvancedPanel';advanced.hidden=true;\npg.insertBefore(bar,pg.firstChild);pg.insertBefore(advanced,area);\nfor(const id of ['v39Shell']){const elm=by(id);if(elm)advanced.append(elm)}\nfor(const elm of [...pg.children]){if(elm.classList?.contains('toolbar')||elm.classList?.contains('v35-panel')||elm.classList?.contains('v31-batch'))advanced.append(elm)}\nconst head=(name)=>{const d=document.createElement('div');d.className='v391-panel-head';d.innerHTML=`<strong>${name}</strong><button type=\"button\" title=\"Fechar painel\" aria-label=\"Fechar painel\">×</button>`;return d};\nconst lh=head('Biblioteca de elementos'),rh=head('Propriedades do elemento');\nconst layerPane=document.createElement('section');layerPane.className='v391-left-layers';layerPane.hidden=true;\nconst addPane=document.createElement('section');addPane.className='v391-left-elements';\nconst existingLayer=by('layerList');const layerHeader=left.querySelector('.v39-layer-header');\nconst headings=[...left.querySelectorAll('h3')];const oldLayerTitle=headings.find(h=>h.textContent.trim().toLowerCase()==='camadas');\nfor(const elm of [oldLayerTitle,layerHeader,existingLayer])if(elm)layerPane.append(elm);\nwhile(left.firstChild)addPane.append(left.firstChild);\nconst tabs=document.createElement('div');tabs.className='v391-tabbar';tabs.innerHTML='<button type=\"button\" data-v391-tab=\"elements\">＋ Adicionar</button><button type=\"button\" data-v391-tab=\"layers\">▤ Camadas</button>';\nleft.append(lh,tabs,addPane,layerPane);right.prepend(rh);\nconst footer=document.createElement('div');footer.className='v391-footer';footer.innerHTML='<span>Roda do mouse: zoom • Espaço + arrastar: mover cenário • Ctrl/Shift: multisseleção</span><span>Resolução do jogo preservada</span>';pg.append(footer);\npg.classList.add('v391-editor');\nfunction tab(name){settings.tab=name==='layers'?'layers':'elements';addPane.hidden=settings.tab!=='elements';layerPane.hidden=settings.tab!=='layers';tabs.querySelectorAll('button').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.v391Tab===settings.tab)));save()}\nfunction apply(){document.body.classList.toggle('v391-global-focus',!!settings.focus&&pg.classList.contains('ws-open')&&!pg.classList.contains('ws-minimized'));pg.classList.toggle('v391-focus',!!settings.focus);area.classList.toggle('v391-floating',settings.mode==='floating');area.classList.toggle('v391-docked',settings.mode==='docked');area.classList.toggle('v391-left-open',!!settings.left);area.classList.toggle('v391-right-open',!!settings.right);by('v391Mode').value=settings.mode;by('v391Focus').textContent=settings.focus?'▣ Janela normal':'⛶ Área completa';by('v391Focus').setAttribute('aria-pressed',String(!!settings.focus));for(const [id,pressed] of [['v391Elements',settings.left&&settings.tab==='elements'],['v391Layers',settings.left&&settings.tab==='layers'],['v391Properties',settings.right]])by(id).setAttribute('aria-pressed',String(pressed));\n area.style.setProperty('--v391-xleft',settings.xleft+'px');area.style.setProperty('--v391-yleft',settings.yleft+'px');area.style.setProperty('--v391-xright',settings.xright===null?'calc(100% - 302px)':settings.xright+'px');area.style.setProperty('--v391-yright',settings.yright+'px');tab(settings.tab);save();requestAnimationFrame(()=>{if(typeof computeScale==='function')computeScale()})}\nfunction openLeft(name){settings.left=!(settings.left&&settings.tab===name);settings.tab=name;apply()}\nby('v391Elements').onclick=()=>openLeft('elements');by('v391Layers').onclick=()=>openLeft('layers');\nby('v391Properties').onclick=()=>{settings.right=!settings.right;apply()};\nby('v391Mode').onchange=e=>{settings.mode=e.target.value;apply()};\nby('v391Focus').onclick=()=>{settings.focus=!settings.focus;apply()};\nby('v391Exit').onclick=()=>{settings.focus=false;apply()};\nby('v391Fit').onclick=()=>{const f=by('v39Fit');if(f)f.click();pan.x=pan.y=0;panFrame()};\nby('v391Preview').onclick=()=>by('v39Preview')?.click();\nby('v391Advanced').onclick=()=>{advanced.hidden=!advanced.hidden;by('v391Advanced').setAttribute('aria-expanded',String(!advanced.hidden));requestAnimationFrame(()=>computeScale())};\nfor(const [panel,headNode,side] of [[left,lh,'left'],[right,rh,'right']]){\n headNode.querySelector('button').onclick=()=>{settings[side==='left'?'left':'right']=false;apply()};\n let hold=null;\n headNode.addEventListener('pointerdown',e=>{if(settings.mode!=='floating'||e.button!==0||e.target.closest('button'))return;hold={x:e.clientX,y:e.clientY,left:panel.getBoundingClientRect().left-area.getBoundingClientRect().left,top:panel.getBoundingClientRect().top-area.getBoundingClientRect().top};headNode.setPointerCapture?.(e.pointerId);e.preventDefault()});\n headNode.addEventListener('pointermove',e=>{if(!hold)return;const x=Math.max(0,Math.min(area.clientWidth-panel.offsetWidth,hold.left+e.clientX-hold.x)),y=Math.max(0,Math.min(area.clientHeight-50,hold.top+e.clientY-hold.y));settings[side==='left'?'xleft':'xright']=Math.round(x);settings[side==='left'?'yleft':'yright']=Math.round(y);area.style.setProperty('--v391-x'+side,settings[side==='left'?'xleft':'xright']+'px');area.style.setProperty('--v391-y'+side,settings[side==='left'?'yleft':'yright']+'px')});\n const end=()=>{if(hold){hold=null;save()}};headNode.addEventListener('pointerup',end);headNode.addEventListener('pointercancel',end);\n}\ntabs.querySelectorAll('button').forEach(b=>b.onclick=()=>{settings.tab=b.dataset.v391Tab;tab(settings.tab);apply()});\n// Zoom por roda substitui a rolagem do cenário, sem alterar o tamanho lógico do projeto.\nlet pan={x:0,y:0},spaceHeld=false,panGrab=null;\nfunction panFrame(){const frame=by('stageFrame');if(frame)frame.style.transform=`translate(${pan.x}px,${pan.y}px)`}\nstageScroll.addEventListener('wheel',e=>{e.preventDefault();e.stopImmediatePropagation();const zoom=by('v39Zoom');if(!zoom)return;zoom.value=Math.min(250,Math.max(40,Number(zoom.value)+(e.deltaY<0?10:-10)));zoom.dispatchEvent(new Event('input',{bubbles:true}))},{passive:false,capture:true});\nstageScroll.addEventListener('pointerdown',e=>{if(!(e.button===1||(spaceHeld&&e.button===0)))return;e.preventDefault();e.stopImmediatePropagation();panGrab={id:e.pointerId,x:e.clientX,y:e.clientY,px:pan.x,py:pan.y};stageScroll.setPointerCapture?.(e.pointerId)},{capture:true});\nstageScroll.addEventListener('pointermove',e=>{if(!panGrab||e.pointerId!==panGrab.id)return;pan.x=panGrab.px+e.clientX-panGrab.x;pan.y=panGrab.py+e.clientY-panGrab.y;panFrame()});\nfor(const name of ['pointerup','pointercancel','lostpointercapture'])stageScroll.addEventListener(name,()=>{panGrab=null});\nwindow.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;if(e.code==='Space'&&pg.classList.contains('v391-editor')){spaceHeld=true;if(e.target===document.body||e.target===stageScroll)e.preventDefault()}if(e.key==='Escape'&&!by('v39PreviewModal')?.hidden)return;if(e.key==='Escape'&&settings.focus&&!advanced.hidden){advanced.hidden=true;by('v391Advanced').setAttribute('aria-expanded','false');return}if(e.key==='Escape'&&settings.focus){settings.focus=false;apply()}},{capture:true});window.addEventListener('keyup',e=>{if(e.code==='Space')spaceHeld=false});window.addEventListener('blur',()=>spaceHeld=false);\n// Botão de imagem: a aparência é APENAS a figura, sem sobreposição textual e sem moldura.\nfunction isPure(e){return e?.type==='button'&&(e.button_look==='image'||((e.component_type==='building')&&Boolean(e.action_icon_asset||e.assetId)))}\nconst oldStage=renderStage;\nrenderStage=function(){oldStage();for(const node of by('stage').querySelectorAll('.art')){const e=screen().elements.find(el=>el.id===node.dataset.id);if(!isPure(e))continue;\n const a=asset(e.action_icon_asset)||asset(e.assetId);if(!a)continue;\n node.classList.add('v391-image-only');node.style.background='transparent';node.style.border='0';node.style.borderRadius='0';node.querySelectorAll('span.txt,img.v34-button-icon,img.v36-button-photo,img.v39-component-image').forEach(n=>n.remove());\n const img=document.createElement('img');img.className='v391-pure-image';img.src=a.data;img.alt='';node.insertBefore(img,node.firstChild);\n }};\nconst oldInspector=renderInspector;\nrenderInspector=function(){oldInspector();const e=element();if(!e||e.type!=='button'||multiSelected.size>1)return;\n const look=by('v36ButtonLook');if(look){look.value=e.button_look||'image_text';look.title='Somente imagem oculta texto, moldura e fundo; a ação continua funcionando.'}\n const inp=by('inspector')?.querySelector('[data-field=\"text\"]');if(inp&&e.button_look==='image'){inp.style.display='none';if(inp.previousElementSibling)inp.previousElementSibling.style.display='none'}\n const section=by('v36ButtonPrev');if(section){const help=document.createElement('div');help.className='v391-image-helper';help.textContent='Somente imagem: sem texto, caixa, fundo ou moldura. A ação fica vinculada ao elemento.';\n const bt=document.createElement('button');bt.type='button';bt.textContent='⤢ Ajustar proporção do botão à imagem';bt.onclick=async()=>{const a=asset(e.action_icon_asset)||asset(e.assetId);if(!a)return;const img=new Image();img.onload=()=>{history();const ratio=img.naturalWidth/img.naturalHeight;e.h=Math.max(16,Math.round(e.w/ratio));renderLayout()};img.src=a.data};help.append(bt);section.after(help)}\n};\n// Captura anterior aos handlers legados: importar/selecionar foto muda automaticamente para modo \"só imagem\".\nby('inspector')?.addEventListener('change',e=>{const el=element();if(el?.type!=='button')return;\n if(e.target.id==='v36ButtonAsset'&&e.target.value||e.target.id==='v36ButtonFile'&&e.target.files?.length){el.button_look='image';el.hide_button_frame=true;}\n if(e.target.id==='v36ButtonLook'&&e.target.value==='image'){el.hide_button_frame=true;}\n},{capture:true});\n// O JSON para Godot transporta imagem e modo sem perder dados do projeto original.\nconst oldNorm=normScreenForGodot;\nnormScreenForGodot=function(layout){const out=oldNorm(layout);for(const e of out.elements){const original=layout.elements.find(x=>x.id===e.id);if(original?.type!=='button')continue;\n const im=asset(original.action_icon_asset)||asset(original.assetId);if(im){e.action_icon_path=assetPath(im);if(original.button_look==='image'||original.component_type==='building')e.texture=assetPath(im)}\n if(isPure(original)&&im){e.button_look='image';e.text='';e.hide_button_frame=true;e.background='#00000000';e.border_color='#00000000';}\n }return out};\n// Não se alteram conteúdo dos projetos salvos da versão 3.8 nem as 52 poções.\nstageScroll.addEventListener('pointerdown',e=>{if(e.target.closest('.art')&&!settings.right){settings.right=true;apply()}},{capture:false});\n// Sair automaticamente do foco ao abrir uma ferramenta diferente.\nconst beforePageSwitch=switchPage;\nswitchPage=function(name){if(name!=='layouts'&&settings.focus){settings.focus=false;apply()}return beforePageSwitch(name)};\napply();\nconst focusObserver=new MutationObserver(()=>{const show=settings.focus&&pg.classList.contains('ws-open')&&!pg.classList.contains('ws-minimized');document.body.classList.toggle('v391-global-focus',show)});focusObserver.observe(pg,{attributes:true,attributeFilter:['class']});\nwindow.ApoenaWorkspace39={getPreferences:()=>({...settings}),setMode:mode=>{if(mode==='floating'||mode==='docked'){settings.mode=mode;apply()}},setFocus:focus=>{settings.focus=!!focus;apply()},openPanel:name=>{if(name==='properties')settings.right=true;else{settings.left=true;settings.tab=name==='layers'?'layers':'elements'}apply()}};\n})();\n\n</script><script id=\"apoena-v39-item-factory-script\">\n(function(){\n 'use strict';\n // Usa state.items, state.assets, state.systemsV3 e os mesmos editores legados.\n const root=document.getElementById('page-drops'); if(!root)return;\n const el=id=>document.getElementById(id);\n let editId='',imageId='',manualId=false;\n const checked=id=>!!el(id).checked;\n const checkedSet=(id,v)=>{el(id).checked=!!v};\n const money=(id)=>Math.max(0,Number(el(id).value)||0);\n const escHTML=t=>String(t||'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\n function feedback(t){el('v40SaveMessage').textContent=t||'';}\n function imagePreview(){const a=imageId&&state.assets.find(x=>x.id===imageId),img=el('v40IconPreview');\n  img.hidden=!a;if(a)img.src=a.data;else img.removeAttribute('src');el('v40IconEmpty').hidden=!!a;\n  el('v40ImageFeedback').textContent=a?'Imagem selecionada: '+a.name:'Nenhuma imagem selecionada';\n }\n function setDefaultFlags(category){\n  checkedSet('v40InInventory',true);checkedSet('v40InStore',false);\n  checkedSet('v40InLab',['pocao','material','alimento'].includes(category));\n  checkedSet('v40InForge',['arma','escudo','armadura','acessorio'].includes(category));\n  checkedSet('v40InCrystal',category==='cristal');checkedSet('v40Available',true);\n }\n function blank(){editId='';imageId='';manualId=false;\n  for(const id of ['v37IngName','v37IngId','v37IngDesc'])el(id).value='';\n  el('v40Category').value='material';el('v40Rarity').value='comum';el('v40UseAction').value='nenhuma';el('v40Scope').value='permanente';\n  el('v40Mode').value='ambos';el('v40Currency').value='ouro';el('v40Price').value='0';el('v40Diamonds').value='0';setDefaultFlags('material');\n  el('v40IdHelp').textContent='O ID conecta o item à loja, receitas, inventário e drops.';\n  el('v37CreateIngredient').textContent='✓ Salvar item no banco do jogo';\n  el('v40DropDetails').open=false;imagePreview();window.ApoenaUniversal40?.reset();feedback('Novo item: preencha a ficha e clique em Salvar.');drawFactoryList();\n }\n function openItem(id){const i=state.items.find(x=>x.id===id);if(!i)return;editId=id;imageId=i.iconId||'';manualId=true;\n  el('v37IngName').value=i.name||'';el('v37IngId').value=i.id||'';\n  el('v37IngDesc').value=i.description||'';el('v40Category').value=i.category||'outro';el('v40Rarity').value=i.rarity||'comum';\n  el('v40UseAction').value=['nenhuma','consumir','equipar','ativar_poder','desbloquear','entregar_missao'].includes(i.useAction)?i.useAction:'nenhuma';\n  el('v40Scope').value=['permanente','partida','evento'].includes(i.scope)?i.scope:'permanente';\n  el('v40Mode').value=['ambos','moba','exploracao'].includes(i.requiredMode)?i.requiredMode:'ambos';\n  const vis=i.visibility||{};\n  checkedSet('v40InInventory',vis.inventory??true);checkedSet('v40InLab',vis.lab??vis.laboratorio??false);\n  checkedSet('v40InStore',vis.store??vis.loja??false);checkedSet('v40InForge',vis.forge??vis.forja??false);\n  checkedSet('v40InCrystal',vis.crystal??vis.cristais??false);checkedSet('v40Available',vis.available??vis.disponivel??true);\n  el('v40Currency').value=['ouro','diamantes','gratuito','nenhuma'].includes(i.currency)?i.currency:'ouro';\n  el('v40Price').value=Number(i.price)||0;el('v40Diamonds').value=Number(i.diamonds)||0;\n  el('v40IdHelp').textContent='ID de item salvo: mantenha o identificador para não romper vínculos já existentes.';\n  el('v37CreateIngredient').textContent='✓ Atualizar item existente';\n  imagePreview();updateCombos37();el('v37DropItem').value=i.id;feedback('Editando: '+i.name+'. As alterações serão feitas no mesmo cadastro.');drawFactoryList();\n  window.ApoenaUniversal40?.load(i);root.scrollIntoView({block:'start',behavior:'smooth'});\n }\n function drawFactoryList(){const box=el('v40ItemRecords');if(!box)return;\n  const q=el('v40SearchItems').value.trim().toLowerCase(),rows=state.items.filter(i=>String(i.id+' '+i.name+' '+i.category).toLowerCase().includes(q));\n  box.innerHTML=rows.length?rows.map(i=>{const a=i.iconId&&state.assets.find(x=>x.id===i.iconId);\n   return `<button class=\"v40-item-card ${editId===i.id?'v40-selected':''}\" data-v40-open=\"${escHTML(i.id)}\" type=\"button\">${a?`<img alt=\"\" src=\"${a.data}\">`:'<span class=\"v40-item-placeholder\">▧</span>'}<span><strong>${escHTML(i.name)}</strong><small>${escHTML(i.id)}</small><small>${escHTML(i.category)}</small></span></button>`;\n  }).join(''):'<p class=\"hint\">Nenhum item encontrado. Crie um item usando o formulário.</p>';\n  box.querySelectorAll('[data-v40-open]').forEach(b=>b.addEventListener('click',()=>openItem(b.dataset.v40Open)));\n }\n async function uploadFile(file){if(!file)return;try{\n   const data=await fileToPNG(file),a=makeAsset(file.name,data,'upload',el('v40Category').value);\n   imageId=a.id;imagePreview();refreshAssetLists();feedback('Ícone carregado. Salve o item para associá-lo ao cadastro.');\n  }catch(e){alert('Não foi possível carregar a imagem: '+e.message)}\n  el('v37NewIngredientIcon').value='';\n }\n function savedFactory(){\n  const name=el('v37IngName').value.trim(),id=validId(el('v37IngId').value||name),category=el('v40Category').value;\n  if(!name||!id)return alert('Preencha o nome e o identificador do item.');\n  if(editId&&id!==editId)return alert('O ID existente não pode ser alterado nesta ficha, para preservar os vínculos. Cadastre um novo item com outro ID.');\n  const existing=state.items.find(i=>i.id===id);\n  if(existing&&!editId)return alert('Já existe um item com este identificador. Selecione-o na lista à direita para editar.');\n  const official=existing?.source==='pack_52';\n  if(official&&!confirm('Este é um item do catálogo oficial das 52 poções. Deseja alterar sua ficha? Os dados oficiais existentes serão preservados nos campos não editados.'))return;\n  const flags={...(existing?.visibility||{}),inventory:checked('v40InInventory'),lab:checked('v40InLab'),store:checked('v40InStore'),forge:checked('v40InForge'),crystal:checked('v40InCrystal'),available:checked('v40Available')};\n  // Espelha chaves legadas sem descartar quaisquer campos de outras versões.\n  Object.assign(flags,{laboratorio:flags.lab,loja:flags.store,forja:flags.forge,cristais:flags.crystal,disponivel:flags.available});\n  const item={...(existing||{}),id,name,category,rarity:el('v40Rarity').value,iconId:imageId,\n   description:el('v37IngDesc').value.trim(),visibility:flags,price:money('v40Price'),diamonds:money('v40Diamonds'),\n   currency:el('v40Currency').value,scope:el('v40Scope').value,requiredMode:el('v40Mode').value,useAction:el('v40UseAction').value};\n  if(!existing)Object.assign(item,{effect:{type:'nenhum',value:0,duration:0},gameplayEnabled:false,equippable:false,equipmentSlot:'',consumable:false,maxStack:99,craftCost:0,source:'custom',status:'rascunho'});\n  // Dados universais ficam NO MESMO ITEM, preservando campos legados e fichas oficiais.\n  const au=window.ApoenaUniversal40;\n  if(au){const validation=au.validate();if(validation.errors.length){au.report();alert('Corrija os erros exibidos em Verificação antes de salvar.');return}\n   item.universal=au.collect();if(!official){item.maxStack=item.universal.storage.stack;\n    item.consumable=item.universal.roles.includes('consumivel');\n    item.equippable=item.universal.roles.some(x=>['arma','escudo','armadura','equipamento'].includes(x));\n    if(item.universal.equipment.slots)item.equipmentSlot=item.universal.equipment.slots;\n    item.status=item.universal.workflow.status;}\n   // Fichas oficiais: conservamos explicitamente os campos legados e gravamos apenas o novo subregistro universal.\n  }\n  if(!existing)state.items.push(item);else {\n   if(existing.universal){const history=Array.isArray(existing.universalHistory)?existing.universalHistory:[];\n    history.push({at:new Date().toISOString(),universal:deep(existing.universal)});item.universalHistory=history.slice(-10);\n   }\n   Object.assign(existing,item);\n  }\n  // Sincronizar os mesmos dados nos demais editores e exportadores.\n  refreshAssetLists();renderItems();renderDatabase();updateCombos37();el('v37DropItem').value=id;el('v37RecipeIngredient').value=id;\n  editId=id;manualId=true;el('v37CreateIngredient').textContent='✓ Atualizar item existente';\n  window.ApoenaUniversal40?.load(item);feedback((existing?'Item atualizado: ':'Item criado: ')+name+' — disponível no catálogo compartilhado.');drawFactoryList();\n  save37();\n }\n el('v40NewItem').addEventListener('click',blank);\n el('v40SearchItems').addEventListener('input',drawFactoryList);\n el('v37IngName').addEventListener('input',()=>{if(!editId&&!manualId)el('v37IngId').value=validId(el('v37IngName').value)});\n el('v37IngId').addEventListener('input',()=>manualId=!!el('v37IngId').value.trim());\n el('v40Category').addEventListener('change',()=>{if(!editId)setDefaultFlags(el('v40Category').value)});\n el('v37CreateIngredient').onclick=savedFactory;\n el('v37NewIngredientIcon').onchange=e=>uploadFile(e.target.files?.[0]);\n const picker=el('v37NewIngredientIcon'),zone=el('v40IconDrop');\n const pick=()=>picker.click();zone.addEventListener('click',pick);el('v40PickIcon').addEventListener('click',pick);\n zone.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();pick()}});\n for(const e of ['dragenter','dragover'])zone.addEventListener(e,ev=>{ev.preventDefault();zone.classList.add('v40-drag-over')});\n for(const e of ['dragleave','drop'])zone.addEventListener(e,()=>zone.classList.remove('v40-drag-over'));\n zone.addEventListener('drop',e=>{e.preventDefault();const f=[...(e.dataTransfer?.files||[])].find(x=>x.type.startsWith('image/'));if(f)uploadFile(f);else feedback('Arraste uma imagem PNG, JPG ou WebP.')});\n el('v40RemoveIcon').addEventListener('click',()=>{imageId='';imagePreview();feedback('Imagem removida da ficha. Salve para confirmar.')});\n el('v40EditAdvanced').addEventListener('click',()=>{if(!editId){alert('Salve o item antes de editar as regras avançadas.');return}const i=state.items.find(x=>x.id===editId);if(i)fillItem(i)});\n const previousAddDrop=el('v37AddDrop').onclick;\n el('v37AddDrop').onclick=function(e){if(!el('v37DropItem').value&&editId)el('v37DropItem').value=editId;return previousAddDrop?.call(this,e)};\n // Permitir soltar imagens diretamente em todas as entradas de foto do aplicativo.\n const imageInputs=[...document.querySelectorAll('input[type=\"file\"]')].filter(i=>i!==picker&&/image\\//.test(i.getAttribute('accept')||''));\n imageInputs.forEach(input=>{\n  const wrap=document.createElement('div');wrap.className='v40-universal-drop';\n  input.parentNode.insertBefore(wrap,input);wrap.appendChild(input);\n  const hint=document.createElement('p');hint.className='v40-upload-help';hint.textContent='Solte uma imagem aqui ou clique em Escolher arquivo.';wrap.appendChild(hint);\n  const drag=e=>{e.preventDefault();e.stopPropagation();wrap.classList.add('v40-drag-over')};\n  wrap.addEventListener('dragenter',drag);wrap.addEventListener('dragover',drag);\n  wrap.addEventListener('dragleave',e=>{if(!wrap.contains(e.relatedTarget))wrap.classList.remove('v40-drag-over')});\n  wrap.addEventListener('drop',e=>{\n   e.preventDefault();e.stopPropagation();wrap.classList.remove('v40-drag-over');\n   const files=[...(e.dataTransfer?.files||[])].filter(f=>f.type.startsWith('image/'));if(!files.length){hint.textContent='Arquivo inválido: escolha uma imagem.';return}\n   try{const dt=new DataTransfer();(input.multiple?files:[files[0]]).forEach(f=>dt.items.add(f));input.files=dt.files;input.dispatchEvent(new Event('change',{bubbles:true}));hint.textContent=files.length+' imagem(ns) recebida(s).'}catch(err){hint.textContent='Não foi possível importar esta imagem: '+err.message}\n  });\n });\n // Recarrega a lista quando o usuário retorna ao editor por qualquer rota do aplicativo.\n const obs=new MutationObserver(()=>{if(root.classList.contains('active')){drawFactoryList();imagePreview()}});\n obs.observe(root,{attributes:true,attributeFilter:['class']});\n blank();\n window.ApoenaFactory39={openItem,clear:blank,list:()=>state.items.map(i=>({id:i.id,name:i.name,category:i.category,iconId:i.iconId}))};\n})();\n</script><script id=\"apoena-universal-factory-script\">\n/* APOENA GAME CREATOR — Fábrica Universal v3.9.1\n   Extensão progressiva: um item, várias funções, efeitos, origens e usos.\n   Nenhum dado oficial é alterado sem salvar explicitamente; sem backend ou serviços externos.\n*/\n(function(){\n'use strict';\nconst root=document.getElementById('page-drops');if(!root)return;\nconst $=id=>document.getElementById(id);\nconst esc=x=>String(x??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst uid=()=> 'r_'+(crypto?.randomUUID?.()||(''+Date.now()+'_'+Math.random().toString(36).slice(2)));\nconst num=(v,def=0)=>{let n=Number(v);return Number.isFinite(n)?n:def};\nconst copy=x=>JSON.parse(JSON.stringify(x));\nconst roles=[['consumivel','Consumível'],['ingrediente','Ingrediente de receita'],['arma','Arma'],['escudo','Escudo'],['armadura','Armadura'],['equipamento','Equipamento'],['habilidade','Concede poder'],['material_forja','Material de forja'],['missao','Item de missão'],['comercio','Comercializável'],['interativo','Objeto interativo'],['colecionavel','Colecionável']];\nconst attrs=[['hp','Vida (HP)'],['aurium','Aurium (AUR)'],['ataque','Ataque'],['defesa','Defesa'],['forca','Força'],['velocidade','Velocidade'],['inteligencia','Inteligência'],['sorte','Sorte'],['xp','Experiência (XP)'],['habilidade','Habilidade'],['custom','Atributo personalizado']];\nconst triggers=[['ao_equipar','Ao equipar'],['ao_consumir','Ao consumir'],['ao_usar','Ao usar'],['ao_atacar','Ao atacar'],['ao_acertar','Ao acertar'],['ao_defender','Ao defender'],['ao_sofrer_dano','Ao receber dano'],['ao_matar','Ao derrotar inimigo'],['passivo','Enquanto no inventário']];\nconst origins=[['arvore','Árvore'],['planta','Planta / coleta'],['monstro','Monstro / chefe'],['minerio','Minério / rocha'],['bau','Baú'],['pesca','Pesca'],['cenario','Objeto do cenário'],['missao','Missão / recompensa'],['receita','Fabricação / receita'],['loja','Loja / mercador'],['outro','Personalizado']];\nconst actions=[['colher','Colher'],['cortar','Cortar'],['quebrar','Quebrar'],['derrotar','Derrotar'],['interagir','Interagir'],['abrir','Abrir'],['pescar','Pescar'],['comprar','Comprar'],['fabricar','Fabricar'],['recompensa','Receber recompensa']];\nconst locations=[['mochila','Mochila'],['equipamento','Equipamento'],['laboratorio','Laboratório'],['forja','Forja'],['loja','Loja'],['missao','Missões'],['mapa','Mapa'],['personagens','Heróis'],['evento','Eventos'],['outro','Outros']];\nconst select=(choices,val,cls)=>`<select class=\"${cls}\">${choices.map(([id,title])=>`<option value=\"${esc(id)}\" ${id===val?'selected':''}>${esc(title)}</option>`).join('')}</select>`;\nconst field=(lbl,html)=>`<div><label>${lbl}</label>${html}</div>`;\nfunction fresh(){return {version:1,roles:[],effects:[],sources:[],placements:[],tags:'',notes:'',equipment:{slots:'',requiredLevel:0,classes:'',maxDurability:0,setId:''},storage:{stack:99,weight:0,tradable:true,discardable:true,unique:false,expiryMinutes:0},economy:{buy:0,sell:0,stock:0,restockMinutes:0},workflow:{status:'rascunho'},language:{},metadata:{}}}\nlet model=fresh();let sourceIndex=-1,effectIndex=-1,dirty=false;\nconst up=(arr,id,val)=>{if(val){if(!arr.includes(id))arr.push(id)}else{const p=arr.indexOf(id);if(p>=0)arr.splice(p,1)}};\nfunction checkGroups(arr,namespace){return arr.map(([k,v])=>`<label><input type=\"checkbox\" data-augroup=\"${namespace}\" value=\"${k}\" ${model[namespace].includes(k)?'checked':''}>${v}</label>`).join('')}\nfunction inject(){\n const sec3=$('v40UseAction').closest('.v40-section');\n sec3.insertAdjacentHTML('beforeend',`<div id=\"au40Functional\" class=\"au40-panel\"><h3>Funções múltiplas (não escolha apenas uma)</h3><p class=\"au40-help\">O mesmo objeto pode ser consumível, ingrediente, arma e material de fabricação. A função antiga será preservada para compatibilidade.</p><div class=\"au40-tags\" id=\"au40Roles\"></div><details><summary>Editor de efeitos e atributos</summary><p class=\"au40-help\">Configure efeitos independentes: quando acontecem, como calculam, duração, chance e acúmulo. A execução precisa existir no Godot.</p><div class=\"au40-buttons\"><button type=\"button\" id=\"au40AddEffect\">＋ Adicionar efeito</button></div><div id=\"au40Effects\"></div></details><details><summary>Equipamentos, requisitos e durabilidade</summary><div class=\"au40-grid two\" id=\"au40Equipment\"></div></details><details><summary>Inventário, empilhamento e trocas</summary><div class=\"au40-grid two\" id=\"au40Storage\"></div></details></div>`);\n const sec4=$('v40Mode').closest('.v40-section');\n sec4.insertAdjacentHTML('beforeend',`<div class=\"au40-panel\"><h3>Locais adicionais e organização</h3><div class=\"au40-tags\" id=\"au40Locations\"></div><div class=\"au40-grid two\">${field('Etiquetas para busca','<input id=\"au40Tags\" placeholder=\"flor, raro, cura\">')}${field('Notas internas','<textarea id=\"au40Notes\" rows=\"2\" placeholder=\"Uso interno para o desenvolvedor\"></textarea>')}</div></div>`);\n const sec5=$('v40DropDetails').closest('.v40-section');\n sec5.insertAdjacentHTML('beforeend',`<div class=\"au40-panel\"><h3>Origens múltiplas do mesmo item</h3><p class=\"au40-help\">Cadastre quantas fontes quiser: árvore, monstro, rocha, baú e outras. Cada uma possui probabilidade e quantidade próprias. O editor legado de monstros acima continua disponível.</p><button type=\"button\" id=\"au40AddSource\">＋ Adicionar origem</button><div id=\"au40Sources\"></div></div>`);\n const sec6=$('v40Currency').closest('.v40-section');\n sec6.insertAdjacentHTML('beforeend',`<div class=\"au40-panel\"><h3>Economia avançada e publicação</h3><div class=\"au40-grid two\" id=\"au40Economy\"></div><div class=\"au40-grid two\"><div><label>Estado de publicação</label><select id=\"au40Status\"><option value=\"rascunho\">Rascunho</option><option value=\"teste\">Em teste</option><option value=\"publicado\">Publicado</option></select></div><div><label>Histórico do item</label><p class=\"au40-help\" id=\"au40Revision\">Ainda sem revisões</p></div></div></div>`);\n const footer=$('v37CreateIngredient').closest('.v40-actions-footer');\n footer.insertAdjacentHTML('beforeend',`<div class=\"au40-panel\" style=\"width:100%\"><h3>Verificação, simulação e relações</h3><p class=\"au40-help\">Tudo funciona offline. Uma simulação de drops não executa combate no Godot.</p><div class=\"au40-buttons\"><button id=\"au40Validate\" type=\"button\">✓ Validar configuração</button><button id=\"au40Simulate\" type=\"button\">⚗ Simular 10.000 drops</button><button id=\"au40EffectTest\" type=\"button\">⚔ Prévia dos efeitos</button><button id=\"au40Relations\" type=\"button\">🔗 Onde é usado?</button><button id=\"au40Duplicate\" type=\"button\">▣ Duplicar ficha</button><button id=\"au40Export\" type=\"button\">↓ Exportar ficha JSON</button><button id=\"au40Audit\" type=\"button\">☑ Auditar banco completo</button></div><div class=\"au40-result\" id=\"au40Results\" role=\"status\" aria-live=\"polite\">O banco principal e os recursos oficiais são preservados.</div></div>`);\n}\nfunction mark(){dirty=true}\nfunction showRoles(){ $('au40Roles').innerHTML=checkGroups(roles,'roles');$('au40Locations').innerHTML=checkGroups(locations,'placements');root.querySelectorAll('[data-augroup]').forEach(x=>x.onchange=()=>{up(model[x.dataset.augroup],x.value,x.checked);mark()})}\nfunction standardEffect(){return {id:uid(),attribute:'ataque',customAttribute:'',operation:'adicionar',value:0,trigger:'ao_equipar',target:'usuario',chance:100,duration:0,interval:0,cooldown:0,stacking:'nao',maxStacks:1,condition:''}}\nfunction renderEffects(){\n const wrap=$('au40Effects');wrap.innerHTML=model.effects.length?'':'<div class=\"au40-empty\">Nenhum efeito cadastrado.</div>';\n model.effects.forEach((e,i)=>{\n let box=document.createElement('div');box.className='au40-card';box.innerHTML=`<div class=\"au40-card-head\"><strong>Efeito ${i+1}</strong><button class=\"au40-danger\" data-action=\"remove\" type=\"button\">Excluir</button></div>\n <div class=\"au40-grid\">${field('Atributo',select(attrs,e.attribute,'aAttr'))}${field('Operação',select([['adicionar','Somar pontos'],['percentual','Porcentagem'],['multiplicar','Multiplicar'],['recuperar','Restaurar'],['fixar','Definir valor']],e.operation,'aOp'))}${field('Valor','<input class=\"aValue\" type=\"number\" step=\"any\" value=\"'+esc(e.value)+'\">')}\n ${field('Gatilho',select(triggers,e.trigger,'aTrigger'))}${field('Alvo',select([['usuario','Quem usa'],['aliado','Aliado'],['inimigo','Inimigo'],['area','Área']],e.target,'aTarget'))}${field('Chance (%)','<input class=\"aChance\" type=\"number\" min=\"0\" max=\"100\" value=\"'+esc(e.chance)+'\">')}\n ${field('Duração (segundos)','<input class=\"aDuration\" type=\"number\" min=\"0\" step=\"any\" value=\"'+esc(e.duration)+'\">')}${field('Intervalo (segundos)','<input class=\"aInterval\" type=\"number\" min=\"0\" step=\"any\" value=\"'+esc(e.interval)+'\">')}${field('Recarga (segundos)','<input class=\"aCooldown\" type=\"number\" min=\"0\" step=\"any\" value=\"'+esc(e.cooldown)+'\">')}\n ${field('Acúmulo',select([['nao','Não acumula'],['acumular','Acumula'],['substituir','Substituir']],e.stacking,'aStacking'))}${field('Máximo de acúmulos','<input class=\"aMaxStacks\" type=\"number\" min=\"1\" value=\"'+esc(e.maxStacks)+'\">')}${field('Atributo personalizado','<input class=\"aCustom\" value=\"'+esc(e.customAttribute)+'\" placeholder=\"Opcional\">')}</div>\n <div class=\"au40-grid two\" style=\"margin-top:8px\">${field('Condição / expressão de regra (texto)','<input class=\"aCondition\" value=\"'+esc(e.condition)+'\" placeholder=\"Ex.: personagem nível 10 (não executado sem regra)\">')}</div>`;\n const get=(s)=>box.querySelector(s);\n for(let [sel,key] of [['.aAttr','attribute'],['.aOp','operation'],['.aValue','value'],['.aTrigger','trigger'],['.aTarget','target'],['.aChance','chance'],['.aDuration','duration'],['.aInterval','interval'],['.aCooldown','cooldown'],['.aStacking','stacking'],['.aMaxStacks','maxStacks'],['.aCustom','customAttribute'],['.aCondition','condition']]){\n get(sel).addEventListener('change',ev=>{e[key]=['value','chance','duration','interval','cooldown','maxStacks'].includes(key)?num(ev.target.value):ev.target.value;mark()})\n }\n get('[data-action=\"remove\"]').onclick=()=>{model.effects.splice(i,1);mark();renderEffects()};wrap.appendChild(box);\n });\n}\nfunction standardSource(){return {id:uid(),type:'arvore',sourceId:'',name:'',action:'colher',chance:100,min:1,max:1,conditions:'',respawn:0,region:''}}\nfunction renderSources(){\n const wrap=$('au40Sources');wrap.innerHTML=model.sources.length?'':'<div class=\"au40-empty\">Nenhuma origem cadastrada. Um item pode existir sem ter drop.</div>';\n model.sources.forEach((s,i)=>{\n const box=document.createElement('div');box.className='au40-card';box.innerHTML=`<div class=\"au40-card-head\"><strong>Origem ${i+1}</strong><button type=\"button\" class=\"au40-danger\" data-remove>Excluir</button></div>\n <div class=\"au40-grid\">${field('Tipo de fonte',select(origins,s.type,'sType'))}${field('Nome da fonte','<input class=\"sName\" value=\"'+esc(s.name)+'\" placeholder=\"Ex.: Árvore azul\">')}${field('ID da fonte cadastrada','<input class=\"sId\" value=\"'+esc(s.sourceId)+'\" placeholder=\"ID opcional\">')}\n ${field('Como é obtido?',select(actions,s.action,'sAction'))}${field('Chance (%)','<input class=\"sChance\" type=\"number\" min=\"0\" max=\"100\" step=\"any\" value=\"'+esc(s.chance)+'\">')}${field('Quantidade mínima','<input class=\"sMin\" type=\"number\" min=\"1\" step=\"1\" value=\"'+esc(s.min)+'\">')}\n ${field('Quantidade máxima','<input class=\"sMax\" type=\"number\" min=\"1\" step=\"1\" value=\"'+esc(s.max)+'\">')}${field('Reaparecimento (seg.)','<input class=\"sRespawn\" type=\"number\" min=\"0\" value=\"'+esc(s.respawn)+'\">')}${field('Região / bioma','<input class=\"sRegion\" value=\"'+esc(s.region)+'\" placeholder=\"Opcional\">')}\n </div>${field('Condições do drop','<input class=\"sConditions\" value=\"'+esc(s.conditions)+'\" placeholder=\"Ex.: à noite, missão ativa (regra declarativa)\">')}`;\n for(const [sel,key] of [['.sType','type'],['.sName','name'],['.sId','sourceId'],['.sAction','action'],['.sChance','chance'],['.sMin','min'],['.sMax','max'],['.sRespawn','respawn'],['.sRegion','region'],['.sConditions','conditions']]){\n box.querySelector(sel).addEventListener('change',ev=>{s[key]=['chance','min','max','respawn'].includes(key)?num(ev.target.value):ev.target.value;mark()});\n }\n box.querySelector('[data-remove]').onclick=()=>{model.sources.splice(i,1);mark();renderSources()};wrap.appendChild(box);\n });\n}\nconst config={\n equipment:[['slots','Slots ocupados','text','Ex.: mão direita, mão esquerda'],['requiredLevel','Nível mínimo','number','0'],['classes','Classes / tribos permitidas','text','Opcional'],['maxDurability','Durabilidade máxima','number','0'],['setId','Conjunto de equipamento','text','Opcional']],\n storage:[['stack','Máximo por pilha','number','99'],['weight','Peso por unidade','number','0'],['expiryMinutes','Validade em minutos (0 = não expira)','number','0'],['tradable','Permite negociar','checkbox',''],['discardable','Permite descartar','checkbox',''],['unique','Único por jogador','checkbox','']],\n economy:[['buy','Preço de compra (moeda principal)','number','0'],['sell','Preço de venda','number','0'],['stock','Estoque da loja (0 = sem limite definido)','number','0'],['restockMinutes','Reposição (minutos)','number','0']]\n};\nfunction renderConfig(group){const id={equipment:'au40Equipment',storage:'au40Storage',economy:'au40Economy'}[group],obj=model[group];let box=$(id);box.innerHTML='';for(const [key,lbl,type,placeholder] of config[group]){\n const wrap=document.createElement('div'),input=document.createElement('input');input.type=type;input.placeholder=placeholder;\n if(type==='checkbox')input.checked=!!obj[key];else input.value=obj[key]??'';\n input.addEventListener('change',()=>{obj[key]=type==='checkbox'?input.checked:type==='number'?num(input.value):input.value;mark()});wrap.appendChild(Object.assign(document.createElement('label'),{textContent:lbl}));wrap.appendChild(input);box.appendChild(wrap)}\n}\nfunction render(){showRoles();renderEffects();renderSources();for(const k of Object.keys(config))renderConfig(k);$('au40Tags').value=model.tags||'';$('au40Notes').value=model.notes||'';$('au40Status').value=model.workflow.status||'rascunho';$('au40Revision').textContent=(model.metadata?.revision||0)+' revisão(ões) registrada(s)';}\nfunction reset(){model=fresh();dirty=false;render();$('au40Results').textContent='Novo item: escolha as funções, efeitos e origens que precisar.'}\nfunction load(item){model={...fresh(),...(copy(item.universal||{}))};for(const k of ['equipment','storage','economy','workflow','language','metadata'])model[k]={...fresh()[k],...(model[k]||{})};for(const k of ['roles','effects','sources','placements'])if(!Array.isArray(model[k]))model[k]=[];\n // Itens legados permanecem exatamente com os dados originais. Apenas sugerimos funções para edição.\n if(!item.universal){model.storage.stack=Number.isInteger(item.maxStack)&&item.maxStack>0?item.maxStack:99;if(item.consumable||item.useAction==='consumir'||item.category==='pocao'||item.category==='alimento')model.roles.push('consumivel');if(item.equippable||item.useAction==='equipar')model.roles.push('equipamento');if(item.category==='material')model.roles.push('ingrediente');model.economy.buy=num(item.price);}\n dirty=false;render();$('au40Results').textContent='Editando '+item.name+'. Campos oficiais legados preservados.';\n}\nfunction collect(){const current=copy(model);current.tags=$('au40Tags').value.trim();current.notes=$('au40Notes').value.trim();current.workflow.status=$('au40Status').value;current.metadata={...(current.metadata||{}),revision:num(current.metadata?.revision)+1,updatedAt:new Date().toISOString()};return current}\nfunction messages(){const errors=[],warnings=[];const m=collect();\n if(!($('v37IngName').value||'').trim())errors.push('Informe o nome do item.');\n const id=($('v37IngId').value||'').trim();if(!id)errors.push('Informe o identificador.');\n const seen=new Set();m.effects.forEach((e,n)=>{const t=n+1;if(seen.has(e.id))errors.push('Efeito '+t+': ID duplicado.');seen.add(e.id);if(!Number.isFinite(e.value))errors.push('Efeito '+t+': valor inválido.');if(e.chance<0||e.chance>100)errors.push('Efeito '+t+': chance fora de 0 a 100%.');if(e.duration<0||e.interval<0||e.cooldown<0)errors.push('Efeito '+t+': tempo negativo.');if(e.maxStacks<1)errors.push('Efeito '+t+': acúmulo deve ser >= 1.');if(e.attribute==='custom'&&!e.customAttribute?.trim())errors.push('Efeito '+t+': atributo personalizado vazio.');if(e.condition)warnings.push('Efeito '+t+': condição textual exige executor no Godot.');});\n const sourceIds=new Set();m.sources.forEach((s,n)=>{const t=n+1;if(sourceIds.has(s.id))errors.push('Origem '+t+': ID interno repetido.');sourceIds.add(s.id);if(s.chance<0||s.chance>100)errors.push('Origem '+t+': chance inválida.');if(!Number.isInteger(s.min)||!Number.isInteger(s.max)||s.min<1||s.max<s.min||s.max>9999)errors.push('Origem '+t+': quantidades inválidas.');if(s.respawn<0)errors.push('Origem '+t+': reaparecimento negativo.');if(s.type==='monstro'&&s.sourceId&&!((state.systemsV3?.npcs||[]).some(x=>x.id===s.sourceId)))warnings.push('Origem '+t+': ID de monstro não encontrado no cadastro.');if(s.conditions)warnings.push('Origem '+t+': condição textual exige execução no Godot.');});\n if(m.storage.stack<1||!Number.isInteger(m.storage.stack))errors.push('Máximo por pilha deve ser inteiro positivo.');if(m.storage.weight<0)errors.push('Peso não pode ser negativo.');if(m.equipment.requiredLevel<0)errors.push('Nível mínimo negativo.');if(m.economy.buy<0||m.economy.sell<0)errors.push('Preço não pode ser negativo.');\n if(m.roles.length===0)warnings.push('Item sem função marcada; pode ser intencional.');\n if(m.economy.sell>m.economy.buy&&m.economy.buy>0)warnings.push('Venda acima do preço de compra: verifique risco de lucro infinito.');\n if(m.workflow.status==='publicado'&&!m.roles.length)warnings.push('Publicado sem funções definidas.');\n warnings.push('Efeitos e origens avançadas são dados declarativos; só funcionarão no jogo com executor Godot correspondente.');\n return {errors,warnings};}\nfunction report(){const r=messages();$('au40Results').innerHTML=`<strong class=\"${r.errors.length?'au40-alert':'au40-ok'}\">${r.errors.length?'Erros encontrados: '+r.errors.length:'✓ Sem erros estruturais'}</strong>\\n`+[...r.errors.map(x=>'✗ '+x),...r.warnings.map(x=>'! '+x)].map(esc).join('\\n');return r}\nfunction simulate(){let results=[];const N=10000;let seed=123456789;function random(){seed^=seed<<13;seed^=seed>>>17;seed^=seed<<5;return (seed>>>0)/4294967296}\n if(!model.sources.length){$('au40Results').textContent='Adicione pelo menos uma origem de drop para simular.';return}\n model.sources.forEach((s,i)=>{if(!(s.chance>=0&&s.chance<=100&&s.min>=1&&s.max>=s.min)){results.push('Origem '+(i+1)+': dados inválidos');return}let hits=0,quantity=0;for(let k=0;k<N;k++){if(random()<s.chance/100){hits++;quantity+=s.min+Math.floor(random()*(s.max-s.min+1))}}\n let expected=N*s.chance/100*(s.min+s.max)/2;results.push(`${i+1}. ${s.name||s.type} — ${hits}/${N} acertos (${(100*hits/N).toFixed(2)}%). Itens recebidos: ${quantity}; esperado ≈ ${expected.toFixed(1)}.`)});\n $('au40Results').textContent='Simulação determinística de '+N+' tentativas por origem (não altera inventário):\\n'+results.join('\\n');}\nfunction effectPreview(){\n const base=100;let lines=['Prévia simplificada sobre uma base hipotética de '+base+' pontos por atributo (não altera atributos oficiais).'];const accum={};\n for(const e of model.effects){const a=e.attribute==='custom'?e.customAttribute:e.attribute;let current=accum[a]??base;\n  if(e.condition||e.duration>0||e.interval>0||e.chance!==100){lines.push('! '+a+': gatilho, chance, duração ou condição exigem execução específica.');continue}\n  if(e.operation==='adicionar'||e.operation==='recuperar')current+=e.value;\n  else if(e.operation==='percentual')current+=current*e.value/100;\n  else if(e.operation==='multiplicar')current*=e.value;\n  else if(e.operation==='fixar')current=e.value;\n  accum[a]=current;lines.push('• '+a+': '+base+' → '+Number(current.toFixed(3))+' (gatilho '+e.trigger+')');\n }\n if(!model.effects.length)lines.push('Nenhum efeito cadastrado.');\n lines.push('Os valores reais, limites e aplicação temporal dependem do executor do Godot.');$('au40Results').textContent=lines.join('\\n');\n}\nfunction relationReport(){const id=$('v37IngId').value.trim();if(!id){$('au40Results').textContent='Preencha o ID para procurar relações.';return}\n let found=[];for(const r of state.recipes||[])if(JSON.stringify(r).includes('\"'+id+'\"'))found.push('Receita: '+(r.name||r.id||'sem nome'));\n for(const t of state.systemsV3?.loot||[])if((t.entries||[]).some(x=>x.itemId===id))found.push('Tabela de drop: '+(t.name||t.id));\n for(const sc of Object.values(state.screens||{})){if(JSON.stringify(sc).includes(id))found.push('Layout: '+(sc.name||sc.id||'tela'))}\n $('au40Results').textContent=found.length?'Referências encontradas:\\n'+[...new Set(found)].join('\\n'):'Nenhuma referência direta encontrada. Os módulos podem possuir vínculos declarativos não mapeados.';\n}\nfunction auditCatalog(){\n const errors=[],warnings=[],items=state.items||[],recipes=state.recipes||[],set";